/* works-v2.js — 暫定(V1流用)。工場完了後 build_data.py で置換 */
const WORKDATA_V2={"version":"placeholder-2026-08-26","categories":[{"id":"feeding","name":"飼養管理"},{"id":"hygiene","name":"衛生管理"},{"id":"breeding","name":"繁殖管理"},{"id":"farrowing","name":"分娩管理"},{"id":"facility","name":"施設管理"},{"id":"record","name":"記録管理"},{"id":"shipping","name":"出荷管理"}],"works":[{"id":"feeding-daily","category":"feeding","no":"No.11","name":"給餌","purposeShort":"成長・繁殖を安定させ、全頭がムラなく食べ、ムダな飼料を出さない","aspects":[{"id":"amount","name":"給与量の管理と個体・季節調整","kanten":"決められた給与量を守りつつ、豚の状態や季節に応じて過不足なく調整できるか。","levels":["決められた量を守らず目分量で与え、豚の状態や季節の違いを考えずに一律に給餌する。","指示があれば決められた量を与えられるが、季節や個体差に応じた調整は他者まかせで、過不足が出やすい。","指示があれば決められた量を守り、暑い時期や豚の状態に応じてある程度の増減ができる。","指示がなくても食い込みや季節を見て量を細かく加減し、食下量の低下があれば原因を探って対応する。","給与量が成長・繁殖に与える影響を理解し、体況・季節・ステージに合わせて最適化し、調整の考え方を新人に指導できる。"],"name_en":"Feed amount control with individual and seasonal adjustment","kanten_en":"Can they follow the prescribed feed amounts while adjusting appropriately for pig condition and season, without excess or shortage?","levels_en":["Ignores the prescribed amounts and feeds by eye, giving the same amount to all pigs regardless of condition or season.","With guidance, can give the prescribed amount, but leaves seasonal and individual adjustments to others, often causing excess or shortage.","With guidance, follows the prescribed amounts and can make some increases or decreases according to hot weather or pig condition.","Independently fine-tunes amounts based on feed intake and season, and investigates the cause when feed intake drops.","Understands how feed amounts affect growth and reproduction, optimizes them by body condition, season, and stage, and can teach new staff the principles of adjustment."],"name_vi":"Quản lý lượng thức ăn và điều chỉnh theo từng con, theo mùa","kanten_vi":"Có giữ đúng lượng thức ăn quy định, đồng thời điều chỉnh vừa đủ theo tình trạng lợn và theo mùa không.","levels_vi":["Không giữ lượng quy định, cho ăn theo ước lượng bằng mắt, cho ăn giống nhau mà không nghĩ đến tình trạng lợn hay mùa.","Nếu có chỉ dẫn thì cho ăn đúng lượng quy định, nhưng việc điều chỉnh theo mùa hay từng con thì phó mặc cho người khác, dễ bị thừa hoặc thiếu.","Nếu có chỉ dẫn thì giữ đúng lượng quy định, và có thể tăng giảm phần nào theo mùa nóng hoặc tình trạng lợn.","Không cần chỉ dẫn cũng nhìn mức ăn và mùa để điều chỉnh lượng một cách tỉ mỉ; nếu lợn ăn ít đi thì tìm nguyên nhân và xử lý.","Hiểu lượng thức ăn ảnh hưởng đến tăng trưởng và sinh sản, tối ưu theo thể trạng, mùa và giai đoạn, và có thể hướng dẫn người mới cách điều chỉnh."],"name_id":"Pengelolaan jumlah pakan dan penyesuaian per individu dan musim","kanten_id":"Apakah bisa mengikuti jumlah pakan yang ditentukan, dan menyesuaikannya dengan tepat sesuai kondisi babi dan musim.","levels_id":["Tidak mengikuti jumlah yang ditentukan, memberi pakan dengan kira-kira saja, dan memberi jumlah yang sama tanpa melihat kondisi babi atau musim.","Jika ada instruksi bisa memberi jumlah yang ditentukan, tetapi penyesuaian menurut musim atau perbedaan individu diserahkan ke orang lain, sehingga sering kelebihan atau kekurangan.","Jika ada instruksi, bisa mengikuti jumlah yang ditentukan dan bisa menambah atau mengurangi sedikit sesuai musim panas atau kondisi babi.","Tanpa instruksi pun, bisa mengatur jumlah pakan dengan teliti sambil melihat nafsu makan dan musim, dan jika konsumsi pakan turun, mencari penyebabnya lalu menanganinya.","Memahami pengaruh jumlah pakan terhadap pertumbuhan dan reproduksi, mengoptimalkannya sesuai kondisi tubuh, musim, dan tahap produksi, serta bisa mengajari karyawan baru cara berpikir penyesuaiannya."]},{"id":"residue-water","name":"残餌と給水の確認","kanten":"残餌の有無・変質と、給水器の流量を毎回確認し、飲水不足や飼料ロスを防げるか。","levels":["残餌や給水器の不具合を確認せず、飼料ロスや飲水不足を放置する。高温期の変質・カビにも気づかない。","指示があれば残餌を片づけるが、給水器の流量確認や槽内飼料の傷みの点検に漏れが多い。","指示があれば残餌を確認して片づけ、給水器から水が出ているかを確かめられる。","指示がなくても毎回残餌の量と傷みを確かめ、給水器の流量を点検し、飲水不足による食い込み低下を防ぐ。","残餌量・飲水量を給餌量の見直しに結びつけ、高温期の変質対策まで判断し、確認の要点を新人に指導できる。"],"name_en":"Checking leftover feed and water supply","kanten_en":"Can they check for leftover feed, spoilage, and drinker flow rate at every feeding to prevent water shortage and feed loss?","levels_en":["Does not check leftover feed or drinker problems, leaving feed loss and water shortage unaddressed; fails to notice spoilage or mold in hot weather.","With guidance, clears leftover feed, but often misses checking drinker flow rates and spoiled feed in the trough.","With guidance, checks and clears leftover feed and can confirm that water comes out of the drinkers.","Independently checks the amount and condition of leftover feed at every feeding, inspects drinker flow rates, and prevents reduced feed intake caused by water shortage.","Links leftover feed and water intake to feed amount reviews, makes decisions on spoilage countermeasures in hot weather, and can teach new staff the key checkpoints."],"name_vi":"Kiểm tra thức ăn thừa và nước uống","kanten_vi":"Mỗi lần có kiểm tra thức ăn thừa, thức ăn bị hỏng và lưu lượng núm uống nước, để tránh lợn thiếu nước và lãng phí thức ăn không.","levels_vi":["Không kiểm tra thức ăn thừa hay núm uống nước hỏng, bỏ mặc lãng phí thức ăn và thiếu nước. Mùa nóng thức ăn hỏng, mốc cũng không nhận ra.","Nếu có chỉ dẫn thì dọn thức ăn thừa, nhưng hay bỏ sót việc kiểm tra lưu lượng nước và thức ăn hỏng trong máng.","Nếu có chỉ dẫn thì kiểm tra và dọn thức ăn thừa, xác nhận được nước có chảy ra từ núm uống không.","Không cần chỉ dẫn cũng kiểm tra lượng và độ hỏng của thức ăn thừa mỗi lần, kiểm tra lưu lượng núm uống, phòng lợn ăn ít do thiếu nước.","Biết dùng lượng thức ăn thừa và lượng nước uống để xem lại lượng cho ăn, biết cách chống thức ăn hỏng mùa nóng, và có thể hướng dẫn người mới các điểm cần kiểm tra."],"name_id":"Pemeriksaan sisa pakan dan air minum","kanten_id":"Apakah setiap kali memeriksa ada tidaknya sisa pakan dan kerusakannya serta aliran air di nipple, sehingga bisa mencegah kekurangan air minum dan pemborosan pakan.","levels_id":["Tidak memeriksa sisa pakan atau kerusakan nipple air minum, membiarkan pakan terbuang dan babi kekurangan air. Tidak sadar pakan rusak atau berjamur di musim panas.","Jika ada instruksi bisa membereskan sisa pakan, tetapi sering lupa memeriksa aliran air nipple dan kerusakan pakan di dalam tempat pakan.","Jika ada instruksi, bisa memeriksa dan membereskan sisa pakan, serta memastikan air keluar dari nipple air minum.","Tanpa instruksi pun, setiap kali memeriksa jumlah dan kerusakan sisa pakan, memeriksa aliran air nipple, dan mencegah turunnya nafsu makan karena kekurangan air minum.","Menghubungkan jumlah sisa pakan dan konsumsi air dengan peninjauan jumlah pakan, bisa memutuskan langkah pencegahan pakan rusak di musim panas, dan bisa mengajari karyawan baru poin-poin pemeriksaannya."]}],"gyomu":"11","name_en":"Feeding","purposeShort_en":"Stabilize growth and reproduction, ensure all pigs eat evenly, and avoid feed waste","name_vi":"Cho ăn","purposeShort_vi":"Giúp lợn lớn và sinh sản ổn định, cả đàn ăn đều nhau, không lãng phí thức ăn","name_id":"Pemberian pakan","purposeShort_id":"Menstabilkan pertumbuhan dan reproduksi, semua babi makan merata, tidak ada pakan terbuang"},{"id":"feed-adjust","category":"feeding","no":"No.02","name":"エサ調整","purposeShort":"BCS・生理ステージに応じて栄養過不足を防ぎ、繁殖成績を高める","aspects":[{"id":"stage-timing","name":"ステージ・時期に合わせた調整","kanten":"妊娠・泌乳などの生理ステージと正しい時期を見て、適切な段階で給与を変えられるか。","levels":["ステージや時期を考えず、いつも同じ与え方をする。切り替えの時期を外しても気にしない。","指示があれば切り替えられるが、ステージ移行の時期が遅れがちで、判断は他者まかせ。","指示があれば生理ステージに応じた時期にエサ量を切り替えられる。","指示がなくてもステージの移行を見越して適切な時期に調整し、増量中は餌残しに注意する。","不適切な時期の調整が逆効果になることを理解し、ステージごとに最適な時期と量を判断し、新人に指導できる。"],"name_en":"Adjustment by stage and timing","kanten_en":"Can they observe physiological stages such as gestation and lactation and change feeding at the appropriate step and correct timing?","levels_en":["Feeds the same way at all times without considering stage or timing, and does not care about missing the switch-over timing.","With guidance, can switch feed, but stage transitions tend to be late and judgment is left to others.","With guidance, can switch feed amounts at the timing appropriate to the physiological stage.","Independently anticipates stage transitions, adjusts at the appropriate timing, and watches for feed refusals during increases.","Understands that adjustment at the wrong timing can backfire, judges the optimal timing and amount for each stage, and can teach new staff."],"name_vi":"Điều chỉnh theo giai đoạn và thời điểm","kanten_vi":"Có nhìn giai đoạn sinh lý như mang thai, nuôi con và đúng thời điểm, để thay đổi lượng cho ăn ở bước phù hợp không.","levels_vi":["Không nghĩ đến giai đoạn hay thời điểm, lúc nào cũng cho ăn giống nhau. Lỡ thời điểm chuyển đổi cũng không quan tâm.","Nếu có chỉ dẫn thì chuyển đổi được, nhưng hay bị trễ thời điểm chuyển giai đoạn, việc phán đoán phó mặc cho người khác.","Nếu có chỉ dẫn thì chuyển đổi lượng thức ăn đúng thời điểm theo giai đoạn sinh lý.","Không cần chỉ dẫn cũng nhìn trước việc chuyển giai đoạn để điều chỉnh đúng lúc, khi tăng lượng thì chú ý thức ăn bị bỏ thừa.","Hiểu rằng điều chỉnh sai thời điểm sẽ phản tác dụng, biết phán đoán thời điểm và lượng tốt nhất cho từng giai đoạn, và có thể hướng dẫn người mới."],"name_id":"Penyesuaian sesuai tahap dan waktu","kanten_id":"Apakah bisa mengubah pemberian pakan pada tahap yang tepat, dengan melihat tahap fisiologis seperti bunting dan menyusui serta waktu yang benar.","levels_id":["Selalu memberi pakan dengan cara yang sama tanpa memikirkan tahap atau waktu. Tidak peduli walau melewatkan waktu penggantian pakan.","Jika ada instruksi bisa mengganti pakan, tetapi waktu perpindahan tahap sering terlambat dan keputusan diserahkan ke orang lain.","Jika ada instruksi, bisa mengganti jumlah pakan pada waktu yang sesuai dengan tahap fisiologis.","Tanpa instruksi pun, bisa mengantisipasi perpindahan tahap dan menyesuaikan pada waktu yang tepat, serta memperhatikan sisa pakan saat jumlah pakan sedang dinaikkan.","Memahami bahwa penyesuaian pada waktu yang salah bisa berakibat sebaliknya, bisa menentukan waktu dan jumlah terbaik untuk tiap tahap, dan bisa mengajari karyawan baru."]},{"id":"individual","name":"個体差・体重に応じた加減","kanten":"体重やBCSを見て一頭ごとに給与を加減し、日齢だけで一律に判断しないか。","levels":["個体差を見ずに全頭一律に与え、痩せ・過肥があっても気づかない。","指示があれば極端な個体には対応するが、体重を確かめず日齢だけで切り替えることが多い。","指示があれば体重やBCSを確かめ、痩せ・過肥の個体を見分けられる。","指示がなくても一頭ごとに体重・BCSを見て給与量を加減し、痩せすぎ・太りすぎを防ぐ。","体重・BCS・産次を総合して細かく最適化し、個体に応じた加減の目安を新人に指導できる。"],"name_en":"Adjustment by individual variation and body weight","kanten_en":"Do they adjust feeding for each pig based on body weight and BCS, rather than judging uniformly by age in days alone?","levels_en":["Feeds all pigs uniformly without looking at individual differences, and fails to notice thin or over-conditioned animals.","With guidance, handles extreme individuals, but often switches feed based on age in days alone without checking body weight.","With guidance, checks body weight and BCS and can identify thin and over-conditioned individuals.","Independently adjusts feed amounts for each pig based on body weight and BCS, preventing animals from becoming too thin or too fat.","Fine-tunes feeding by integrating body weight, BCS, and parity, and can teach new staff the guidelines for individual adjustment."],"name_vi":"Tăng giảm theo từng con và theo cân nặng","kanten_vi":"Có nhìn cân nặng và BCS để tăng giảm lượng cho từng con, không phán đoán đồng loạt chỉ theo tuổi ngày không.","levels_vi":["Không nhìn sự khác nhau giữa các con, cho ăn đồng loạt như nhau, có con gầy hay quá béo cũng không nhận ra.","Nếu có chỉ dẫn thì xử lý được những con quá gầy hoặc quá béo rõ rệt, nhưng thường không kiểm tra cân nặng mà chỉ chuyển đổi theo tuổi ngày.","Nếu có chỉ dẫn thì kiểm tra cân nặng và BCS, phân biệt được con gầy và con quá béo.","Không cần chỉ dẫn cũng nhìn cân nặng và BCS của từng con để tăng giảm lượng thức ăn, phòng lợn quá gầy hoặc quá béo.","Tổng hợp cân nặng, BCS và lứa đẻ để tối ưu tỉ mỉ, và có thể hướng dẫn người mới tiêu chuẩn tăng giảm theo từng con."],"name_id":"Penyesuaian menurut perbedaan individu dan berat badan","kanten_id":"Apakah menambah atau mengurangi pakan per ekor dengan melihat berat badan dan BCS, tanpa memutuskan seragam hanya berdasarkan umur (hari).","levels_id":["Memberi pakan seragam ke semua babi tanpa melihat perbedaan individu, dan tidak sadar walau ada babi yang kurus atau terlalu gemuk.","Jika ada instruksi bisa menangani individu yang ekstrem, tetapi sering mengganti pakan hanya berdasarkan umur (hari) tanpa memeriksa berat badan.","Jika ada instruksi, bisa memeriksa berat badan dan BCS, serta membedakan babi yang kurus dan yang terlalu gemuk.","Tanpa instruksi pun, bisa menambah atau mengurangi jumlah pakan per ekor dengan melihat berat badan dan BCS, sehingga mencegah babi terlalu kurus atau terlalu gemuk.","Bisa mengoptimalkan pakan secara rinci dengan mempertimbangkan berat badan, BCS, dan paritas, serta bisa mengajari karyawan baru patokan penyesuaian per individu."]}],"gyomu":"02","name_en":"Feed adjustment","purposeShort_en":"Prevent nutritional excess or deficiency according to BCS and physiological stage, and improve reproductive performance","name_vi":"Điều chỉnh lượng thức ăn","purposeShort_vi":"Tránh thừa hoặc thiếu dinh dưỡng theo BCS (điểm thể trạng) và giai đoạn sinh lý, nâng cao thành tích sinh sản","name_id":"Penyesuaian Jumlah Pakan","purposeShort_id":"Mencegah kelebihan atau kekurangan gizi sesuai BCS dan tahap fisiologis, meningkatkan hasil reproduksi"},{"id":"feed-adjust-detail","category":"feeding","no":"No.38","name":"エサ調整（詳細）","purposeShort":"体重・BCS・産次を見て調整し、痩せ・過肥を防ぎ農場目標に合わせる","aspects":[{"id":"gradual","name":"段階的な増減","kanten":"エサ量を急に変えず少しずつ増減し、急な変化による食欲低下を防げるか。","levels":["エサ量を一気に増減し、食欲低下を招いても気にしない。","指示があれば増減するが、変化幅が大きく食欲を落とすことがある。","指示があればエサ量を少しずつ増減できる。","指示がなくても食い込みを見ながら段階的に増減し、急な変化を避ける。","急な増減が消化器や食欲に与える影響を理解し、段階的な調整幅を判断して新人に指導できる。"],"name_en":"Gradual increases and decreases","kanten_en":"Can they change feed amounts gradually rather than abruptly, preventing appetite loss caused by sudden changes?","levels_en":["Increases or decreases feed all at once and does not care even when this causes appetite loss.","With guidance, adjusts feed, but the changes are too large and sometimes reduce appetite.","With guidance, can increase or decrease feed amounts little by little.","Independently adjusts feed in gradual steps while watching feed intake, avoiding sudden changes.","Understands how sudden changes affect the digestive system and appetite, judges appropriate step sizes for adjustment, and can teach new staff."],"name_vi":"Tăng giảm từng bước","kanten_vi":"Có tăng giảm lượng thức ăn từng chút một, không thay đổi đột ngột, để tránh lợn chán ăn do thay đổi nhanh không.","levels_vi":["Tăng giảm lượng thức ăn một lúc quá nhiều, làm lợn chán ăn cũng không quan tâm.","Nếu có chỉ dẫn thì tăng giảm được, nhưng mức thay đổi lớn, có khi làm lợn chán ăn.","Nếu có chỉ dẫn thì có thể tăng giảm lượng thức ăn từng chút một.","Không cần chỉ dẫn cũng vừa nhìn mức ăn vừa tăng giảm từng bước, tránh thay đổi đột ngột.","Hiểu việc tăng giảm đột ngột ảnh hưởng đến tiêu hóa và sự thèm ăn, biết phán đoán mức điều chỉnh từng bước và có thể hướng dẫn người mới."],"name_id":"Penambahan dan pengurangan bertahap","kanten_id":"Apakah bisa menambah atau mengurangi jumlah pakan sedikit demi sedikit, tidak mengubahnya mendadak, sehingga mencegah turunnya nafsu makan karena perubahan tiba-tiba.","levels_id":["Menambah atau mengurangi jumlah pakan sekaligus, dan tidak peduli walau menyebabkan nafsu makan turun.","Jika ada instruksi bisa menambah atau mengurangi, tetapi perubahannya terlalu besar sehingga kadang menurunkan nafsu makan.","Jika ada instruksi, bisa menambah atau mengurangi jumlah pakan sedikit demi sedikit.","Tanpa instruksi pun, menambah atau mengurangi secara bertahap sambil melihat nafsu makan, dan menghindari perubahan mendadak.","Memahami pengaruh perubahan mendadak terhadap pencernaan dan nafsu makan, bisa menentukan besarnya penyesuaian bertahap, dan bisa mengajari karyawan baru."]},{"id":"parity-season","name":"産次・季節への配慮","kanten":"産次の違いや夏季の食い込み低下を考え、量だけでなく回数や時間帯でも対応できるか。","levels":["産次の違いや季節を無視して与え、夏季の食い込み低下を量の増加だけで対応し残餌を増やす。","指示があれば産次や季節をある程度考えるが、多産系母豚の泌乳量増大への対応に漏れが多い。","指示があれば産次や季節を考えて量を調整できる。","指示がなくても産次差・多産系の泌乳量を考え、夏季は給与時間や回数を工夫して食下量を確保する。","産次・泌乳量・季節を総合して給与設計を最適化し、残餌を抑える工夫を新人に指導できる。"],"name_en":"Consideration of parity and season","kanten_en":"Can they account for parity differences and reduced summer feed intake, responding not only with amount but also with feeding frequency and timing?","levels_en":["Ignores parity differences and season, responds to reduced summer intake only by increasing amounts, and increases leftover feed.","With guidance, gives some consideration to parity and season, but often fails to address the increased milk production of hyperprolific sows.","With guidance, can adjust amounts with parity and season in mind.","Independently considers parity differences and the milk output of hyperprolific sows, and secures feed intake in summer by adjusting feeding times and frequency.","Optimizes the feeding plan by integrating parity, milk production, and season, and can teach new staff techniques for minimizing leftover feed."],"name_vi":"Chú ý đến lứa đẻ và mùa","kanten_vi":"Có nghĩ đến sự khác nhau theo lứa đẻ và việc lợn ăn ít vào mùa hè, xử lý không chỉ bằng lượng mà cả số bữa và giờ cho ăn không.","levels_vi":["Bỏ qua lứa đẻ và mùa, mùa hè lợn ăn ít thì chỉ tăng lượng, làm tăng thức ăn thừa.","Nếu có chỉ dẫn thì có nghĩ phần nào đến lứa đẻ và mùa, nhưng hay bỏ sót việc xử lý khi lợn nái nhiều con tiết sữa nhiều hơn.","Nếu có chỉ dẫn thì điều chỉnh được lượng theo lứa đẻ và mùa.","Không cần chỉ dẫn cũng nghĩ đến sự khác nhau theo lứa đẻ và lượng sữa của nái nhiều con; mùa hè thì thay đổi giờ và số bữa cho ăn để lợn ăn đủ.","Tổng hợp lứa đẻ, lượng sữa và mùa để tối ưu cách cho ăn, và có thể hướng dẫn người mới cách giảm thức ăn thừa."],"name_id":"Perhatian pada paritas dan musim","kanten_id":"Apakah mempertimbangkan perbedaan paritas dan turunnya nafsu makan di musim panas, dan bisa menanganinya bukan hanya dengan jumlah tetapi juga dengan frekuensi dan jam pemberian.","levels_id":["Memberi pakan tanpa peduli perbedaan paritas atau musim, dan mengatasi turunnya nafsu makan di musim panas hanya dengan menambah jumlah sehingga sisa pakan bertambah.","Jika ada instruksi bisa sedikit mempertimbangkan paritas dan musim, tetapi sering lalai menangani produksi susu yang besar pada induk babi tipe prolifik (banyak anak).","Jika ada instruksi, bisa menyesuaikan jumlah pakan dengan mempertimbangkan paritas dan musim.","Tanpa instruksi pun, mempertimbangkan perbedaan paritas dan produksi susu induk tipe prolifik, dan di musim panas mengatur jam serta frekuensi pemberian agar konsumsi pakan terjaga.","Bisa mengoptimalkan rancangan pemberian pakan dengan mempertimbangkan paritas, produksi susu, dan musim secara menyeluruh, serta bisa mengajari karyawan baru cara menekan sisa pakan."]}],"gyomu":"38","name_en":"Feed adjustment (advanced)","purposeShort_en":"Adjust based on body weight, BCS, and parity to prevent thinness and over-conditioning, in line with farm targets","name_vi":"Điều chỉnh thức ăn (chi tiết)","purposeShort_vi":"Nhìn cân nặng, BCS và lứa đẻ để điều chỉnh, tránh lợn gầy hoặc quá béo, đạt mục tiêu của trại","name_id":"Penyesuaian pakan (rinci)","purposeShort_id":"Menyesuaikan dengan melihat berat badan, BCS, dan paritas, mencegah babi kurus atau terlalu gemuk, sesuai target peternakan"},{"id":"feed-recovery","category":"feeding","no":"No.16","name":"エサ回収","purposeShort":"病気・腐敗リスクを減らし飼料コストを削減し、給餌量見直しに役立てる","aspects":[{"id":"spoilage","name":"変質餌の見分けと短時間回収","kanten":"カビ・腐敗した残餌を再利用せず、回収・保管を短時間で行い変質を防げるか。","levels":["カビや腐敗した残餌を再利用し、回収後も常温で長時間放置して変質させる。","指示があれば回収するが、変質の見分けが甘く、放置時間が長くなりがち。","指示があればカビ・腐敗した残餌を見分けて分け、短時間で回収できる。","指示がなくても変質を見分けて再利用せず、回収・保管を短時間で済ませる。","変質が病気・腐敗リスクにつながることを理解し、回収の手順を最適化して新人に指導できる。"],"name_en":"Identifying spoiled feed and quick recovery","kanten_en":"Can they avoid reusing moldy or rotten leftover feed and complete recovery and storage quickly to prevent spoilage?","levels_en":["Reuses moldy or rotten leftover feed and leaves recovered feed at room temperature for long periods, letting it spoil.","With guidance, recovers feed, but is poor at identifying spoilage and tends to leave feed standing too long.","With guidance, can identify and separate moldy or rotten leftover feed and recover it quickly.","Independently identifies spoiled feed, avoids reusing it, and completes recovery and storage in a short time.","Understands that spoilage leads to disease and decay risk, optimizes the recovery procedure, and can teach new staff."],"name_vi":"Phân biệt thức ăn hỏng và thu gom nhanh","kanten_vi":"Có tránh dùng lại thức ăn thừa bị mốc, thối, và thu gom, cất giữ trong thời gian ngắn để tránh hỏng thêm không.","levels_vi":["Dùng lại thức ăn thừa bị mốc hoặc thối; sau khi thu gom lại để lâu ở nhiệt độ thường làm hỏng thêm.","Nếu có chỉ dẫn thì thu gom, nhưng phân biệt thức ăn hỏng còn kém, hay để lâu.","Nếu có chỉ dẫn thì phân biệt và tách được thức ăn thừa bị mốc, thối, thu gom trong thời gian ngắn.","Không cần chỉ dẫn cũng phân biệt thức ăn hỏng và không dùng lại, thu gom và cất giữ nhanh gọn.","Hiểu thức ăn hỏng dẫn đến nguy cơ bệnh và thối rữa, biết tối ưu quy trình thu gom và có thể hướng dẫn người mới."],"name_id":"Mengenali pakan rusak dan pengumpulan cepat","kanten_id":"Apakah tidak memakai ulang sisa pakan yang berjamur atau busuk, dan bisa mengumpulkan serta menyimpannya dalam waktu singkat agar tidak rusak.","levels_id":["Memakai ulang sisa pakan yang berjamur atau busuk, dan setelah dikumpulkan dibiarkan lama di suhu ruang sampai rusak.","Jika ada instruksi bisa mengumpulkan, tetapi kurang teliti mengenali pakan rusak dan cenderung membiarkannya terlalu lama.","Jika ada instruksi, bisa mengenali dan memisahkan sisa pakan yang berjamur atau busuk, serta mengumpulkannya dalam waktu singkat.","Tanpa instruksi pun, mengenali pakan rusak dan tidak memakainya ulang, serta menyelesaikan pengumpulan dan penyimpanan dalam waktu singkat.","Memahami bahwa pakan rusak berhubungan dengan risiko penyakit dan pembusukan, bisa mengoptimalkan urutan pengumpulan, dan bisa mengajari karyawan baru."]},{"id":"dedicated-tools","name":"専用容器・器具の管理","kanten":"回収用の容器・器具を専用にして洗い、他用途転用や豚房間共用による交差汚染を防げるか。","levels":["他用途のバケツを転用し、器具を豚房間で使い回して交差汚染・病原伝播を招く。","指示があれば専用容器を使うが、洗浄や豚房ごとの使い分けに漏れがある。","指示があれば回収用の専用容器・器具を使い、使用後に洗える。","指示がなくても専用容器を清潔に保ち、豚房間の共用を避けて交差汚染を防ぐ。","交差汚染・病原伝播の仕組みを理解し、容器・器具の管理ルールを新人に指導できる。"],"name_en":"Management of dedicated containers and tools","kanten_en":"Can they keep recovery containers and tools dedicated and washed, preventing cross-contamination from repurposing or sharing between pens?","levels_en":["Repurposes buckets from other uses and shares tools between pens, causing cross-contamination and pathogen spread.","With guidance, uses dedicated containers, but is inconsistent about washing and keeping tools separate per pen.","With guidance, uses dedicated recovery containers and tools and can wash them after use.","Independently keeps dedicated containers clean and avoids sharing between pens, preventing cross-contamination.","Understands the mechanisms of cross-contamination and pathogen spread, and can teach new staff the rules for managing containers and tools."],"name_vi":"Quản lý thùng và dụng cụ chuyên dùng","kanten_vi":"Có dùng thùng và dụng cụ chuyên cho việc thu gom, rửa sạch sau khi dùng, tránh lây nhiễm chéo do dùng chung giữa các ô chuồng hoặc dùng sang việc khác không.","levels_vi":["Lấy xô của việc khác sang dùng, dùng chung dụng cụ giữa các ô chuồng lợn, gây lây nhiễm chéo và lan truyền mầm bệnh.","Nếu có chỉ dẫn thì dùng thùng chuyên dùng, nhưng có bỏ sót việc rửa và việc dùng riêng theo từng ô chuồng.","Nếu có chỉ dẫn thì dùng thùng và dụng cụ chuyên cho thu gom, rửa được sau khi dùng.","Không cần chỉ dẫn cũng giữ thùng chuyên dùng sạch sẽ, tránh dùng chung giữa các ô chuồng để phòng lây nhiễm chéo.","Hiểu cơ chế lây nhiễm chéo và lan truyền mầm bệnh, và có thể hướng dẫn người mới quy tắc quản lý thùng, dụng cụ."],"name_id":"Pengelolaan wadah dan alat khusus","kanten_id":"Apakah memakai wadah dan alat khusus untuk pengumpulan lalu mencucinya, sehingga mencegah kontaminasi silang karena dipakai untuk keperluan lain atau dipakai bergantian antar petak kandang.","levels_id":["Memakai ember bekas keperluan lain, dan memakai alat bergantian antar petak kandang sehingga menyebabkan kontaminasi silang dan penyebaran bibit penyakit.","Jika ada instruksi bisa memakai wadah khusus, tetapi sering lalai mencuci atau memisahkan pemakaian per petak kandang.","Jika ada instruksi, bisa memakai wadah dan alat khusus untuk pengumpulan, serta mencucinya setelah dipakai.","Tanpa instruksi pun, menjaga wadah khusus tetap bersih dan menghindari pemakaian bergantian antar petak kandang sehingga mencegah kontaminasi silang.","Memahami mekanisme kontaminasi silang dan penyebaran bibit penyakit, dan bisa mengajari karyawan baru aturan pengelolaan wadah dan alat."]}],"gyomu":"16","name_en":"Feed recovery","purposeShort_en":"Reduce disease and spoilage risk, cut feed costs, and inform feed amount reviews","name_vi":"Thu gom thức ăn thừa","purposeShort_vi":"Giảm nguy cơ bệnh và thức ăn thối hỏng, giảm chi phí thức ăn, giúp xem lại lượng cho ăn","name_id":"Mengumpulkan sisa pakan","purposeShort_id":"Mengurangi risiko penyakit dan pembusukan, menekan biaya pakan, dan membantu peninjauan jumlah pakan"},{"id":"nursing-feed","category":"feeding","no":"No.43","name":"えつけ（哺乳期給餌）","purposeShort":"泌乳量を確保し、子豚の離乳頭数・体重を高め、母豚の削痩を防ぐ","aspects":[{"id":"gradual-lactation","name":"分娩後の段階的増給と暑熱対応","kanten":"分娩後は少量から段階的に増やし、暑熱時は回数を増やして食下量を確保できるか。","levels":["分娩後にいきなり多く与える、または暑熱時に回数を増やさず食下量を落とす。","指示があれば段階的に増やすが、暑熱時の回数調整や水の確保に漏れがある。","指示があれば分娩後は少量から段階的に増やし、水が飲める状態を保てる。","指示がなくても食い込みを見て段階的に増やし、暑熱時は回数を増やして食下量を確保する。","泌乳量と母豚の削痩・次回繁殖の関係を理解し、給餌設計を最適化して新人に指導できる。"],"name_en":"Gradual increase after farrowing and heat stress response","kanten_en":"Can they increase feed gradually from small amounts after farrowing, and increase feeding frequency in hot weather to maintain feed intake?","levels_en":["Gives large amounts right after farrowing, or fails to increase feeding frequency in hot weather, reducing feed intake.","With guidance, increases feed gradually, but is inconsistent about adjusting frequency in hot weather and securing water.","With guidance, increases feed gradually from small amounts after farrowing and keeps water available.","Independently increases feed step by step while watching intake, and raises feeding frequency in hot weather to maintain feed intake.","Understands the relationship between milk production, sow body condition loss, and the next breeding cycle, optimizes the feeding plan, and can teach new staff."],"name_vi":"Tăng dần thức ăn sau đẻ và ứng phó nắng nóng","kanten_vi":"Sau khi đẻ có cho ăn từ ít rồi tăng dần từng bước, khi nắng nóng có tăng số bữa để lợn ăn đủ không.","levels_vi":["Sau khi đẻ cho ăn nhiều ngay một lúc, hoặc khi nắng nóng không tăng số bữa làm lợn ăn ít đi.","Nếu có chỉ dẫn thì tăng dần được, nhưng có bỏ sót việc điều chỉnh số bữa khi nắng nóng và việc bảo đảm nước uống.","Nếu có chỉ dẫn thì sau khi đẻ cho ăn từ ít rồi tăng dần, giữ được trạng thái lợn luôn uống được nước.","Không cần chỉ dẫn cũng nhìn mức ăn để tăng dần từng bước, khi nắng nóng thì tăng số bữa để lợn ăn đủ.","Hiểu quan hệ giữa lượng sữa với việc nái gầy sút và lứa sinh sản tiếp theo, biết tối ưu cách cho ăn và có thể hướng dẫn người mới."],"name_id":"Penambahan bertahap setelah melahirkan dan penanganan cuaca panas","kanten_id":"Apakah setelah melahirkan menambah pakan bertahap mulai dari sedikit, dan saat cuaca panas menambah frekuensi pemberian agar konsumsi pakan terjaga.","levels_id":["Langsung memberi banyak pakan setelah melahirkan, atau saat cuaca panas tidak menambah frekuensi sehingga konsumsi pakan turun.","Jika ada instruksi bisa menambah bertahap, tetapi sering lalai mengatur frekuensi saat cuaca panas dan memastikan air minum.","Jika ada instruksi, bisa menambah pakan bertahap mulai dari sedikit setelah melahirkan, dan menjaga agar induk selalu bisa minum air.","Tanpa instruksi pun, menambah pakan bertahap sambil melihat nafsu makan, dan saat cuaca panas menambah frekuensi pemberian agar konsumsi pakan terjaga.","Memahami hubungan produksi susu dengan menurunnya kondisi tubuh induk dan reproduksi berikutnya, bisa mengoptimalkan rancangan pemberian pakan, dan bisa mengajari karyawan baru."]},{"id":"colostrum-balance","name":"産子数と乳頭数のバランス管理","kanten":"産子数と乳頭数の差を確認し、初乳未摂取子豚や泌乳不全乳頭を見落とさず対応できるか。","levels":["産子数と乳頭数の差を確認せず、初乳を飲めない子豚や泌乳不全の乳頭を放置する。","指示があれば確認するが、分割授乳や弱い子豚の固定に漏れが多い。","指示があれば産子数と乳頭数の差を確かめ、初乳を飲めていない子豚に気づける。","指示がなくても分割授乳を行い、泌乳不全乳頭や発育格差に気づいて弱い子豚を手当てする。","初乳・泌乳と発育格差の関係を理解し、里子や分割授乳の判断を最適化して新人に指導できる。"],"name_en":"Balancing litter size and functional teats","kanten_en":"Can they check the gap between litter size and teat count, and respond without overlooking piglets that missed colostrum or non-functional teats?","levels_en":["Does not check the gap between litter size and teat count, leaving piglets without colostrum and non-lactating teats unattended.","With guidance, checks, but often fails to carry out split suckling or place weak piglets on teats.","With guidance, checks the gap between litter size and teat count and can notice piglets that are not getting colostrum.","Independently performs split suckling, notices non-functional teats and growth disparities, and cares for weak piglets.","Understands the relationship between colostrum, lactation, and growth disparity, optimizes decisions on cross-fostering and split suckling, and can teach new staff."],"name_vi":"Quản lý cân bằng số con đẻ ra và số vú","kanten_vi":"Có kiểm tra chênh lệch giữa số con đẻ ra và số vú, không bỏ sót lợn con chưa bú sữa đầu và vú không tiết sữa, và xử lý được không.","levels_vi":["Không kiểm tra chênh lệch giữa số con đẻ ra và số vú, bỏ mặc lợn con không bú được sữa đầu và vú không tiết sữa.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót việc cho bú theo nhóm chia lượt và việc giữ chỗ bú cho con yếu.","Nếu có chỉ dẫn thì kiểm tra chênh lệch giữa số con đẻ ra và số vú, nhận ra được lợn con chưa bú được sữa đầu.","Không cần chỉ dẫn cũng cho bú theo nhóm chia lượt, nhận ra vú không tiết sữa và sự chênh lệch phát triển, chăm sóc con yếu.","Hiểu quan hệ giữa sữa đầu, tiết sữa và chênh lệch phát triển, biết tối ưu việc ghép bầy và cho bú chia lượt, và có thể hướng dẫn người mới."],"name_id":"Pengelolaan keseimbangan jumlah anak dan jumlah puting","kanten_id":"Apakah memeriksa selisih jumlah anak yang lahir dengan jumlah puting, dan tidak melewatkan anak babi yang belum minum kolostrum atau puting yang tidak mengeluarkan susu.","levels_id":["Tidak memeriksa selisih jumlah anak dan jumlah puting, membiarkan anak babi yang tidak bisa minum kolostrum atau puting yang tidak mengeluarkan susu.","Jika ada instruksi bisa memeriksa, tetapi sering lalai melakukan menyusui bergantian (split suckling) atau memegangi anak yang lemah ke puting.","Jika ada instruksi, bisa memeriksa selisih jumlah anak dan jumlah puting, serta menyadari anak babi yang belum minum kolostrum.","Tanpa instruksi pun, melakukan menyusui bergantian, menyadari puting yang tidak mengeluarkan susu dan perbedaan pertumbuhan, serta menolong anak babi yang lemah.","Memahami hubungan kolostrum dan produksi susu dengan perbedaan pertumbuhan, bisa mengoptimalkan keputusan titip anak ke induk lain dan menyusui bergantian, dan bisa mengajari karyawan baru."]}],"gyomu":"43","name_en":"Lactation feeding","purposeShort_en":"Secure milk production, increase the number and weight of weaned piglets, and prevent sow body condition loss","name_vi":"Tập cho ăn (cho ăn thời kỳ nuôi con bú sữa)","purposeShort_vi":"Bảo đảm lượng sữa, tăng số con và cân nặng lúc cai sữa, tránh lợn nái bị gầy sút","name_id":"Melatih makan (pemberian pakan masa menyusui)","purposeShort_id":"Menjaga produksi susu, meningkatkan jumlah dan berat anak babi saat sapih, dan mencegah induk babi menjadi kurus"},{"id":"grow-handover","category":"feeding","no":"No.27","name":"育成受け","purposeShort":"育成管理への引き継ぎを確実に行う","aspects":[{"id":"info-handover","name":"個体情報の引き継ぎ","kanten":"個体情報を漏れなく伝え、受入れ先が管理を継続できる形で引き継げるか。","levels":["個体情報を伝えず、引き継ぎ漏れがあっても気にしない。","指示されれば伝えるが、内容が不十分で伝達漏れが多い。","指示された個体情報をひと通り伝えて引き継げる。","指示がなくても必要な個体情報を整理し、受入れ先に伝わる形で引き継ぐ。","引き継ぎで漏れやすい情報を把握し、確実な引き継ぎの方法を新人に指導できる。"],"name_en":"Handover of individual animal information","kanten_en":"Can they pass on individual animal information without omissions, in a form that lets the receiving side continue management?","levels_en":["Does not pass on individual animal information and does not care about handover omissions.","Passes information when instructed, but the content is insufficient with many omissions.","With guidance, can pass on the specified individual animal information and complete the handover.","Independently organizes the necessary individual information and hands it over in a form the receiving side can use.","Knows which information is easily missed in handovers and can teach new staff reliable handover methods."],"name_vi":"Bàn giao thông tin từng con","kanten_vi":"Có truyền đạt đầy đủ thông tin từng con, bàn giao theo cách để bên nhận tiếp tục quản lý được không.","levels_vi":["Không truyền đạt thông tin từng con, có sót khi bàn giao cũng không quan tâm.","Nếu được chỉ dẫn thì truyền đạt, nhưng nội dung chưa đủ, hay bị sót thông tin.","Truyền đạt và bàn giao được các thông tin từng con theo chỉ dẫn.","Không cần chỉ dẫn cũng sắp xếp thông tin cần thiết của từng con, bàn giao theo cách bên nhận hiểu được.","Nắm được những thông tin dễ bị sót khi bàn giao, và có thể hướng dẫn người mới cách bàn giao chắc chắn."],"name_id":"Serah terima informasi individu","kanten_id":"Apakah bisa menyampaikan informasi individu tanpa ada yang terlewat, dalam bentuk yang memungkinkan pihak penerima melanjutkan pengelolaan.","levels_id":["Tidak menyampaikan informasi individu, dan tidak peduli walau ada yang terlewat dalam serah terima.","Jika disuruh bisa menyampaikan, tetapi isinya kurang lengkap dan banyak informasi yang tidak tersampaikan.","Bisa menyampaikan dan menyerahterimakan informasi individu yang diinstruksikan secara garis besar.","Tanpa instruksi pun, merapikan informasi individu yang diperlukan dan menyerahterimakannya dalam bentuk yang mudah dipahami pihak penerima.","Mengetahui informasi yang mudah terlewat dalam serah terima, dan bisa mengajari karyawan baru cara serah terima yang pasti."]},{"id":"receiving-env","name":"受入れ環境の事前確認と初期観察","kanten":"受入れ先の水・エサ・温度・群密度を事前に整え、受入後数日の採食・飲水を確認できるか。","levels":["洗浄・消毒や空舎期間を省き、前ロットのままの温度・換気で受け入れ、群密度過多も見落とす。","指示があれば環境を確認するが、受入後の採食・飲水の確認に漏れが多い。","指示があれば受入れ先の水・エサ・温度を事前に確かめられる。","指示がなくても洗浄・消毒・空舎期間をとり、群密度と受入後3日間の採食・飲水を確認する。","病原体持ち越しや群密度過多のリスクを理解し、受入れ環境づくりを最適化して新人に指導できる。"],"name_en":"Pre-checking the receiving environment and initial observation","kanten_en":"Can they prepare water, feed, temperature, and group density at the receiving site in advance, and check eating and drinking for the first days after arrival?","levels_en":["Skips washing, disinfection, and downtime, receives pigs with the previous lot's temperature and ventilation settings, and overlooks overcrowding.","With guidance, checks the environment, but often fails to confirm eating and drinking after arrival.","With guidance, can check water, feed, and temperature at the receiving site in advance.","Independently carries out washing, disinfection, and downtime, and checks group density plus eating and drinking for the first 3 days after arrival.","Understands the risks of pathogen carryover and overcrowding, optimizes preparation of the receiving environment, and can teach new staff."],"name_vi":"Kiểm tra trước môi trường nhận lợn và quan sát ban đầu","kanten_vi":"Có chuẩn bị trước nước, thức ăn, nhiệt độ, mật độ đàn ở nơi nhận lợn, và kiểm tra việc ăn, uống trong vài ngày sau khi nhận không.","levels_vi":["Bỏ qua việc rửa, khử trùng và thời gian để trống chuồng, nhận lợn với nhiệt độ, thông gió còn nguyên như lứa trước, mật độ đàn quá đông cũng bỏ sót.","Nếu có chỉ dẫn thì kiểm tra môi trường, nhưng hay bỏ sót việc kiểm tra ăn, uống sau khi nhận lợn.","Nếu có chỉ dẫn thì kiểm tra trước được nước, thức ăn, nhiệt độ ở nơi nhận lợn.","Không cần chỉ dẫn cũng thực hiện rửa, khử trùng, để trống chuồng, kiểm tra mật độ đàn và việc ăn, uống trong 3 ngày sau khi nhận.","Hiểu nguy cơ mầm bệnh còn sót lại và mật độ đàn quá đông, biết tối ưu việc chuẩn bị môi trường nhận lợn và có thể hướng dẫn người mới."],"name_id":"Pemeriksaan awal lingkungan penerima dan pengamatan awal","kanten_id":"Apakah menyiapkan air, pakan, suhu, dan kepadatan kelompok di tempat penerima sebelumnya, dan memeriksa makan serta minum selama beberapa hari setelah diterima.","levels_id":["Melewatkan pencucian, disinfeksi, dan masa kosong kandang, menerima babi dengan suhu dan ventilasi bekas kelompok sebelumnya, dan tidak sadar kepadatan kelompok berlebih.","Jika ada instruksi bisa memeriksa lingkungan, tetapi sering lalai memeriksa makan dan minum setelah babi diterima.","Jika ada instruksi, bisa memeriksa air, pakan, dan suhu di tempat penerima sebelum babi datang.","Tanpa instruksi pun, melakukan pencucian, disinfeksi, dan masa kosong kandang, serta memeriksa kepadatan kelompok dan makan-minum selama 3 hari setelah diterima.","Memahami risiko bibit penyakit yang terbawa dan kepadatan kelompok berlebih, bisa mengoptimalkan penyiapan lingkungan penerima, dan bisa mengajari karyawan baru."]}],"gyomu":"27","name_en":"Grower intake","purposeShort_en":"Ensure a reliable handover to grower management","name_vi":"Nhận lợn cai sữa vào chuồng cai sữa (bàn giao nuôi dưỡng)","purposeShort_vi":"Bàn giao chắc chắn sang khâu quản lý lợn choai","name_id":"Penerimaan babi sapih ke kandang sapih (serah terima pemeliharaan)","purposeShort_id":"Memastikan serah terima ke pengelolaan pembesaran berjalan dengan pasti"},{"id":"castration","category":"feeding","no":"No.34","name":"去勢","purposeShort":"雄臭のない豚肉を生産し、ケンカ・乗駕を減らし、群管理を安全にする","aspects":[{"id":"age-method","name":"日齢・方法の遵守と短時間実施","kanten":"決められた日齢・方法で、子豚に無理をさせず短時間で去勢できるか。","levels":["日齢や方法を守らず、生後7日を過ぎてから雑に行い、子豚に長く無理をさせる。","指示があれば実施できるが、日齢の判断や手早さに欠け、ストレスをかけがち。","指示があれば決められた日齢・方法でひと通り去勢できる。","指示がなくても適期を見て短時間で行い、子豚への負担を抑える。","日齢超過がストレス・出血を増やすことを理解し、適期と手技を新人に指導できる。"],"name_en":"Following age and method with quick execution","kanten_en":"Can they castrate at the prescribed age in days and by the prescribed method, quickly and without straining the piglets?","levels_en":["Ignores age and method, performs the procedure roughly after 7 days of age, and puts prolonged strain on the piglets.","With guidance, can perform the procedure, but lacks judgment on age and speed, tending to stress the piglets.","With guidance, can castrate adequately at the prescribed age and by the prescribed method.","Independently judges the right timing, works quickly, and keeps the burden on piglets low.","Understands that exceeding the proper age increases stress and bleeding, and can teach new staff the right timing and technique."],"name_vi":"Giữ đúng tuổi ngày, cách làm và thực hiện nhanh gọn","kanten_vi":"Có thiến đúng tuổi ngày và cách làm quy định, thao tác nhanh, không làm lợn con quá sức không.","levels_vi":["Không giữ tuổi ngày và cách làm, làm ẩu sau khi lợn quá 7 ngày tuổi, bắt lợn con chịu đựng lâu.","Nếu có chỉ dẫn thì làm được, nhưng phán đoán tuổi ngày và độ nhanh tay còn kém, dễ gây stress cho lợn.","Nếu có chỉ dẫn thì thiến được các bước cơ bản theo đúng tuổi ngày và cách làm quy định.","Không cần chỉ dẫn cũng nhìn đúng thời kỳ thích hợp, làm nhanh gọn, giảm gánh nặng cho lợn con.","Hiểu việc quá tuổi ngày làm tăng stress và chảy máu, và có thể hướng dẫn người mới thời kỳ thích hợp và kỹ thuật thao tác."],"name_id":"Mematuhi umur dan metode serta pelaksanaan cepat","kanten_id":"Apakah bisa melakukan kastrasi dengan umur (hari) dan metode yang ditentukan, dalam waktu singkat tanpa memaksa anak babi.","levels_id":["Tidak mematuhi umur atau metode, melakukannya dengan kasar setelah lewat umur 7 hari, dan membuat anak babi tersiksa lama.","Jika ada instruksi bisa melaksanakan, tetapi kurang bisa menilai umur dan kurang cekatan sehingga cenderung membuat stres.","Jika ada instruksi, bisa melakukan kastrasi secara garis besar dengan umur dan metode yang ditentukan.","Tanpa instruksi pun, melakukannya pada waktu yang tepat dalam waktu singkat, dan menekan beban pada anak babi.","Memahami bahwa melewati umur yang tepat menambah stres dan pendarahan, dan bisa mengajari karyawan baru waktu yang tepat dan teknik pelaksanaannya."]},{"id":"asepsis-aftercare","name":"清潔な器具と術後の確認","kanten":"器具を1頭ごとに消毒し、術後の切り口の処置と出血・腫れ・元気の確認ができるか。","levels":["器具を1頭ごとに消毒せず使い回し、術後の切り口処置や観察を怠り腹膜炎・感染を招く。","指示があれば消毒するが、術後の消毒薬塗布や観察に漏れが多い。","指示があれば清潔な器具を使い、術後の出血・腫れ・元気をひと通り確認できる。","指示がなくても1頭ごとに器具を消毒し、切り口を処置して術後の観察頻度を増やす。","感染・合併症の仕組みを理解し、無菌操作と術後管理を新人に指導できる。"],"name_en":"Clean instruments and post-operative checks","kanten_en":"Can they disinfect instruments for each animal, treat the incision, and check for bleeding, swelling, and vitality after the procedure?","levels_en":["Reuses instruments without disinfecting between animals and neglects incision care and observation, causing peritonitis and infection.","With guidance, disinfects, but often fails to apply antiseptic to the incision or observe afterward.","With guidance, uses clean instruments and can adequately check bleeding, swelling, and vitality after the procedure.","Independently disinfects instruments between each animal, treats the incision, and increases the frequency of post-operative observation.","Understands the mechanisms of infection and complications, and can teach new staff aseptic technique and post-operative management."],"name_vi":"Dụng cụ sạch và kiểm tra sau thiến","kanten_vi":"Có khử trùng dụng cụ theo từng con, xử lý vết cắt sau thiến và kiểm tra chảy máu, sưng, độ khỏe không.","levels_vi":["Không khử trùng dụng cụ theo từng con mà dùng đi dùng lại, bỏ qua xử lý vết cắt và quan sát sau thiến, gây viêm phúc mạc và nhiễm trùng.","Nếu có chỉ dẫn thì khử trùng, nhưng hay bỏ sót việc bôi thuốc sát trùng và quan sát sau thiến.","Nếu có chỉ dẫn thì dùng dụng cụ sạch, kiểm tra được cơ bản chảy máu, sưng và độ khỏe sau thiến.","Không cần chỉ dẫn cũng khử trùng dụng cụ theo từng con, xử lý vết cắt và tăng số lần quan sát sau thiến.","Hiểu cơ chế nhiễm trùng và biến chứng, và có thể hướng dẫn người mới thao tác vô trùng và quản lý sau thiến."],"name_id":"Alat yang bersih dan pemeriksaan pascaoperasi","kanten_id":"Apakah mendisinfeksi alat setiap satu ekor, merawat luka sayatan setelah operasi, dan memeriksa pendarahan, bengkak, serta keaktifan anak babi.","levels_id":["Memakai alat bergantian tanpa disinfeksi per ekor, lalai merawat luka dan mengamati setelah operasi sehingga menyebabkan peritonitis (radang selaput perut) dan infeksi.","Jika ada instruksi bisa mendisinfeksi, tetapi sering lalai mengoleskan obat disinfektan pada luka dan mengamati setelah operasi.","Jika ada instruksi, bisa memakai alat yang bersih dan memeriksa pendarahan, bengkak, serta keaktifan secara garis besar setelah operasi.","Tanpa instruksi pun, mendisinfeksi alat setiap satu ekor, merawat luka sayatan, dan menambah frekuensi pengamatan setelah operasi.","Memahami mekanisme infeksi dan komplikasi, dan bisa mengajari karyawan baru cara kerja bersih (aseptik) dan pengelolaan pascaoperasi."]}],"gyomu":"34","name_en":"Castration","purposeShort_en":"Produce pork free of boar taint, reduce fighting and mounting, and make group management safer","name_vi":"Thiến lợn con","purposeShort_vi":"Sản xuất thịt lợn không có mùi hôi đực, giảm đánh nhau và nhảy lên nhau, quản lý đàn an toàn hơn","name_id":"Kastrasi anak babi","purposeShort_id":"Menghasilkan daging babi tanpa bau pejantan, mengurangi perkelahian dan menunggangi, membuat pengelolaan kelompok lebih aman"},{"id":"additive","category":"feeding","no":"No.18","name":"添加剤準備","purposeShort":"添加剤の効果をムラなく出し、豚の健康・成績を安定させる","aspects":[{"id":"dosage-mix","name":"正確な計量と混合","kanten":"ラベルの対象・添加量を守り、正確に計量してムラなく混合できるか。","levels":["計量器を確かめず目分量で入れ、混合手順を省いてムラを出す。","指示があれば計量するが、計量器の校正やプレミックス手順に漏れがある。","指示があればラベルの添加量に従って計量し、ひと通り混合できる。","指示がなくても計量器を確かめて正確に計り、プレミックスでムラなく混合する。","計量誤差・混合ムラが成績に与える影響を理解し、正確な準備手順を新人に指導できる。"],"name_en":"Accurate measurement and mixing","kanten_en":"Can they follow the label's target animals and inclusion rate, measure accurately, and mix evenly?","levels_en":["Adds by eye without checking the scale and skips mixing steps, causing uneven distribution.","With guidance, measures, but is inconsistent about scale calibration and premix procedures.","With guidance, measures according to the label's inclusion rate and can mix adequately.","Independently verifies the scale, measures accurately, and mixes evenly using a premix.","Understands how measurement errors and uneven mixing affect performance, and can teach new staff accurate preparation procedures."],"name_vi":"Cân đo chính xác và trộn đều","kanten_vi":"Có giữ đúng đối tượng và lượng bổ sung ghi trên nhãn, cân đo chính xác và trộn đều không.","levels_vi":["Không kiểm tra dụng cụ cân, đổ theo ước lượng bằng mắt, bỏ bước trộn làm trộn không đều.","Nếu có chỉ dẫn thì cân đo, nhưng có bỏ sót việc hiệu chỉnh dụng cụ cân và bước trộn trước (premix).","Nếu có chỉ dẫn thì cân đo theo lượng bổ sung trên nhãn, trộn được các bước cơ bản.","Không cần chỉ dẫn cũng kiểm tra dụng cụ cân, cân chính xác, trộn trước (premix) để trộn đều không bị chỗ đậm chỗ nhạt.","Hiểu sai số cân đo và trộn không đều ảnh hưởng đến thành tích, và có thể hướng dẫn người mới quy trình chuẩn bị chính xác."],"name_id":"Penakaran akurat dan pencampuran","kanten_id":"Apakah mematuhi sasaran dan dosis pada label, menakar dengan akurat, dan mencampur secara merata.","levels_id":["Memasukkan dengan kira-kira tanpa memeriksa alat takar, dan melewatkan langkah pencampuran sehingga tidak merata.","Jika ada instruksi bisa menakar, tetapi sering lalai mengecek kalibrasi alat takar dan langkah premix (campuran awal).","Jika ada instruksi, bisa menakar sesuai dosis pada label dan mencampur secara garis besar.","Tanpa instruksi pun, memeriksa alat takar dan menakar dengan akurat, serta mencampur merata dengan cara premix.","Memahami pengaruh kesalahan takaran dan campuran tidak merata terhadap performa, dan bisa mengajari karyawan baru urutan persiapan yang akurat."]},{"id":"antibacterial","name":"抗菌性添加物の重複・休薬管理","kanten":"抗菌性添加物の重なりに注意し、給与期間の終了・休薬を記録で管理できるか。","levels":["抗菌性添加物の重なりや給与期間の終了を確認せず、残留リスクを招く。","指示があれば注意するが、複数添加剤の残存や期間管理に漏れが多い。","指示があれば抗菌性添加物の重なりに注意し、休薬のあるものを記録できる。","指示がなくても給与期間の終了を管理し、容器内残存による混在を避ける。","残留リスクと休薬の意味を理解し、抗菌性添加物の管理ルールを新人に指導できる。"],"name_en":"Managing overlap and withdrawal of antibacterial additives","kanten_en":"Can they watch for overlapping antibacterial additives and manage the end of feeding periods and withdrawal through records?","levels_en":["Does not check for overlapping antibacterial additives or the end of feeding periods, creating residue risk.","With guidance, pays attention, but often misses residues of multiple additives and period management.","With guidance, watches for overlapping antibacterial additives and can record those with withdrawal periods.","Independently manages the end of feeding periods and prevents mixing caused by leftovers remaining in containers.","Understands residue risk and the meaning of withdrawal periods, and can teach new staff the rules for managing antibacterial additives."],"name_vi":"Quản lý trùng lặp và ngừng thuốc của chất bổ sung kháng khuẩn","kanten_vi":"Có chú ý sự trùng lặp của các chất bổ sung kháng khuẩn, quản lý bằng ghi chép việc kết thúc thời gian cho ăn và thời gian ngừng thuốc không.","levels_vi":["Không kiểm tra sự trùng lặp của chất bổ sung kháng khuẩn và việc kết thúc thời gian cho ăn, gây nguy cơ tồn dư thuốc.","Nếu có chỉ dẫn thì chú ý, nhưng hay bỏ sót việc quản lý chất còn sót lại khi dùng nhiều loại và quản lý thời gian.","Nếu có chỉ dẫn thì chú ý sự trùng lặp của chất bổ sung kháng khuẩn, ghi chép được những loại có thời gian ngừng thuốc.","Không cần chỉ dẫn cũng quản lý việc kết thúc thời gian cho ăn, tránh lẫn lộn do chất còn sót lại trong thùng chứa.","Hiểu nguy cơ tồn dư và ý nghĩa của việc ngừng thuốc, và có thể hướng dẫn người mới quy tắc quản lý chất bổ sung kháng khuẩn."],"name_id":"Pengelolaan tumpang tindih imbuhan antibakteri dan masa henti obat","kanten_id":"Apakah memperhatikan tumpang tindih imbuhan antibakteri, dan mengelola akhir masa pemberian serta masa henti obat dengan catatan.","levels_id":["Tidak memeriksa tumpang tindih imbuhan antibakteri atau akhir masa pemberian, sehingga menimbulkan risiko residu obat.","Jika ada instruksi bisa berhati-hati, tetapi sering lalai soal sisa beberapa imbuhan dan pengelolaan masa pemberian.","Jika ada instruksi, bisa memperhatikan tumpang tindih imbuhan antibakteri dan mencatat yang punya masa henti obat.","Tanpa instruksi pun, mengelola akhir masa pemberian dan menghindari tercampurnya sisa imbuhan di dalam wadah.","Memahami risiko residu dan arti masa henti obat, dan bisa mengajari karyawan baru aturan pengelolaan imbuhan antibakteri."]}],"gyomu":"18","name_en":"Additive preparation","purposeShort_en":"Deliver the effects of additives evenly and stabilize pig health and performance","name_vi":"Chuẩn bị chất bổ sung (trộn vào thức ăn)","purposeShort_vi":"Giúp chất bổ sung phát huy hiệu quả đều, giữ sức khỏe và thành tích của lợn ổn định","name_id":"Persiapan imbuhan pakan (dicampur ke pakan)","purposeShort_id":"Mengeluarkan efek imbuhan pakan secara merata, menstabilkan kesehatan dan performa babi"},{"id":"dung-removal","category":"hygiene","no":"No.12","name":"除フン","purposeShort":"病気・有害ガスを減らし豚の健康を守り、糞から異常を早期発見する","aspects":[{"id":"order","name":"除糞→洗浄→消毒の順序","kanten":"先に糞を取り除いてから洗浄・消毒する順序を守り、汚れの上から消毒しないか。","levels":["汚れが残ったまま消毒し、順序を守らず効果を半減させても気にしない。","指示があれば糞を取るが、洗浄・消毒の順序や仕上がりの確認に漏れが多い。","指示があれば先に糞を取り、その後に洗浄・消毒する順序をひと通り守れる。","指示がなくても順序を守り、汚れが残ると消毒が効かないことを踏まえて確実に除糞する。","汚れと消毒効果の関係を理解し、決められた頻度・タイミングと順序を新人に指導できる。"],"name_en":"Order of manure removal, washing, then disinfection","kanten_en":"Do they follow the order of removing manure first, then washing and disinfecting, and avoid disinfecting over dirt?","levels_en":["Disinfects over remaining dirt, ignoring the correct order and not caring that this halves the effect.","With guidance, removes manure, but often skips steps in the washing and disinfection order and fails to check the result.","With guidance, can adequately follow the order of removing manure first, then washing and disinfecting.","Independently follows the order and removes manure thoroughly, knowing that disinfection does not work over remaining dirt.","Understands the relationship between dirt and disinfection efficacy, and can teach new staff the prescribed frequency, timing, and order."],"name_vi":"Thứ tự dọn phân → rửa → khử trùng","kanten_vi":"Có giữ thứ tự lấy phân đi trước rồi mới rửa và khử trùng, không khử trùng đè lên chỗ bẩn không.","levels_vi":["Khử trùng khi chỗ bẩn còn nguyên, không giữ thứ tự làm hiệu quả giảm một nửa cũng không quan tâm.","Nếu có chỉ dẫn thì lấy phân, nhưng hay bỏ sót thứ tự rửa, khử trùng và việc kiểm tra kết quả.","Nếu có chỉ dẫn thì giữ được cơ bản thứ tự lấy phân trước, sau đó rửa và khử trùng.","Không cần chỉ dẫn cũng giữ thứ tự, dọn phân kỹ vì biết rằng còn bẩn thì khử trùng không có tác dụng.","Hiểu quan hệ giữa chỗ bẩn và hiệu quả khử trùng, và có thể hướng dẫn người mới tần suất, thời điểm quy định và thứ tự làm."],"name_id":"Urutan bersihkan kotoran → cuci → disinfeksi","kanten_id":"Apakah mematuhi urutan membersihkan kotoran dulu baru mencuci dan mendisinfeksi, dan tidak mendisinfeksi di atas kotoran.","levels_id":["Mendisinfeksi dengan kotoran masih menempel, tidak peduli walau urutan dilanggar dan efeknya berkurang setengah.","Jika ada instruksi bisa membersihkan kotoran, tetapi sering lalai soal urutan cuci-disinfeksi dan memeriksa hasil akhirnya.","Jika ada instruksi, bisa mematuhi urutan secara garis besar: bersihkan kotoran dulu, lalu cuci dan disinfeksi.","Tanpa instruksi pun, mematuhi urutan dan membersihkan kotoran dengan pasti, karena tahu disinfeksi tidak bekerja jika kotoran masih tersisa.","Memahami hubungan kotoran dengan efek disinfeksi, dan bisa mengajari karyawan baru frekuensi, waktu, dan urutan yang ditentukan."]},{"id":"underfloor","name":"床下・ピット・残渣の確認","kanten":"床下やピットまで定期的に確認し、スクレーパー動作後の残渣を目視で確かめられるか。","levels":["床下・ピットを確認せず、スクレーパー後の残渣も見ずに次工程へ進む。","指示があれば見えるところは確認するが、床下・ピットの点検に漏れが多い。","指示があれば床下やピットをひと通り確認できる。","指示がなくても床下・ピットを定期的に確認し、スクレーパー後の残渣を目視で確かめる。","残渣滞留のリスクを理解し、見落としやすい箇所の点検を新人に指導できる。"],"name_en":"Checking underfloor areas, pits, and residue","kanten_en":"Can they regularly check underfloor areas and pits, and visually confirm residue after the scraper has run?","levels_en":["Does not check underfloor areas or pits, and moves to the next task without looking at residue after the scraper.","With guidance, checks visible areas, but often misses underfloor and pit inspections.","With guidance, can adequately check underfloor areas and pits.","Independently checks underfloor areas and pits regularly and visually confirms residue after the scraper.","Understands the risks of residue accumulation and can teach new staff how to inspect easily overlooked spots."],"name_vi":"Kiểm tra dưới sàn, hố chứa phân và phân sót lại","kanten_vi":"Có kiểm tra định kỳ cả dưới sàn và hố chứa phân, nhìn tận mắt phân còn sót sau khi máy cào phân chạy không.","levels_vi":["Không kiểm tra dưới sàn và hố chứa phân, cũng không nhìn phân sót sau khi máy cào phân chạy mà chuyển sang việc tiếp theo.","Nếu có chỉ dẫn thì kiểm tra chỗ nhìn thấy được, nhưng hay bỏ sót việc kiểm tra dưới sàn và hố chứa phân.","Nếu có chỉ dẫn thì kiểm tra được cơ bản dưới sàn và hố chứa phân.","Không cần chỉ dẫn cũng kiểm tra định kỳ dưới sàn và hố chứa phân, nhìn tận mắt phân còn sót sau khi máy cào phân chạy.","Hiểu nguy cơ khi phân ứ đọng, và có thể hướng dẫn người mới cách kiểm tra những chỗ dễ bỏ sót."],"name_id":"Pemeriksaan bawah lantai, pit, dan sisa kotoran","kanten_id":"Apakah memeriksa sampai bawah lantai dan pit secara berkala, dan memeriksa dengan mata sisa kotoran setelah alat pengeruk kotoran bekerja.","levels_id":["Tidak memeriksa bawah lantai dan pit, dan lanjut ke pekerjaan berikutnya tanpa melihat sisa kotoran setelah alat pengeruk bekerja.","Jika ada instruksi bisa memeriksa bagian yang terlihat, tetapi sering lalai memeriksa bawah lantai dan pit.","Jika ada instruksi, bisa memeriksa bawah lantai dan pit secara garis besar.","Tanpa instruksi pun, memeriksa bawah lantai dan pit secara berkala, dan memeriksa dengan mata sisa kotoran setelah alat pengeruk bekerja.","Memahami risiko kotoran yang menumpuk, dan bisa mengajari karyawan baru pemeriksaan tempat-tempat yang mudah terlewat."]}],"gyomu":"12","name_en":"Manure removal","purposeShort_en":"Reduce disease and harmful gases to protect pig health, and detect abnormalities early from the manure","name_vi":"Dọn phân","purposeShort_vi":"Giảm bệnh và khí độc hại, bảo vệ sức khỏe lợn, phát hiện sớm bất thường qua phân","name_id":"Membersihkan kotoran","purposeShort_id":"Mengurangi penyakit dan gas berbahaya untuk menjaga kesehatan babi, dan menemukan kelainan lebih awal dari kotoran"},{"id":"five-s","category":"hygiene","no":"No.31","name":"5S清掃","purposeShort":"衛生レベルを底上げし、作業をやりやすくし、設備トラブルを早く見つける","aspects":[{"id":"fixed-place","name":"定位置管理の徹底","kanten":"物の置き場所を決めて守り、使った物を元の場所に戻せるか。","levels":["置き場所を決めず、使った物を元に戻さないまま放置する。","指示があれば片づけるが、元の場所に戻さないことが多い。","指示があれば決められた置き場所に物を戻せる。","指示がなくても定位置を守り、乱れがあれば自分で整える。","定位置管理がミス削減につながることを理解し、置き場所のルールづくりを新人に指導できる。"],"name_en":"Thorough fixed-location management","kanten_en":"Can they set and observe fixed storage locations, returning items to their place after use?","levels_en":["Does not set storage locations and leaves used items lying around without returning them.","With guidance, tidies up, but often fails to return items to their original place.","With guidance, can return items to their designated locations.","Independently keeps to the fixed locations and straightens things up on their own when they are out of order.","Understands that fixed-location management reduces mistakes, and can teach new staff how to establish storage rules."],"name_vi":"Giữ nghiêm việc để đồ đúng vị trí quy định","kanten_vi":"Có quy định chỗ để đồ và giữ đúng, dùng xong trả đồ về chỗ cũ không.","levels_vi":["Không quy định chỗ để đồ, dùng xong không trả về chỗ cũ mà bỏ mặc.","Nếu có chỉ dẫn thì dọn dẹp, nhưng thường không trả đồ về chỗ cũ.","Nếu có chỉ dẫn thì trả được đồ về chỗ để quy định.","Không cần chỉ dẫn cũng giữ đúng vị trí quy định, nếu có xáo trộn thì tự mình sắp xếp lại.","Hiểu việc quản lý vị trí cố định giúp giảm sai sót, và có thể hướng dẫn người mới cách đặt quy tắc chỗ để đồ."],"name_id":"Menjalankan pengaturan tempat tetap","kanten_id":"Apakah menentukan dan mematuhi tempat menyimpan barang, dan mengembalikan barang yang dipakai ke tempat semula.","levels_id":["Tidak menentukan tempat penyimpanan, dan membiarkan barang yang dipakai tanpa dikembalikan ke tempatnya.","Jika ada instruksi bisa membereskan, tetapi sering tidak mengembalikan barang ke tempat semula.","Jika ada instruksi, bisa mengembalikan barang ke tempat penyimpanan yang ditentukan.","Tanpa instruksi pun, mematuhi tempat tetap, dan jika ada yang berantakan merapikannya sendiri.","Memahami bahwa pengaturan tempat tetap mengurangi kesalahan, dan bisa mengajari karyawan baru cara membuat aturan tempat penyimpanan."]},{"id":"standard-abnormal","name":"きれいさの基準共有と異常発見","kanten":"「基準のきれいさ」を共有し、清掃を形式で終わらせず設備の異常発見につなげられるか。","levels":["基準があいまいで人により差が出て、チェックリストを形式的に埋めるだけで異常に気づかない。","指示があれば清掃するが、基準の共有や異常発見への意識が薄い。","指示があれば汚れやすい所を重点的に掃除し、決めた基準に沿ってひと通り清掃できる。","指示がなくても基準のきれいさを意識し、清掃しながら設備トラブルの兆候に気づく。","5Sを異常の早期発見に結びつけ、基準の共有と継続の仕組みを新人に指導できる。"],"name_en":"Sharing cleanliness standards and finding abnormalities","kanten_en":"Can they share a common cleanliness standard and use cleaning to detect equipment abnormalities rather than treating it as a formality?","levels_en":["Standards are vague and vary by person; fills in checklists as a formality and misses abnormalities.","With guidance, cleans, but has little awareness of shared standards or abnormality detection.","With guidance, focuses on spots that get dirty easily and can clean adequately according to the agreed standard.","Independently keeps the cleanliness standard in mind and notices early signs of equipment trouble while cleaning.","Connects 5S to early detection of abnormalities, and can teach new staff how to share standards and keep the practice going."],"name_vi":"Chia sẻ tiêu chuẩn sạch sẽ và phát hiện bất thường","kanten_vi":"Có chia sẻ \"tiêu chuẩn sạch sẽ\" chung, không làm vệ sinh cho có hình thức mà gắn với việc phát hiện bất thường của thiết bị không.","levels_vi":["Tiêu chuẩn mơ hồ nên mỗi người làm một kiểu, chỉ điền bảng kiểm cho có hình thức mà không nhận ra bất thường.","Nếu có chỉ dẫn thì làm vệ sinh, nhưng ý thức về chia sẻ tiêu chuẩn và phát hiện bất thường còn yếu.","Nếu có chỉ dẫn thì lau dọn kỹ những chỗ dễ bẩn, làm vệ sinh được cơ bản theo tiêu chuẩn đã định.","Không cần chỉ dẫn cũng ý thức về tiêu chuẩn sạch sẽ, vừa làm vệ sinh vừa nhận ra dấu hiệu sự cố của thiết bị.","Gắn 5S với việc phát hiện sớm bất thường, và có thể hướng dẫn người mới cách chia sẻ tiêu chuẩn và duy trì lâu dài."],"name_id":"Berbagi standar kebersihan dan menemukan kelainan","kanten_id":"Apakah berbagi \"standar kebersihan\" bersama, dan tidak menjadikan bersih-bersih sekadar formalitas tetapi menghubungkannya dengan penemuan kelainan peralatan.","levels_id":["Standarnya tidak jelas sehingga hasil tiap orang berbeda, hanya mengisi daftar periksa sebagai formalitas dan tidak menyadari kelainan.","Jika ada instruksi bisa bersih-bersih, tetapi kesadaran akan berbagi standar dan menemukan kelainan masih lemah.","Jika ada instruksi, bisa membersihkan terutama tempat yang mudah kotor, dan bersih-bersih secara garis besar sesuai standar yang ditetapkan.","Tanpa instruksi pun, sadar akan standar kebersihan, dan sambil bersih-bersih menyadari tanda-tanda masalah peralatan.","Bisa menghubungkan 5S dengan penemuan kelainan lebih awal, dan bisa mengajari karyawan baru cara berbagi standar dan menjaga kelangsungannya."]}],"gyomu":"31","name_en":"5S cleaning","purposeShort_en":"Raise the overall hygiene level, make work easier, and detect equipment trouble early","name_vi":"Vệ sinh 5S (Sàng lọc - Sắp xếp - Sạch sẽ - Săn sóc - Sẵn sàng)","purposeShort_vi":"Nâng cao mức vệ sinh, làm việc dễ hơn, phát hiện sớm sự cố thiết bị","name_id":"Kebersihan 5S (Ringkas - Rapi - Resik - Rawat - Rajin)","purposeShort_id":"Menaikkan tingkat kebersihan, membuat pekerjaan lebih mudah, dan menemukan masalah peralatan lebih cepat"},{"id":"treatment","category":"hygiene","no":"No.04","name":"治療","purposeShort":"体調の悪い豚を早く回復させ、悪化と感染拡大を防ぐ","aspects":[{"id":"withdrawal","name":"休薬期間の確認と治療豚の識別","kanten":"使用薬剤の休薬期間を確認し、治療豚を確実に識別して出荷から除外できるか。","levels":["休薬期間を確認せず、治療豚の識別もあいまいで、休薬中の豚を誤って出荷する危険がある。","指示があれば休薬を確認するが、治療豚の識別や記録に漏れが多い。","指示があれば休薬期間を確認し、治療豚を識別してひと通り管理できる。","指示がなくても休薬期間を必ず確認し、治療豚を明確に識別して出荷から除外する。","残留違反の重大さを理解し、休薬管理と個体識別の仕組みを新人に指導できる。"],"name_en":"Checking withdrawal periods and identifying treated pigs","kanten_en":"Can they check the withdrawal period of each drug used, reliably identify treated pigs, and exclude them from shipment?","levels_en":["Does not check withdrawal periods; identification of treated pigs is vague, risking mistaken shipment of pigs still in withdrawal.","With guidance, checks withdrawal periods, but often fails to identify or record treated pigs.","With guidance, checks withdrawal periods and can adequately identify and manage treated pigs.","Independently always checks withdrawal periods, clearly identifies treated pigs, and excludes them from shipment.","Understands the seriousness of residue violations, and can teach new staff systems for withdrawal management and individual identification."],"name_vi":"Kiểm tra thời gian ngừng thuốc và nhận biết lợn đang điều trị","kanten_vi":"Có kiểm tra thời gian ngừng thuốc của thuốc đang dùng, đánh dấu rõ lợn đang điều trị và loại khỏi danh sách xuất chuồng không.","levels_vi":["Không kiểm tra thời gian ngừng thuốc, đánh dấu lợn đang điều trị cũng mơ hồ, có nguy cơ xuất chuồng nhầm lợn đang trong thời gian ngừng thuốc.","Nếu có chỉ dẫn thì kiểm tra việc ngừng thuốc, nhưng hay bỏ sót việc đánh dấu và ghi chép lợn đang điều trị.","Nếu có chỉ dẫn thì kiểm tra thời gian ngừng thuốc, đánh dấu lợn đang điều trị và quản lý được cơ bản.","Không cần chỉ dẫn cũng luôn kiểm tra thời gian ngừng thuốc, đánh dấu rõ lợn đang điều trị và loại khỏi việc xuất chuồng.","Hiểu mức độ nghiêm trọng của vi phạm tồn dư thuốc, và có thể hướng dẫn người mới cách quản lý ngừng thuốc và nhận dạng từng con."],"name_id":"Pemeriksaan masa henti obat dan penandaan babi yang diobati","kanten_id":"Apakah memeriksa masa henti obat dari obat yang dipakai, menandai babi yang diobati dengan pasti, dan mengeluarkannya dari pengiriman.","levels_id":["Tidak memeriksa masa henti obat, penandaan babi yang diobati juga tidak jelas, sehingga ada bahaya mengirim babi yang masih dalam masa henti obat.","Jika ada instruksi bisa memeriksa masa henti obat, tetapi sering lalai menandai dan mencatat babi yang diobati.","Jika ada instruksi, bisa memeriksa masa henti obat, menandai babi yang diobati, dan mengelolanya secara garis besar.","Tanpa instruksi pun, selalu memeriksa masa henti obat, menandai babi yang diobati dengan jelas, dan mengeluarkannya dari pengiriman.","Memahami seriusnya pelanggaran residu obat, dan bisa mengajari karyawan baru sistem pengelolaan masa henti obat dan identifikasi individu."]},{"id":"protocol","name":"指示・用法の遵守と針の本数管理","kanten":"決められたやり方・指示を守り、注射針の本数を管理して紛失・混入を防げるか。","levels":["自己判断でやり方を変え、注射針の本数管理もせず紛失・混入の危険を放置する。","指示があれば従うが、用法の徹底や針の本数確認に漏れがある。","指示があれば決められたやり方・指示に従い、針の本数をひと通り確認できる。","指示がなくても用法を守り、注射針の本数管理を徹底して紛失・混入を防ぐ。","経験則での抗生剤選択のリスクや針混入の危険を理解し、正しい治療手順を新人に指導できる。"],"name_en":"Following instructions and dosage, and needle count management","kanten_en":"Can they follow prescribed methods and instructions, and manage the number of needles to prevent loss and contamination?","levels_en":["Changes methods on their own judgment and does not manage needle counts, leaving the risk of loss and contamination unaddressed.","With guidance, complies, but is inconsistent about following dosage instructions and checking needle counts.","With guidance, follows the prescribed methods and instructions and can adequately check needle counts.","Independently follows the dosage instructions and rigorously manages needle counts to prevent loss and contamination.","Understands the risks of choosing antibiotics by rule of thumb and of needle contamination, and can teach new staff correct treatment procedures."],"name_vi":"Tuân thủ chỉ dẫn, cách dùng thuốc và quản lý số kim tiêm","kanten_vi":"Có giữ đúng cách làm và chỉ dẫn quy định, quản lý số lượng kim tiêm để tránh mất kim và kim lẫn vào thịt không.","levels_vi":["Tự ý thay đổi cách làm, không quản lý số kim tiêm, bỏ mặc nguy cơ mất kim và kim lẫn vào thịt.","Nếu có chỉ dẫn thì làm theo, nhưng có bỏ sót việc giữ đúng cách dùng thuốc và kiểm số kim.","Nếu có chỉ dẫn thì làm theo đúng cách và chỉ dẫn quy định, kiểm được cơ bản số kim tiêm.","Không cần chỉ dẫn cũng giữ đúng cách dùng thuốc, quản lý chặt số kim tiêm để tránh mất và lẫn kim.","Hiểu nguy cơ khi tự chọn kháng sinh theo kinh nghiệm và nguy cơ kim lẫn vào thịt, và có thể hướng dẫn người mới quy trình điều trị đúng."],"name_id":"Mematuhi instruksi dan aturan pakai serta pengelolaan jumlah jarum","kanten_id":"Apakah mematuhi cara dan instruksi yang ditentukan, dan mengelola jumlah jarum suntik untuk mencegah hilang atau masuk ke tubuh babi.","levels_id":["Mengubah cara sesuka hati, tidak mengelola jumlah jarum suntik, dan membiarkan bahaya jarum hilang atau masuk ke tubuh babi.","Jika ada instruksi bisa mengikuti, tetapi sering lalai mematuhi aturan pakai dan memeriksa jumlah jarum.","Jika ada instruksi, bisa mengikuti cara dan instruksi yang ditentukan, serta memeriksa jumlah jarum secara garis besar.","Tanpa instruksi pun, mematuhi aturan pakai dan mengelola jumlah jarum suntik dengan ketat untuk mencegah hilang atau masuk ke tubuh babi.","Memahami risiko memilih antibiotik hanya berdasar pengalaman dan bahaya jarum masuk ke tubuh babi, dan bisa mengajari karyawan baru urutan pengobatan yang benar."]},{"id":"identify-track","name":"個体識別と投薬経過の記録","kanten":"治療豚を明確に識別し、薬剤名・投与量・開始日など投薬経過を追える形で記録できるか。","levels":["治療豚の識別が不明瞭で、投薬経過を記録せず後から追えない。","指示されれば記録するが、薬剤名・投与量・開始日の記入漏れが多い。","指示があれば治療豚を識別し、投薬内容をひと通り記録できる。","指示がなくても投薬経過を漏れなく記録し、識別と記録を結びつけて管理する。","投薬経過の記録が休薬管理・治療評価に不可欠と理解し、記録の書き方を新人に指導できる。"],"name_en":"Individual identification and medication records","kanten_en":"Can they clearly identify treated pigs and record the medication course — drug name, dose, start date — in a traceable form?","levels_en":["Identification of treated pigs is unclear, and the medication course is not recorded and cannot be traced later.","Records when instructed, but often omits drug name, dose, and start date.","With guidance, identifies treated pigs and can adequately record the medication details.","Independently records the medication course completely and manages it by linking identification with records.","Understands that medication records are essential for withdrawal management and treatment evaluation, and can teach new staff how to keep them."],"name_vi":"Nhận dạng từng con và ghi chép quá trình dùng thuốc","kanten_vi":"Có đánh dấu rõ lợn đang điều trị, ghi chép tên thuốc, liều lượng, ngày bắt đầu... theo cách theo dõi lại được quá trình dùng thuốc không.","levels_vi":["Đánh dấu lợn đang điều trị không rõ ràng, không ghi chép quá trình dùng thuốc nên sau này không theo dõi lại được.","Nếu được chỉ dẫn thì ghi chép, nhưng hay bỏ sót tên thuốc, liều lượng, ngày bắt đầu.","Nếu có chỉ dẫn thì đánh dấu lợn đang điều trị, ghi chép được cơ bản nội dung dùng thuốc.","Không cần chỉ dẫn cũng ghi chép đầy đủ quá trình dùng thuốc, quản lý bằng cách gắn kết việc đánh dấu với ghi chép.","Hiểu ghi chép quá trình dùng thuốc là không thể thiếu cho quản lý ngừng thuốc và đánh giá điều trị, và có thể hướng dẫn người mới cách ghi chép."],"name_id":"Identifikasi individu dan pencatatan perjalanan pengobatan","kanten_id":"Apakah menandai babi yang diobati dengan jelas, dan mencatat perjalanan pengobatan seperti nama obat, dosis, dan tanggal mulai dalam bentuk yang bisa ditelusuri.","levels_id":["Penandaan babi yang diobati tidak jelas, tidak mencatat perjalanan pengobatan sehingga tidak bisa ditelusuri kemudian.","Jika disuruh bisa mencatat, tetapi sering lupa mengisi nama obat, dosis, dan tanggal mulai.","Jika ada instruksi, bisa menandai babi yang diobati dan mencatat isi pengobatan secara garis besar.","Tanpa instruksi pun, mencatat perjalanan pengobatan tanpa ada yang terlewat, dan mengelolanya dengan menghubungkan penandaan dan catatan.","Memahami bahwa catatan perjalanan pengobatan sangat penting untuk pengelolaan masa henti obat dan evaluasi pengobatan, dan bisa mengajari karyawan baru cara menulis catatan."]}],"gyomu":"04","name_en":"Treatment","purposeShort_en":"Help sick pigs recover quickly and prevent deterioration and spread of infection","name_vi":"Điều trị","purposeShort_vi":"Giúp lợn ốm hồi phục nhanh, ngăn bệnh nặng thêm và lây lan","name_id":"Pengobatan","purposeShort_id":"Memulihkan babi yang sakit dengan cepat, mencegah kondisi memburuk dan penyebaran infeksi"},{"id":"sow-vaccine","category":"hygiene","no":"No.06","name":"母豚ワクチン","purposeShort":"母豚と子豚を守る免疫をつけ、農場の免疫レベルをそろえる","aspects":[{"id":"schedule","name":"日齢・スケジュールの遵守","kanten":"決められた日齢・スケジュールで確実に接種し、打ち漏れを作らないか。","levels":["スケジュールを守らず、体調不良の母豚にそのまま接種して免疫を不十分にする。","指示があれば接種するが、対象や時期の確認に漏れがある。","指示があれば決められた日齢・スケジュールでひと通り接種できる。","指示がなくても対象と体調を確認して接種し、打ち漏れを防ぐ。","接種時期と免疫の関係を理解し、スケジュール管理と体調確認を新人に指導できる。"],"name_en":"Following age and vaccination schedule","kanten_en":"Can they vaccinate reliably at the prescribed age and schedule without missing any animals?","levels_en":["Ignores the schedule and vaccinates unwell sows as-is, resulting in insufficient immunity.","With guidance, vaccinates, but is inconsistent about confirming target animals and timing.","With guidance, can adequately vaccinate at the prescribed age and schedule.","Independently confirms the target animals and their condition before vaccinating, preventing missed injections.","Understands the relationship between vaccination timing and immunity, and can teach new staff schedule management and condition checks."],"name_vi":"Giữ đúng tuổi ngày và lịch tiêm","kanten_vi":"Có tiêm chắc chắn theo đúng tuổi ngày và lịch quy định, không để sót con chưa tiêm không.","levels_vi":["Không giữ lịch tiêm, tiêm luôn cho lợn nái đang ốm làm miễn dịch không đủ.","Nếu có chỉ dẫn thì tiêm, nhưng có bỏ sót việc kiểm tra đối tượng và thời điểm.","Nếu có chỉ dẫn thì tiêm được cơ bản theo đúng tuổi ngày và lịch quy định.","Không cần chỉ dẫn cũng kiểm tra đối tượng và tình trạng sức khỏe rồi tiêm, phòng sót con chưa tiêm.","Hiểu quan hệ giữa thời điểm tiêm và miễn dịch, và có thể hướng dẫn người mới cách quản lý lịch và kiểm tra sức khỏe."],"name_id":"Mematuhi umur dan jadwal","kanten_id":"Apakah menyuntik vaksin dengan pasti sesuai umur dan jadwal yang ditentukan, tanpa ada yang terlewat.","levels_id":["Tidak mematuhi jadwal, dan menyuntik induk babi yang sedang tidak sehat begitu saja sehingga kekebalan tidak cukup.","Jika ada instruksi bisa menyuntik, tetapi sering lalai memeriksa sasaran dan waktunya.","Jika ada instruksi, bisa menyuntik secara garis besar sesuai umur dan jadwal yang ditentukan.","Tanpa instruksi pun, memeriksa sasaran dan kondisi kesehatan sebelum menyuntik, dan mencegah ada yang terlewat.","Memahami hubungan waktu penyuntikan dengan kekebalan, dan bisa mengajari karyawan baru pengelolaan jadwal dan pemeriksaan kondisi kesehatan."]},{"id":"vaccine-handling","name":"ワクチンの取り扱いと針交換","kanten":"生ワクチンは溶解後すぐ使い切り、不活化は当日中に使い、針を頭ごとに交換できるか。","levels":["溶解後の保管時間を超過し、注射針を使い回して感染リスクを高める。","指示があれば取り扱うが、使い切りの時間管理や針交換に漏れがある。","指示があれば生ワクチンを溶解後すぐ使い、針をひと通り交換できる。","指示がなくても溶解後の時間を守って使い切り、針を頭ごとに交換する。","ワクチンの失活や針使い回しのリスクを理解し、正しい取り扱いを新人に指導できる。"],"name_en":"Vaccine handling and needle changes","kanten_en":"Can they use live vaccines immediately after reconstitution, use inactivated vaccines within the day, and change needles for each animal?","levels_en":["Exceeds the storage time after reconstitution and reuses needles, raising infection risk.","With guidance, handles vaccines, but is inconsistent about use-by time management and needle changes.","With guidance, uses live vaccines promptly after reconstitution and can adequately change needles.","Independently observes the time limit after reconstitution, uses vaccines up, and changes the needle for each animal.","Understands the risks of vaccine inactivation and needle reuse, and can teach new staff correct handling."],"name_vi":"Cách xử lý vắc-xin và thay kim tiêm","kanten_vi":"Vắc-xin sống có dùng hết ngay sau khi pha, vắc-xin bất hoạt dùng trong ngày, và thay kim theo từng con không.","levels_vi":["Để quá thời gian bảo quản sau khi pha, dùng lại kim tiêm làm tăng nguy cơ lây nhiễm.","Nếu có chỉ dẫn thì xử lý được, nhưng có bỏ sót việc quản lý thời gian dùng hết và thay kim.","Nếu có chỉ dẫn thì dùng vắc-xin sống ngay sau khi pha, thay kim được cơ bản.","Không cần chỉ dẫn cũng giữ đúng thời gian sau khi pha và dùng hết, thay kim theo từng con.","Hiểu nguy cơ vắc-xin mất hiệu lực và dùng lại kim, và có thể hướng dẫn người mới cách xử lý đúng."],"name_id":"Penanganan vaksin dan penggantian jarum","kanten_id":"Apakah vaksin hidup dihabiskan segera setelah dilarutkan, vaksin inaktif dipakai pada hari yang sama, dan jarum diganti setiap ekor.","levels_id":["Melewati batas waktu penyimpanan setelah vaksin dilarutkan, dan memakai jarum suntik bergantian sehingga menaikkan risiko infeksi.","Jika ada instruksi bisa menangani, tetapi sering lalai mengelola batas waktu pemakaian dan mengganti jarum.","Jika ada instruksi, bisa memakai vaksin hidup segera setelah dilarutkan dan mengganti jarum secara garis besar.","Tanpa instruksi pun, mematuhi batas waktu setelah pelarutan dan menghabiskannya, serta mengganti jarum setiap ekor.","Memahami risiko vaksin kehilangan daya dan pemakaian jarum bergantian, dan bisa mengajari karyawan baru penanganan yang benar."]}],"gyomu":"06","name_en":"Sow vaccination","purposeShort_en":"Build immunity that protects sows and piglets, and even out the farm's immunity level","name_vi":"Tiêm vắc-xin cho lợn nái","purposeShort_vi":"Tạo miễn dịch bảo vệ lợn nái và lợn con, làm đồng đều mức miễn dịch của trại","name_id":"Vaksinasi induk babi","purposeShort_id":"Membangun kekebalan yang melindungi induk babi dan anak babi, dan menyeragamkan tingkat kekebalan peternakan"},{"id":"csf-vaccine","category":"hygiene","no":"No.41","name":"CSF（豚熱）子ワクチン接種","purposeShort":"子豚の免疫を立ち上げ、豚熱の発生・死亡と経済被害を防ぐ","aspects":[{"id":"maternal-antibody","name":"移行抗体を考えた接種日齢","kanten":"移行抗体を考慮し、決められた日齢で接種して免疫獲得の失敗を防げるか。","levels":["移行抗体を考えず、抗体の高い時期に接種して免疫獲得を失敗させる。","指示があれば決められた日齢で接種するが、農場の抗体レベルへの意識が薄い。","指示があれば決められた日齢でひと通り接種できる。","指示がなくても移行抗体を考えた日齢で接種し、確実な免疫獲得を意識する。","移行抗体と免疫獲得の関係を理解し、農場の抗体レベルに応じた接種時期を新人に指導できる。"],"name_en":"Vaccination age accounting for maternal antibodies","kanten_en":"Can they take maternal antibodies into account and vaccinate at the prescribed age to prevent immunization failure?","levels_en":["Ignores maternal antibodies and vaccinates while antibody levels are high, causing immunization failure.","With guidance, vaccinates at the prescribed age, but has little awareness of the farm's antibody levels.","With guidance, can adequately vaccinate at the prescribed age.","Independently vaccinates at an age that accounts for maternal antibodies, keeping reliable immunization in mind.","Understands the relationship between maternal antibodies and immunization, and can teach new staff vaccination timing suited to the farm's antibody levels."],"name_vi":"Tuổi ngày tiêm có tính đến kháng thể mẹ truyền","kanten_vi":"Có tính đến kháng thể mẹ truyền, tiêm đúng tuổi ngày quy định để tránh thất bại trong việc tạo miễn dịch không.","levels_vi":["Không nghĩ đến kháng thể mẹ truyền, tiêm vào thời kỳ kháng thể còn cao làm việc tạo miễn dịch thất bại.","Nếu có chỉ dẫn thì tiêm đúng tuổi ngày quy định, nhưng ý thức về mức kháng thể của trại còn yếu.","Nếu có chỉ dẫn thì tiêm được cơ bản theo đúng tuổi ngày quy định.","Không cần chỉ dẫn cũng tiêm ở tuổi ngày có tính đến kháng thể mẹ truyền, ý thức việc tạo miễn dịch chắc chắn.","Hiểu quan hệ giữa kháng thể mẹ truyền và việc tạo miễn dịch, và có thể hướng dẫn người mới thời điểm tiêm theo mức kháng thể của trại."],"name_id":"Umur penyuntikan yang mempertimbangkan antibodi dari induk","kanten_id":"Apakah mempertimbangkan antibodi dari induk (antibodi maternal) dan menyuntik pada umur yang ditentukan, sehingga mencegah gagalnya pembentukan kekebalan.","levels_id":["Tidak memikirkan antibodi dari induk, menyuntik saat antibodi masih tinggi sehingga pembentukan kekebalan gagal.","Jika ada instruksi bisa menyuntik pada umur yang ditentukan, tetapi kesadaran terhadap tingkat antibodi peternakan masih lemah.","Jika ada instruksi, bisa menyuntik secara garis besar pada umur yang ditentukan.","Tanpa instruksi pun, menyuntik pada umur yang mempertimbangkan antibodi dari induk, dan sadar akan pembentukan kekebalan yang pasti.","Memahami hubungan antibodi dari induk dengan pembentukan kekebalan, dan bisa mengajari karyawan baru waktu penyuntikan sesuai tingkat antibodi peternakan."]},{"id":"no-miss","name":"全頭接種と記録","kanten":"全頭に確実に接種し、打ち漏れを作らず接種記録を残せるか。","levels":["打ち漏れを確認せず、接種記録も残さないため漏れが把握できない。","指示があれば接種するが、全頭確認や記録に漏れが多い。","指示があれば全頭にひと通り接種し、記録できる。","指示がなくても打ち漏れがないか確かめ、接種記録を確実に残す。","打ち漏れが防疫上の穴になることを理解し、全頭接種と記録の徹底を新人に指導できる。"],"name_en":"Whole-herd vaccination and records","kanten_en":"Can they reliably vaccinate every animal, leave no missed injections, and keep vaccination records?","levels_en":["Does not check for missed injections and keeps no vaccination records, so omissions cannot be tracked.","With guidance, vaccinates, but often fails at whole-herd confirmation and record-keeping.","With guidance, can adequately vaccinate all animals and keep records.","Independently verifies there are no missed injections and reliably keeps vaccination records.","Understands that missed injections become holes in biosecurity, and can teach new staff thorough whole-herd vaccination and record-keeping."],"name_vi":"Tiêm đủ cả đàn và ghi chép","kanten_vi":"Có tiêm chắc chắn cho tất cả các con, không để sót và để lại ghi chép tiêm phòng không.","levels_vi":["Không kiểm tra con bị sót tiêm, cũng không để lại ghi chép nên không nắm được sót con nào.","Nếu có chỉ dẫn thì tiêm, nhưng hay bỏ sót việc kiểm tra cả đàn và ghi chép.","Nếu có chỉ dẫn thì tiêm được cơ bản cho cả đàn và ghi chép được.","Không cần chỉ dẫn cũng kiểm tra xem có con nào bị sót tiêm không, để lại ghi chép tiêm phòng chắc chắn.","Hiểu con sót tiêm là lỗ hổng trong phòng dịch, và có thể hướng dẫn người mới việc tiêm đủ cả đàn và ghi chép nghiêm túc."],"name_id":"Penyuntikan semua ekor dan pencatatan","kanten_id":"Apakah menyuntik semua ekor dengan pasti, tidak ada yang terlewat, dan meninggalkan catatan penyuntikan.","levels_id":["Tidak memeriksa ada tidaknya yang terlewat, tidak meninggalkan catatan penyuntikan sehingga yang terlewat tidak bisa diketahui.","Jika ada instruksi bisa menyuntik, tetapi sering lalai memeriksa semua ekor dan mencatat.","Jika ada instruksi, bisa menyuntik semua ekor secara garis besar dan mencatatnya.","Tanpa instruksi pun, memastikan tidak ada yang terlewat dan meninggalkan catatan penyuntikan dengan pasti.","Memahami bahwa penyuntikan yang terlewat menjadi lubang biosekuriti, dan bisa mengajari karyawan baru pentingnya penyuntikan semua ekor dan pencatatan."]}],"gyomu":"41","name_en":"CSF (classical swine fever) piglet vaccination","purposeShort_en":"Establish piglet immunity and prevent CSF outbreaks, deaths, and economic damage","name_vi":"Tiêm vắc-xin CSF (dịch tả lợn cổ điển) cho lợn con","purposeShort_vi":"Tạo miễn dịch cho lợn con, phòng bệnh dịch tả lợn phát sinh, chết và thiệt hại kinh tế","name_id":"Vaksinasi CSF (demam babi klasik) untuk anak babi","purposeShort_id":"Membangun kekebalan anak babi, mencegah kejadian dan kematian demam babi klasik serta kerugian ekonomi"},{"id":"vaccine-assist","category":"hygiene","no":"No.45","name":"子ワクチン補助","purposeShort":"接種漏れ・誤接種を防ぎ、安全に正しい部位・量で接種できる環境を作る","aspects":[{"id":"role-restraint","name":"役割分担・声かけと保定","kanten":"役割分担と声かけを明確にし、豚を落ち着かせて無理のない保定ができるか。","levels":["役割分担や声かけをせず、豚を無理に保定して暴れさせる。","指示があれば補助するが、声かけや保定が不十分で接種を難しくする。","指示があれば役割分担に従い、ひと通り保定を補助できる。","指示がなくても声かけで連携し、豚を落ち着かせて安全に保定する。","安全な接種環境づくりの要点を理解し、役割分担と保定のコツを新人に指導できる。"],"name_en":"Role assignment, communication, and restraint","kanten_en":"Can they clarify roles and verbal cues, calm the pigs, and restrain them without force?","levels_en":["Works without role assignment or verbal cues, restrains pigs forcibly, and makes them struggle.","With guidance, assists, but poor communication and restraint make the injections difficult.","With guidance, follows the role assignment and can adequately assist with restraint.","Independently coordinates with verbal cues, calms the pigs, and restrains them safely.","Understands the essentials of creating a safe injection environment, and can teach new staff role assignment and restraint techniques."],"name_vi":"Phân công, gọi báo nhau và giữ lợn","kanten_vi":"Có phân công và gọi báo nhau rõ ràng, làm lợn bình tĩnh và giữ lợn không quá sức không.","levels_vi":["Không phân công và không gọi báo nhau, giữ lợn quá mạnh làm lợn giãy giụa.","Nếu có chỉ dẫn thì hỗ trợ, nhưng gọi báo và giữ lợn chưa tốt, làm việc tiêm khó hơn.","Nếu có chỉ dẫn thì làm theo phân công, hỗ trợ giữ lợn được cơ bản.","Không cần chỉ dẫn cũng phối hợp bằng cách gọi báo nhau, làm lợn bình tĩnh và giữ lợn an toàn.","Hiểu các điểm chính để tạo môi trường tiêm an toàn, và có thể hướng dẫn người mới cách phân công và mẹo giữ lợn."],"name_id":"Pembagian peran, saling memberi aba-aba, dan memegangi babi","kanten_id":"Apakah pembagian peran dan aba-aba jelas, dan bisa memegangi babi tanpa paksaan dengan menenangkannya.","levels_id":["Tidak membagi peran atau memberi aba-aba, dan memegangi babi dengan paksa sehingga babi berontak.","Jika ada instruksi bisa membantu, tetapi aba-aba dan cara memegangi kurang baik sehingga menyulitkan penyuntikan.","Jika ada instruksi, bisa mengikuti pembagian peran dan membantu memegangi babi secara garis besar.","Tanpa instruksi pun, bekerja sama dengan aba-aba, menenangkan babi, dan memeganginya dengan aman.","Memahami poin-poin menciptakan lingkungan penyuntikan yang aman, dan bisa mengajari karyawan baru pembagian peran dan trik memegangi babi."]},{"id":"site-needle","name":"接種部位・針・残留の確認","kanten":"正しい部位・量・針で確実に筋注し、接種後の針折れ・針残留を確認してマーキングできるか。","levels":["浅く筋注できていない、成豚用量を子豚に投与する、針残留を確認しないなど危険な補助をする。","指示があれば補助するが、針の選択や残留確認、マーキングに漏れがある。","指示があれば正しい部位・量で接種を補助し、接種後にマーキングできる。","指示がなくても針の選択と体重・日齢を確認し、針折れ・残留を確かめてマーキングする。","針残留や誤用量の危険を理解し、確実な接種と確認の手順を新人に指導できる。"],"name_en":"Checking injection site, needles, and retained needles","kanten_en":"Can they inject intramuscularly at the correct site, dose, and needle, then check for broken or retained needles and mark the animal?","levels_en":["Assists dangerously — injections too shallow to be intramuscular, adult doses given to piglets, retained needles not checked.","With guidance, assists, but is inconsistent about needle selection, retained-needle checks, and marking.","With guidance, assists with injection at the correct site and dose and can mark animals after injection.","Independently checks needle selection against body weight and age, verifies no broken or retained needles, and marks the animals.","Understands the dangers of retained needles and wrong doses, and can teach new staff reliable injection and verification procedures."],"name_vi":"Kiểm tra vị trí tiêm, kim tiêm và kim sót lại","kanten_vi":"Có tiêm bắp chắc chắn đúng vị trí, đúng liều, đúng kim, kiểm tra kim gãy, kim sót lại sau tiêm và đánh dấu không.","levels_vi":["Hỗ trợ nguy hiểm như tiêm nông không vào bắp, tiêm liều của lợn lớn cho lợn con, không kiểm tra kim sót lại.","Nếu có chỉ dẫn thì hỗ trợ, nhưng có bỏ sót việc chọn kim, kiểm tra kim sót lại và đánh dấu.","Nếu có chỉ dẫn thì hỗ trợ tiêm đúng vị trí, đúng liều, đánh dấu được sau khi tiêm.","Không cần chỉ dẫn cũng kiểm tra việc chọn kim, cân nặng, tuổi ngày, kiểm tra kim gãy, kim sót lại rồi đánh dấu.","Hiểu nguy hiểm của kim sót lại và sai liều, và có thể hướng dẫn người mới quy trình tiêm và kiểm tra chắc chắn."],"name_id":"Pemeriksaan lokasi suntik, jarum, dan jarum tertinggal","kanten_id":"Apakah bisa menyuntik ke otot dengan pasti pada lokasi, dosis, dan jarum yang benar, lalu memeriksa jarum patah atau tertinggal setelah penyuntikan dan memberi tanda (marking).","levels_id":["Membantu dengan cara berbahaya, misalnya suntikan terlalu dangkal sehingga tidak masuk otot, memberi dosis babi dewasa ke anak babi, atau tidak memeriksa jarum tertinggal.","Jika ada instruksi bisa membantu, tetapi sering lalai memilih jarum, memeriksa jarum tertinggal, dan memberi tanda.","Jika ada instruksi, bisa membantu penyuntikan dengan lokasi dan dosis yang benar, serta memberi tanda setelah penyuntikan.","Tanpa instruksi pun, memeriksa pilihan jarum serta berat badan dan umur, memastikan tidak ada jarum patah atau tertinggal, lalu memberi tanda.","Memahami bahaya jarum tertinggal dan dosis yang salah, dan bisa mengajari karyawan baru urutan penyuntikan dan pemeriksaan yang pasti."]}],"gyomu":"45","name_en":"Piglet vaccination assistance","purposeShort_en":"Prevent missed and incorrect injections, creating a safe environment for injecting the right site and dose","name_vi":"Hỗ trợ tiêm vắc-xin cho lợn con","purposeShort_vi":"Phòng sót tiêm và tiêm nhầm, tạo môi trường tiêm an toàn, đúng vị trí và đúng liều","name_id":"Membantu vaksinasi anak babi","purposeShort_id":"Mencegah vaksin terlewat atau salah suntik, dan menciptakan lingkungan penyuntikan yang aman dengan lokasi dan dosis yang benar"},{"id":"washing","category":"hygiene","no":"No.40","name":"洗浄（離乳後）","purposeShort":"汚れと病原体を物理的に落とし、消毒が効く状態を作り舎内をリセットする","aspects":[{"id":"wash-order","name":"除糞→洗浄→乾燥→消毒の順序","kanten":"決められた順序を守り、有機物を残したまま消毒しないか、洗浄後に十分乾燥できるか。","levels":["有機物が残った状態で消毒薬を散布し、乾燥不十分のまま次ロットを入れる。","指示があれば洗浄するが、順序や乾燥の徹底に漏れが多い。","指示があれば除糞→洗浄→乾燥→消毒の順序をひと通り守れる。","指示がなくても順序を守り、有機物を落としてから消毒し、十分に乾燥させる。","有機物残存が消毒を無効化することを理解し、洗浄・乾燥の徹底を新人に指導できる。"],"name_en":"Order of manure removal, washing, drying, then disinfection","kanten_en":"Do they follow the prescribed order, avoid disinfecting over organic matter, and dry thoroughly after washing?","levels_en":["Sprays disinfectant over remaining organic matter and brings in the next lot without sufficient drying.","With guidance, washes, but often skips steps in the order and fails to dry thoroughly.","With guidance, can adequately follow the order of manure removal, washing, drying, then disinfection.","Independently follows the order, removes organic matter before disinfecting, and dries thoroughly.","Understands that remaining organic matter neutralizes disinfection, and can teach new staff thorough washing and drying."],"name_vi":"Thứ tự dọn phân → rửa → làm khô → khử trùng","kanten_vi":"Có giữ đúng thứ tự quy định, không khử trùng khi chất hữu cơ còn sót, và làm khô đủ sau khi rửa không.","levels_vi":["Phun thuốc khử trùng khi chất hữu cơ còn sót, đưa lứa lợn mới vào khi chuồng chưa khô đủ.","Nếu có chỉ dẫn thì rửa, nhưng hay bỏ sót thứ tự và việc làm khô kỹ.","Nếu có chỉ dẫn thì giữ được cơ bản thứ tự dọn phân → rửa → làm khô → khử trùng.","Không cần chỉ dẫn cũng giữ đúng thứ tự, loại bỏ chất hữu cơ trước rồi mới khử trùng, làm khô đầy đủ.","Hiểu chất hữu cơ còn sót làm khử trùng mất tác dụng, và có thể hướng dẫn người mới việc rửa và làm khô kỹ."],"name_id":"Urutan bersihkan kotoran → cuci → keringkan → disinfeksi","kanten_id":"Apakah mematuhi urutan yang ditentukan, tidak mendisinfeksi selagi bahan organik masih tersisa, dan bisa mengeringkan dengan cukup setelah mencuci.","levels_id":["Menyemprotkan disinfektan dalam keadaan bahan organik masih tersisa, dan memasukkan kelompok berikutnya selagi belum kering.","Jika ada instruksi bisa mencuci, tetapi sering lalai mematuhi urutan dan pengeringan menyeluruh.","Jika ada instruksi, bisa mematuhi urutan secara garis besar: bersihkan kotoran → cuci → keringkan → disinfeksi.","Tanpa instruksi pun, mematuhi urutan, menghilangkan bahan organik dulu baru mendisinfeksi, dan mengeringkan dengan cukup.","Memahami bahwa bahan organik yang tersisa membuat disinfeksi tidak berguna, dan bisa mengajari karyawan baru pentingnya pencucian dan pengeringan menyeluruh."]},{"id":"hidden-spots","name":"隅・溝・裏側の重点洗浄","kanten":"隅・溝・エサ箱・スノコ裏など汚れが溜まりやすい見えにくい場所を重点的に洗えるか。","levels":["見えやすい所だけ洗い、隅・溝・スノコ裏などの汚れを残す。","指示があれば洗うが、見えにくい場所の洗浄に漏れが多い。","指示があれば汚れが溜まりやすい場所をひと通り洗える。","指示がなくても隅・溝・スノコ裏まで重点的に洗い、汚れを残さない。","見えにくい場所の病原残存リスクを理解し、重点洗浄の着眼点を新人に指導できる。"],"name_en":"Focused washing of corners, grooves, and undersides","kanten_en":"Can they focus on hard-to-see spots where dirt accumulates — corners, grooves, feed boxes, and the undersides of slats?","levels_en":["Washes only visible areas, leaving dirt in corners, grooves, and under the slats.","With guidance, washes, but often misses hard-to-see spots.","With guidance, can adequately wash the spots where dirt accumulates.","Independently focuses on corners, grooves, and slat undersides, leaving no dirt behind.","Understands the risk of pathogens surviving in hard-to-see spots, and can teach new staff where to focus the washing."],"name_vi":"Rửa kỹ góc, rãnh và mặt sau","kanten_vi":"Có rửa kỹ những chỗ khó nhìn thấy, dễ đọng bẩn như góc, rãnh, máng ăn, mặt sau sàn khe không.","levels_vi":["Chỉ rửa chỗ dễ nhìn thấy, để sót bẩn ở góc, rãnh, mặt sau sàn khe.","Nếu có chỉ dẫn thì rửa, nhưng hay bỏ sót việc rửa những chỗ khó nhìn thấy.","Nếu có chỉ dẫn thì rửa được cơ bản những chỗ dễ đọng bẩn.","Không cần chỉ dẫn cũng rửa kỹ đến tận góc, rãnh, mặt sau sàn khe, không để sót bẩn.","Hiểu nguy cơ mầm bệnh còn sót ở những chỗ khó nhìn thấy, và có thể hướng dẫn người mới các điểm cần chú ý khi rửa kỹ."],"name_id":"Pencucian intensif sudut, parit, dan bagian belakang","kanten_id":"Apakah bisa mencuci secara intensif tempat-tempat tersembunyi yang mudah menumpuk kotoran seperti sudut, parit, kotak pakan, dan bagian bawah lantai slat.","levels_id":["Hanya mencuci bagian yang mudah terlihat, meninggalkan kotoran di sudut, parit, dan bawah lantai slat.","Jika ada instruksi bisa mencuci, tetapi sering lalai mencuci tempat yang sulit terlihat.","Jika ada instruksi, bisa mencuci secara garis besar tempat-tempat yang mudah menumpuk kotoran.","Tanpa instruksi pun, mencuci intensif sampai sudut, parit, dan bawah lantai slat tanpa meninggalkan kotoran.","Memahami risiko bibit penyakit yang tersisa di tempat yang sulit terlihat, dan bisa mengajari karyawan baru titik fokus pencucian intensif."]}],"gyomu":"40","name_en":"Washing (post-weaning)","purposeShort_en":"Physically remove dirt and pathogens, create conditions where disinfection works, and reset the barn","name_vi":"Rửa chuồng (sau cai sữa)","purposeShort_vi":"Loại bỏ chất bẩn và mầm bệnh bằng cách rửa, tạo trạng thái để khử trùng có tác dụng, làm mới lại chuồng","name_id":"Mencuci kandang (setelah sapih)","purposeShort_id":"Menghilangkan kotoran dan bibit penyakit secara fisik, membuat kondisi agar disinfeksi bekerja, dan mereset bagian dalam kandang"},{"id":"disinfect","category":"hygiene","no":"No.15","name":"消毒","purposeShort":"病原体を入れない・広げない・持ち出さず、農場の防疫レベルを保つ","aspects":[{"id":"concentration","name":"濃度・量・接触時間の遵守","kanten":"決められた濃度・量・接触時間を守り、目分量の希釈をしないか。","levels":["希釈濃度を目分量で調整し、接触時間も守らず規定を外す。","指示があれば希釈するが、濃度や接触時間の管理に漏れが多い。","指示があれば決められた濃度・量・接触時間をひと通り守れる。","指示がなくても正確に希釈し、接触時間を確保してから乾燥させる。","薬剤ごとの特性と濃度・接触時間の意味を理解し、正しい消毒を新人に指導できる。"],"name_en":"Following concentration, volume, and contact time","kanten_en":"Do they follow the prescribed concentration, volume, and contact time, without diluting by eye?","levels_en":["Adjusts dilution by eye and ignores contact times, deviating from the standards.","With guidance, dilutes, but often fails to manage concentration and contact time.","With guidance, can adequately follow the prescribed concentration, volume, and contact time.","Independently dilutes accurately and secures the contact time before allowing surfaces to dry.","Understands each chemical's characteristics and the meaning of concentration and contact time, and can teach new staff correct disinfection."],"name_vi":"Giữ đúng nồng độ, lượng và thời gian tiếp xúc","kanten_vi":"Có giữ đúng nồng độ, lượng và thời gian tiếp xúc quy định, không pha loãng theo ước lượng bằng mắt không.","levels_vi":["Pha loãng theo ước lượng bằng mắt, không giữ thời gian tiếp xúc, làm sai quy định.","Nếu có chỉ dẫn thì pha loãng, nhưng hay bỏ sót việc quản lý nồng độ và thời gian tiếp xúc.","Nếu có chỉ dẫn thì giữ được cơ bản nồng độ, lượng và thời gian tiếp xúc quy định.","Không cần chỉ dẫn cũng pha loãng chính xác, bảo đảm thời gian tiếp xúc rồi mới làm khô.","Hiểu đặc tính từng loại thuốc và ý nghĩa của nồng độ, thời gian tiếp xúc, và có thể hướng dẫn người mới cách khử trùng đúng."],"name_id":"Mematuhi konsentrasi, jumlah, dan waktu kontak","kanten_id":"Apakah mematuhi konsentrasi, jumlah, dan waktu kontak yang ditentukan, dan tidak mengencerkan dengan kira-kira.","levels_id":["Mengatur konsentrasi pengenceran dengan kira-kira, tidak mematuhi waktu kontak, dan keluar dari ketentuan.","Jika ada instruksi bisa mengencerkan, tetapi sering lalai mengelola konsentrasi dan waktu kontak.","Jika ada instruksi, bisa mematuhi secara garis besar konsentrasi, jumlah, dan waktu kontak yang ditentukan.","Tanpa instruksi pun, mengencerkan dengan akurat, memastikan waktu kontak tercapai, lalu membiarkannya kering.","Memahami sifat tiap bahan disinfektan serta arti konsentrasi dan waktu kontak, dan bisa mengajari karyawan baru cara disinfeksi yang benar."]},{"id":"clean-first-ppe","name":"汚れ除去の徹底と防護具着用","kanten":"汚れを先に落としてから消毒し、防護マスク・ゴーグルを着けて曝露を防げるか。","levels":["有機物が残った面に散布して消毒剤を不活化させ、防護具も着けず薬剤に曝露する。","指示があれば汚れを落とすが、防護具の着用や汚れ除去の徹底に漏れがある。","指示があれば汚れを落としてから消毒し、防護具をひと通り着用できる。","指示がなくても汚れを確実に落としてから消毒し、防護具を着けて安全に作業する。","有機物による不活化と薬剤曝露の危険を理解し、汚れ除去と防護の徹底を新人に指導できる。"],"name_en":"Thorough dirt removal first and wearing protective gear","kanten_en":"Can they remove dirt before disinfecting, and wear a protective mask and goggles to prevent chemical exposure?","levels_en":["Sprays onto surfaces with organic matter, inactivating the disinfectant, and works without protective gear, exposing themselves to chemicals.","With guidance, removes dirt, but is inconsistent about wearing protective gear and removing dirt thoroughly.","With guidance, removes dirt before disinfecting and can adequately wear protective gear.","Independently removes dirt thoroughly before disinfecting and works safely in protective gear.","Understands inactivation by organic matter and the dangers of chemical exposure, and can teach new staff thorough dirt removal and protection."],"name_vi":"Loại bỏ bẩn kỹ trước và đeo đồ bảo hộ","kanten_vi":"Có loại bỏ chất bẩn trước rồi mới khử trùng, đeo khẩu trang và kính bảo hộ để tránh phơi nhiễm thuốc không.","levels_vi":["Phun lên bề mặt còn chất hữu cơ làm thuốc khử trùng mất tác dụng, không đeo đồ bảo hộ nên bị phơi nhiễm thuốc.","Nếu có chỉ dẫn thì loại bỏ bẩn, nhưng có bỏ sót việc đeo đồ bảo hộ và việc làm sạch kỹ.","Nếu có chỉ dẫn thì loại bỏ bẩn trước rồi mới khử trùng, đeo được cơ bản đồ bảo hộ.","Không cần chỉ dẫn cũng loại bỏ bẩn chắc chắn trước khi khử trùng, đeo đồ bảo hộ và làm việc an toàn.","Hiểu chất hữu cơ làm thuốc mất tác dụng và nguy hiểm khi phơi nhiễm thuốc, và có thể hướng dẫn người mới việc làm sạch và bảo hộ kỹ."],"name_id":"Menghilangkan kotoran dengan tuntas dan memakai alat pelindung","kanten_id":"Apakah menghilangkan kotoran dulu baru mendisinfeksi, dan memakai masker pelindung serta kacamata pelindung agar tidak terpapar bahan kimia.","levels_id":["Menyemprot ke permukaan yang masih ada bahan organik sehingga disinfektan tidak bekerja, dan terpapar bahan kimia karena tidak memakai alat pelindung.","Jika ada instruksi bisa menghilangkan kotoran, tetapi sering lalai memakai alat pelindung dan menghilangkan kotoran dengan tuntas.","Jika ada instruksi, bisa menghilangkan kotoran dulu baru mendisinfeksi, dan memakai alat pelindung secara garis besar.","Tanpa instruksi pun, menghilangkan kotoran dengan pasti sebelum mendisinfeksi, dan bekerja dengan aman memakai alat pelindung.","Memahami disinfektan yang tidak bekerja karena bahan organik dan bahaya paparan bahan kimia, dan bisa mengajari karyawan baru pentingnya menghilangkan kotoran dan perlindungan diri."]}],"gyomu":"15","name_en":"Disinfection","purposeShort_en":"Keep pathogens out, contained, and off the farm, maintaining the farm's biosecurity level","name_vi":"Khử trùng","purposeShort_vi":"Không cho mầm bệnh vào, không làm lan rộng, không mang ra ngoài, giữ mức phòng dịch của trại","name_id":"Disinfeksi","purposeShort_id":"Tidak memasukkan, tidak menyebarkan, dan tidak membawa keluar bibit penyakit, menjaga tingkat biosekuriti peternakan"},{"id":"lime","category":"hygiene","no":"No.44","name":"石灰散布","purposeShort":"農場出入口に防疫バリアを作り、病原体の侵入・拡散を抑える","aspects":[{"id":"moisture","name":"含水と散布量の管理","kanten":"地面が白く見える量を目安に、乾燥粉末のままでなく消毒効果の出る状態で散布できるか。","levels":["乾燥粉末のまま散布し、量の目安も守らず消毒効果を出せない。","指示があれば散布するが、含水や量の管理に漏れがある。","指示があれば地面が白く見える量を目安にひと通り散布できる。","指示がなくても消毒効果の出る含水状態にし、劣化を見て定期的に補充する。","石灰の消毒が効く条件（含水率）を理解し、散布量と補充の管理を新人に指導できる。"],"name_en":"Managing moisture content and application amount","kanten_en":"Can they spread lime in a state where it disinfects — not as dry powder — using visible whitening of the ground as a guide for the amount?","levels_en":["Spreads dry powder as-is and ignores the amount guideline, achieving no disinfectant effect.","With guidance, spreads lime, but is inconsistent about managing moisture and amount.","With guidance, can adequately spread lime using visible whitening of the ground as the amount guide.","Independently keeps the lime at a moisture level where it disinfects, and replenishes it regularly as it degrades.","Understands the conditions (moisture content) under which lime disinfects, and can teach new staff how to manage application amounts and replenishment."],"name_vi":"Quản lý độ ẩm và lượng rắc","kanten_vi":"Có rắc với lượng đủ để mặt đất nhìn thấy trắng, ở trạng thái có độ ẩm để phát huy tác dụng khử trùng, không để nguyên dạng bột khô không.","levels_vi":["Rắc nguyên dạng bột khô, cũng không giữ lượng chuẩn nên không có tác dụng khử trùng.","Nếu có chỉ dẫn thì rắc, nhưng có bỏ sót việc quản lý độ ẩm và lượng rắc.","Nếu có chỉ dẫn thì rắc được cơ bản với lượng đủ để mặt đất nhìn thấy trắng.","Không cần chỉ dẫn cũng giữ trạng thái độ ẩm để có tác dụng khử trùng, nhìn độ xuống cấp để bổ sung định kỳ.","Hiểu điều kiện để vôi khử trùng có tác dụng (tỷ lệ độ ẩm), và có thể hướng dẫn người mới cách quản lý lượng rắc và bổ sung."],"name_id":"Pengelolaan kelembapan dan jumlah taburan","kanten_id":"Apakah bisa menabur dengan patokan tanah terlihat putih, dalam keadaan yang memberi efek disinfeksi, bukan berupa bubuk kering begitu saja.","levels_id":["Menabur dalam keadaan bubuk kering, tidak mematuhi patokan jumlah, sehingga efek disinfeksi tidak keluar.","Jika ada instruksi bisa menabur, tetapi sering lalai mengelola kelembapan dan jumlah.","Jika ada instruksi, bisa menabur secara garis besar dengan patokan tanah terlihat putih.","Tanpa instruksi pun, membuat keadaan lembap yang memberi efek disinfeksi, dan menambah taburan secara berkala dengan melihat penurunan mutunya.","Memahami syarat kapur bisa mendisinfeksi (kadar air), dan bisa mengajari karyawan baru pengelolaan jumlah taburan dan penambahannya."]},{"id":"wind-safety","name":"風向き確認と防護","kanten":"風向きを確認して粉末飛散を防ぎ、人・豚にかからないよう防護具を着けて散布できるか。","levels":["風向きを確認せず粉末を飛散させ、防護具も着けず呼吸器障害や周辺苦情を招く。","指示があれば注意するが、風向き確認や防護具着用に漏れがある。","指示があれば人・豚に直接かからないようひと通り注意して散布できる。","指示がなくても風向きを確認して飛散を防ぎ、防護具を着けて安全に散布する。","飛散による健康被害・苦情のリスクを理解し、安全な散布方法を新人に指導できる。"],"name_en":"Checking wind direction and protection","kanten_en":"Can they check the wind direction to prevent powder drift, and wear protective gear so the lime does not land on people or pigs?","levels_en":["Scatters powder without checking wind direction and works without protective gear, causing respiratory harm and neighborhood complaints.","With guidance, takes care, but is inconsistent about checking wind direction and wearing protective gear.","With guidance, can spread lime with adequate care to keep it off people and pigs.","Independently checks wind direction to prevent drift and spreads lime safely in protective gear.","Understands the health and complaint risks of powder drift, and can teach new staff safe spreading methods."],"name_vi":"Kiểm tra hướng gió và bảo hộ","kanten_vi":"Có kiểm tra hướng gió để tránh bột bay tán, đeo đồ bảo hộ và rắc sao cho không dính vào người và lợn không.","levels_vi":["Không kiểm tra hướng gió làm bột bay tán, không đeo đồ bảo hộ, gây hại đường hô hấp và khiếu nại từ xung quanh.","Nếu có chỉ dẫn thì chú ý, nhưng có bỏ sót việc kiểm tra hướng gió và đeo đồ bảo hộ.","Nếu có chỉ dẫn thì rắc được với sự chú ý cơ bản để không dính trực tiếp vào người và lợn.","Không cần chỉ dẫn cũng kiểm tra hướng gió để tránh bay tán, đeo đồ bảo hộ và rắc an toàn.","Hiểu nguy cơ hại sức khỏe và khiếu nại do bột bay tán, và có thể hướng dẫn người mới cách rắc an toàn."],"name_id":"Pemeriksaan arah angin dan perlindungan diri","kanten_id":"Apakah memeriksa arah angin untuk mencegah bubuk beterbangan, dan bisa menabur dengan memakai alat pelindung agar tidak mengenai orang dan babi.","levels_id":["Menabur tanpa memeriksa arah angin sehingga bubuk beterbangan, tidak memakai alat pelindung sehingga menyebabkan gangguan pernapasan dan keluhan warga sekitar.","Jika ada instruksi bisa berhati-hati, tetapi sering lalai memeriksa arah angin dan memakai alat pelindung.","Jika ada instruksi, bisa menabur dengan cukup hati-hati agar tidak langsung mengenai orang dan babi.","Tanpa instruksi pun, memeriksa arah angin untuk mencegah bubuk beterbangan, dan menabur dengan aman memakai alat pelindung.","Memahami risiko gangguan kesehatan dan keluhan akibat bubuk beterbangan, dan bisa mengajari karyawan baru cara menabur yang aman."]}],"gyomu":"44","name_en":"Lime spreading","purposeShort_en":"Create a biosecurity barrier at farm entrances and suppress pathogen entry and spread","name_vi":"Rắc vôi bột (khử trùng bằng vôi)","purposeShort_vi":"Tạo hàng rào phòng dịch ở lối ra vào trại, ngăn mầm bệnh xâm nhập và lan rộng","name_id":"Menaburkan kapur (disinfeksi dengan kapur)","purposeShort_id":"Membuat penghalang biosekuriti di pintu masuk-keluar peternakan, menekan masuk dan menyebarnya bibit penyakit"},{"id":"carcass","category":"hygiene","no":"No.37","name":"死獣回収","purposeShort":"病原体の拡散と悪臭・害獣被害を防ぎ、法令を守る","aspects":[{"id":"prompt-storage","name":"速やかな回収と専用保管","kanten":"死亡確認後すぐに回収し、豚房内に放置せず専用の保管場所へ入れられるか。","levels":["死体を豚房内に放置し、他の豚が接触して感染源になっても気にしない。","指示があれば回収するが、回収の遅れや保管場所の管理に漏れがある。","指示があれば死亡確認後にひと通り回収し、専用保管場所へ入れられる。","指示がなくても速やかに回収して専用場所へ入れ、感染源化を防ぐ。","死体放置の感染リスクを理解し、速やかな回収・保管の手順を新人に指導できる。"],"name_en":"Prompt collection and dedicated storage","kanten_en":"Can they collect carcasses immediately after confirming death, without leaving them in the pen, and place them in dedicated storage?","levels_en":["Leaves carcasses in the pen and does not care that other pigs touch them and they become an infection source.","With guidance, collects carcasses, but collection is delayed and storage management is inconsistent.","With guidance, can adequately collect carcasses after confirming death and place them in dedicated storage.","Independently collects carcasses promptly and moves them to the dedicated area, preventing them from becoming an infection source.","Understands the infection risk of leaving carcasses, and can teach new staff the procedures for prompt collection and storage."],"name_vi":"Thu gom nhanh và cất giữ ở nơi chuyên dùng","kanten_vi":"Sau khi xác nhận lợn chết có thu gom ngay, không để trong ô chuồng mà đưa vào nơi cất giữ chuyên dùng không.","levels_vi":["Để xác lợn trong ô chuồng, lợn khác chạm vào thành nguồn lây nhiễm cũng không quan tâm.","Nếu có chỉ dẫn thì thu gom, nhưng có chậm trễ và bỏ sót việc quản lý nơi cất giữ.","Nếu có chỉ dẫn thì thu gom được cơ bản sau khi xác nhận lợn chết, đưa vào nơi cất giữ chuyên dùng.","Không cần chỉ dẫn cũng thu gom nhanh và đưa vào nơi chuyên dùng, ngăn xác trở thành nguồn lây nhiễm.","Hiểu nguy cơ lây nhiễm khi để xác lợn, và có thể hướng dẫn người mới quy trình thu gom, cất giữ nhanh chóng."],"name_id":"Pengumpulan segera dan penyimpanan khusus","kanten_id":"Apakah segera mengumpulkan setelah kematian dipastikan, tidak membiarkannya di dalam petak kandang, dan memasukkannya ke tempat penyimpanan khusus.","levels_id":["Membiarkan bangkai di dalam petak kandang, dan tidak peduli walau babi lain menyentuhnya dan menjadi sumber infeksi.","Jika ada instruksi bisa mengumpulkan, tetapi sering terlambat mengumpulkan dan lalai mengelola tempat penyimpanan.","Jika ada instruksi, bisa mengumpulkan secara garis besar setelah kematian dipastikan, dan memasukkannya ke tempat penyimpanan khusus.","Tanpa instruksi pun, segera mengumpulkan dan memasukkannya ke tempat khusus, sehingga mencegahnya menjadi sumber infeksi.","Memahami risiko infeksi dari bangkai yang dibiarkan, dan bisa mengajari karyawan baru urutan pengumpulan dan penyimpanan yang cepat."]},{"id":"law-record","name":"法令遵守と死亡記録","kanten":"堆肥混入などの違法処理を避け、感染症疑いは自己判断せず、死亡状況を記録できるか。","levels":["死亡子豚を堆肥に混入するなど違法な処理をし、記録も残さない。","指示されれば記録するが、法令の理解が浅く記録に漏れが多い。","指示があれば専用処理へ回し、死亡状況をひと通り記録できる。","指示がなくても法令に沿って処理し、感染症疑いは自己判断せず、死亡日・頭数・原因を記録する。","化製場法・廃棄物処理法の要点を理解し、正しい処理と記録を新人に指導できる。"],"name_en":"Legal compliance and mortality records","kanten_en":"Can they avoid illegal disposal such as mixing into compost, not self-judge suspected infectious diseases, and record the circumstances of death?","levels_en":["Disposes of carcasses illegally, such as mixing dead piglets into compost, and keeps no records.","Records when instructed, but has a shallow understanding of the law and many recording omissions.","With guidance, sends carcasses to dedicated disposal and can adequately record the circumstances of death.","Independently disposes of carcasses in accordance with the law, never self-judges suspected infectious diseases, and records the date, number, and cause of death.","Understands the key points of the rendering plant and waste disposal laws, and can teach new staff correct disposal and record-keeping."],"name_vi":"Tuân thủ pháp luật và ghi chép lợn chết","kanten_vi":"Có tránh xử lý trái pháp luật như trộn vào phân ủ, không tự phán đoán khi nghi bệnh truyền nhiễm, và ghi chép được tình trạng chết không.","levels_vi":["Xử lý trái pháp luật như trộn lợn con chết vào phân ủ, cũng không để lại ghi chép.","Nếu được chỉ dẫn thì ghi chép, nhưng hiểu biết pháp luật còn nông, hay bỏ sót ghi chép.","Nếu có chỉ dẫn thì chuyển sang xử lý chuyên dùng, ghi chép được cơ bản tình trạng chết.","Không cần chỉ dẫn cũng xử lý theo pháp luật, nghi bệnh truyền nhiễm thì không tự phán đoán, ghi chép ngày chết, số con, nguyên nhân.","Hiểu các điểm chính của luật về cơ sở xử lý xác động vật (化製場法) và luật xử lý chất thải (廃棄物処理法), và có thể hướng dẫn người mới cách xử lý và ghi chép đúng."],"name_id":"Kepatuhan peraturan dan pencatatan kematian","kanten_id":"Apakah menghindari pemrosesan ilegal seperti mencampur ke kompos, tidak memutuskan sendiri jika dicurigai penyakit menular, dan bisa mencatat keadaan kematian.","levels_id":["Melakukan pemrosesan ilegal seperti mencampur anak babi yang mati ke kompos, dan tidak meninggalkan catatan.","Jika disuruh bisa mencatat, tetapi pemahaman peraturannya dangkal dan catatannya banyak yang terlewat.","Jika ada instruksi, bisa menyerahkan ke pemrosesan khusus dan mencatat keadaan kematian secara garis besar.","Tanpa instruksi pun, memproses sesuai peraturan, tidak memutuskan sendiri jika dicurigai penyakit menular, dan mencatat tanggal kematian, jumlah ekor, dan penyebabnya.","Memahami poin-poin undang-undang pengolahan bangkai dan pengelolaan limbah (peraturan Jepang), dan bisa mengajari karyawan baru pemrosesan dan pencatatan yang benar."]}],"gyomu":"37","name_en":"Dead pig collection","purposeShort_en":"Prevent pathogen spread, odor, and pest damage, and comply with the law","name_vi":"Thu gom lợn chết","purposeShort_vi":"Ngăn mầm bệnh lan rộng, mùi hôi và thú hại, tuân thủ pháp luật","name_id":"Pengumpulan babi mati","purposeShort_id":"Mencegah penyebaran bibit penyakit, bau busuk, dan kerusakan oleh hewan liar, serta mematuhi peraturan"},{"id":"ai-insem","category":"breeding","no":"No.14","name":"AI（人工授精）注入作業","purposeShort":"受胎数・産子数を高く保ち、精液を無駄なく計画的に使う","aspects":[{"id":"acceptance","name":"許容確認と挿入の判断","kanten":"許容を確認してから無理なく挿入し、排卵タイミングに合った適期に注入できるか。","levels":["許容を確かめず無理に挿入し、排卵タイミングを無視して受胎率を落とす。","指示があれば実施するが、許容確認が不十分で適期を外すことが多い。","指示があれば許容を確認し、指示された適期にひと通り注入できる。","指示がなくても許容を確かめてから適期に注入し、無理な挿入を避ける。","許容開始からの排卵時間を理解し、適期の判断と丁寧な注入を新人に指導できる。"],"name_en":"Confirming standing heat and judging insertion","kanten_en":"Can they confirm standing heat before inserting gently, and inseminate at the right time matched to ovulation?","levels_en":["Inserts forcibly without confirming standing heat and ignores ovulation timing, lowering the conception rate.","With guidance, performs the procedure, but standing heat checks are insufficient and the optimal window is often missed.","With guidance, confirms standing heat and can adequately inseminate at the instructed timing.","Independently confirms standing heat before inseminating at the right time, avoiding forced insertion.","Understands the time from onset of standing heat to ovulation, and can teach new staff timing judgment and careful insemination."],"name_vi":"Kiểm tra phản xạ đứng yên và phán đoán đưa ống vào","kanten_vi":"Có kiểm tra phản xạ đứng yên rồi mới đưa ống vào nhẹ nhàng, bơm tinh đúng thời kỳ phù hợp với thời điểm rụng trứng không.","levels_vi":["Không kiểm tra phản xạ đứng yên mà đưa ống vào cưỡng ép, bỏ qua thời điểm rụng trứng làm giảm tỷ lệ thụ thai.","Nếu có chỉ dẫn thì làm được, nhưng kiểm tra phản xạ đứng yên chưa đủ, thường lỡ thời kỳ thích hợp.","Nếu có chỉ dẫn thì kiểm tra phản xạ đứng yên, bơm tinh được cơ bản vào thời kỳ được chỉ định.","Không cần chỉ dẫn cũng kiểm tra phản xạ đứng yên rồi bơm tinh đúng thời kỳ, tránh đưa ống vào cưỡng ép.","Hiểu thời gian rụng trứng tính từ khi bắt đầu chịu đực, và có thể hướng dẫn người mới cách phán đoán thời kỳ và bơm tinh nhẹ nhàng."],"name_id":"Pemeriksaan refleks diam dan keputusan memasukkan kateter","kanten_id":"Apakah memeriksa refleks diam dulu baru memasukkan kateter tanpa paksaan, dan bisa memasukkan semen pada waktu yang tepat sesuai saat ovulasi.","levels_id":["Memasukkan kateter dengan paksa tanpa memeriksa refleks diam, mengabaikan saat ovulasi sehingga menurunkan angka kebuntingan.","Jika ada instruksi bisa melaksanakan, tetapi pemeriksaan refleks diam kurang sehingga sering meleset dari waktu yang tepat.","Jika ada instruksi, bisa memeriksa refleks diam dan memasukkan semen secara garis besar pada waktu yang diinstruksikan.","Tanpa instruksi pun, memeriksa refleks diam dulu baru memasukkan semen pada waktu yang tepat, dan menghindari pemasukan kateter secara paksa.","Memahami waktu ovulasi dihitung dari mulainya refleks diam, dan bisa mengajari karyawan baru cara menilai waktu yang tepat dan memasukkan semen dengan hati-hati."]},{"id":"hygiene-temp","name":"器具・外陰部の清潔と精液の温度管理","kanten":"器具・外陰部を清潔に保ち、精液をゆっくり入れ、急激な加温を避けて温度管理できるか。","levels":["器具・外陰部を清潔にせず、精液を急激に加温してカテーテル汚染や高温障害を招く。","指示があれば清潔にするが、温度管理や注入速度に漏れがある。","指示があれば器具・外陰部を清潔に保ち、精液をひと通りゆっくり入れられる。","指示がなくても清潔を徹底し、精液を急激に加温せずゆっくり注入する。","子宮炎・高温障害の仕組みを理解し、清潔操作と温度管理を新人に指導できる。"],"name_en":"Cleanliness of equipment and vulva, and semen temperature control","kanten_en":"Can they keep the equipment and vulva clean, introduce semen slowly, and control temperature while avoiding rapid warming?","levels_en":["Does not clean the equipment or vulva and warms semen rapidly, causing catheter contamination and heat damage.","With guidance, keeps things clean, but is inconsistent about temperature control and insemination speed.","With guidance, keeps the equipment and vulva clean and can adequately introduce the semen slowly.","Independently maintains strict cleanliness and inseminates slowly without rapidly warming the semen.","Understands the mechanisms of metritis and heat damage, and can teach new staff clean technique and temperature control."],"name_vi":"Giữ sạch dụng cụ, bộ phận sinh dục ngoài và quản lý nhiệt độ tinh dịch","kanten_vi":"Có giữ sạch dụng cụ và bộ phận sinh dục ngoài, bơm tinh chậm rãi, tránh làm ấm đột ngột và quản lý được nhiệt độ không.","levels_vi":["Không làm sạch dụng cụ và bộ phận sinh dục ngoài, làm ấm tinh dịch đột ngột, gây bẩn ống thông và hỏng do nhiệt độ cao.","Nếu có chỉ dẫn thì làm sạch, nhưng có bỏ sót việc quản lý nhiệt độ và tốc độ bơm.","Nếu có chỉ dẫn thì giữ sạch dụng cụ và bộ phận sinh dục ngoài, bơm tinh được cơ bản một cách chậm rãi.","Không cần chỉ dẫn cũng giữ sạch kỹ, không làm ấm tinh dịch đột ngột mà bơm chậm rãi.","Hiểu cơ chế viêm tử cung và hỏng do nhiệt độ cao, và có thể hướng dẫn người mới thao tác sạch và quản lý nhiệt độ."],"name_id":"Kebersihan alat dan vulva serta pengelolaan suhu semen","kanten_id":"Apakah menjaga alat dan vulva tetap bersih, memasukkan semen perlahan, dan mengelola suhu dengan menghindari pemanasan mendadak.","levels_id":["Tidak membersihkan alat dan vulva, memanaskan semen secara mendadak sehingga menyebabkan kontaminasi kateter dan kerusakan karena suhu tinggi.","Jika ada instruksi bisa menjaga kebersihan, tetapi sering lalai mengelola suhu dan kecepatan memasukkan semen.","Jika ada instruksi, bisa menjaga alat dan vulva tetap bersih, dan memasukkan semen secara garis besar dengan perlahan.","Tanpa instruksi pun, menjaga kebersihan dengan ketat, dan memasukkan semen perlahan tanpa memanaskannya mendadak.","Memahami mekanisme radang rahim dan kerusakan karena suhu tinggi, dan bisa mengajari karyawan baru kerja bersih dan pengelolaan suhu."]}],"gyomu":"14","name_en":"AI (artificial insemination)","purposeShort_en":"Keep conception and litter size high, and use semen efficiently and according to plan","name_vi":"Công việc bơm tinh AI (thụ tinh nhân tạo)","purposeShort_vi":"Giữ số con thụ thai và số con đẻ ra ở mức cao, dùng tinh dịch có kế hoạch, không lãng phí","name_id":"Pekerjaan inseminasi AI (inseminasi buatan)","purposeShort_id":"Menjaga angka kebuntingan dan jumlah anak tetap tinggi, dan memakai semen secara terencana tanpa pemborosan"},{"id":"standing-check","category":"breeding","no":"No.33","name":"許容確認","purposeShort":"交配に入れる最適なタイミングを見極め、受胎率と産子数を上げる","aspects":[{"id":"boar-backpressure","name":"雄豚接触＋背圧での確認","kanten":"雄豚を接触させ、背圧をかけて強く押しても動かず立つかを確かめられるか。","levels":["雄豚を近づけず外陰部の腫れだけで判断し、偽陰性・適期外授精を招く。","指示があれば背圧を確かめるが、雄豚接触が不十分で判断が甘い。","指示があれば雄豚接触＋背圧で許容をひと通り確認できる。","指示がなくても雄豚を接触させて背圧をかけ、静止するかを確実に確かめる。","許容反応の仕組みを理解し、確実な確認方法と適期の見極めを新人に指導できる。"],"name_en":"Checking with boar contact plus back pressure","kanten_en":"Can they bring a boar into contact and apply back pressure to verify that the sow stands firm even when pushed hard?","levels_en":["Judges only by vulvar swelling without bringing a boar close, causing false negatives and mistimed insemination.","With guidance, checks back pressure, but boar contact is insufficient and judgment is unreliable.","With guidance, can adequately confirm standing heat with boar contact plus back pressure.","Independently brings the boar into contact, applies back pressure, and reliably verifies that the sow stands still.","Understands the mechanism of the standing reflex, and can teach new staff reliable checking methods and how to judge the optimal timing."],"name_vi":"Kiểm tra bằng tiếp xúc lợn đực và ấn lưng","kanten_vi":"Có cho tiếp xúc lợn đực, ấn lưng mạnh để kiểm tra lợn có đứng yên không nhúc nhích không.","levels_vi":["Không cho lợn đực lại gần, chỉ phán đoán bằng độ sưng của bộ phận sinh dục ngoài, gây âm tính giả và phối sai thời kỳ.","Nếu có chỉ dẫn thì kiểm tra bằng ấn lưng, nhưng việc tiếp xúc lợn đực chưa đủ nên phán đoán còn non.","Nếu có chỉ dẫn thì kiểm tra được cơ bản phản xạ đứng yên bằng tiếp xúc lợn đực và ấn lưng.","Không cần chỉ dẫn cũng cho tiếp xúc lợn đực và ấn lưng, kiểm tra chắc chắn lợn có đứng yên không.","Hiểu cơ chế của phản xạ đứng yên, và có thể hướng dẫn người mới cách kiểm tra chắc chắn và nhìn ra thời kỳ thích hợp."],"name_id":"Pemeriksaan dengan kontak babi jantan + tekanan punggung","kanten_id":"Apakah bisa mendekatkan babi jantan, memberi tekanan pada punggung, dan memastikan babi tetap berdiri diam walau ditekan kuat.","levels_id":["Tidak mendekatkan babi jantan dan hanya menilai dari bengkaknya vulva, sehingga terjadi negatif palsu dan inseminasi di luar waktu yang tepat.","Jika ada instruksi bisa memeriksa tekanan punggung, tetapi kontak dengan babi jantan kurang sehingga penilaiannya lemah.","Jika ada instruksi, bisa memeriksa refleks diam secara garis besar dengan kontak babi jantan + tekanan punggung.","Tanpa instruksi pun, mendekatkan babi jantan, memberi tekanan punggung, dan memastikan dengan pasti apakah babi berdiri diam.","Memahami mekanisme refleks diam saat birahi, dan bisa mengajari karyawan baru cara pemeriksaan yang pasti dan penentuan waktu yang tepat."]},{"id":"quiet-timing","name":"静かな母豚・夜間発情の見落とし防止","kanten":"静かな母豚は外見・行動も合わせて見て、夜間・早朝発情を見落とさず確認できるか。","levels":["1日1回の確認だけで、夜間・早朝発情や静かな母豚の発情を見落とす。","指示があれば確認するが、静かな母豚や時間帯による見落としが多い。","指示があれば静かな母豚も外見・行動を合わせてひと通り確認できる。","指示がなくても確認回数を工夫し、静かな母豚も排尿等の行動から発情を捉える。","夜間発情や微弱発情の見落としリスクを理解し、確認のタイミングを新人に指導できる。"],"name_en":"Avoiding missed quiet sows and night-time heats","kanten_en":"Can they assess quiet sows by appearance and behavior as well, and check without missing night-time or early-morning heats?","levels_en":["Checks only once a day and misses night or early-morning heats and the heats of quiet sows.","With guidance, checks, but often misses quiet sows and heats at certain times of day.","With guidance, can adequately check quiet sows using appearance and behavior together.","Independently varies the number and timing of checks, and detects heat in quiet sows from behaviors such as urination.","Understands the risk of missing night-time and weak heats, and can teach new staff the timing of checks."],"name_vi":"Phòng bỏ sót lợn nái động dục thầm lặng và động dục ban đêm","kanten_vi":"Với lợn nái động dục thầm lặng có nhìn thêm cả bề ngoài và hành vi, không bỏ sót động dục ban đêm và sáng sớm không.","levels_vi":["Chỉ kiểm tra 1 lần mỗi ngày, bỏ sót động dục ban đêm, sáng sớm và động dục của lợn nái thầm lặng.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót lợn nái thầm lặng và tùy theo giờ giấc.","Nếu có chỉ dẫn thì kiểm tra được cơ bản cả lợn nái thầm lặng bằng cách nhìn thêm bề ngoài và hành vi.","Không cần chỉ dẫn cũng thay đổi số lần kiểm tra, nhận ra động dục của lợn nái thầm lặng qua hành vi như đi tiểu.","Hiểu nguy cơ bỏ sót động dục ban đêm và động dục yếu, và có thể hướng dẫn người mới thời điểm kiểm tra."],"name_id":"Mencegah terlewatnya induk pendiam dan birahi malam hari","kanten_id":"Apakah induk babi yang pendiam diperiksa juga dari penampilan dan perilakunya, dan birahi malam serta pagi buta tidak terlewat.","levels_id":["Hanya memeriksa sekali sehari, sehingga melewatkan birahi malam dan pagi buta serta birahi induk babi yang pendiam.","Jika ada instruksi bisa memeriksa, tetapi sering melewatkan induk yang pendiam atau karena jam pemeriksaan.","Jika ada instruksi, bisa memeriksa induk yang pendiam juga secara garis besar dengan melihat penampilan dan perilakunya.","Tanpa instruksi pun, mengatur frekuensi pemeriksaan, dan menangkap birahi induk yang pendiam dari perilaku seperti buang air kecil.","Memahami risiko terlewatnya birahi malam hari dan birahi yang lemah, dan bisa mengajari karyawan baru waktu-waktu pemeriksaan."]}],"gyomu":"33","name_en":"Standing heat check","purposeShort_en":"Identify the optimal timing for breeding and raise conception rate and litter size","name_vi":"Kiểm tra phản xạ đứng yên khi động dục","purposeShort_vi":"Nhìn ra thời điểm tốt nhất để phối giống, nâng tỷ lệ thụ thai và số con đẻ ra","name_id":"Pemeriksaan refleks diam saat birahi","purposeShort_id":"Menentukan waktu terbaik untuk perkawinan, menaikkan angka kebuntingan dan jumlah anak"},{"id":"semen-check","category":"breeding","no":"No.03","name":"精液検査・反転","purposeShort":"問題のある精液を使用前に除外し、繁殖成績の低下を防ぐ","aspects":[{"id":"temp-control","name":"17℃保管と温度変化の抑制","kanten":"精液を17℃前後で保管し、検査前の温度を均一にして温度変化を最小限にできるか。","levels":["保管温度を気にせず、検査前の温度も不均一なまま評価して誤判定する。","指示があれば温度を確認するが、変化の抑制や均一化に漏れがある。","指示があれば17℃前後で保管し、ひと通り温度に配慮できる。","指示がなくても温度変化を最小限に抑え、検査前に温度を均一にする。","温度が精子品質に与える影響を理解し、保管・検査時の温度管理を新人に指導できる。"],"name_en":"Storage at 17°C and minimizing temperature changes","kanten_en":"Can they store semen at around 17°C and equalize its temperature before testing, keeping temperature changes to a minimum?","levels_en":["Pays no attention to storage temperature and evaluates semen at uneven temperatures, causing misjudgment.","With guidance, checks the temperature, but is inconsistent about limiting changes and equalizing it.","With guidance, stores semen at around 17°C and can pay adequate attention to temperature.","Independently keeps temperature changes to a minimum and equalizes the temperature before testing.","Understands how temperature affects sperm quality, and can teach new staff temperature control during storage and testing."],"name_vi":"Bảo quản 17℃ và hạn chế thay đổi nhiệt độ","kanten_vi":"Có bảo quản tinh dịch quanh 17℃, làm đều nhiệt độ trước khi kiểm tra và giữ thay đổi nhiệt độ ở mức nhỏ nhất không.","levels_vi":["Không quan tâm nhiệt độ bảo quản, đánh giá khi nhiệt độ trước kiểm tra chưa đều nên phán đoán sai.","Nếu có chỉ dẫn thì kiểm tra nhiệt độ, nhưng có bỏ sót việc hạn chế thay đổi và làm đều nhiệt độ.","Nếu có chỉ dẫn thì bảo quản quanh 17℃, chú ý được cơ bản đến nhiệt độ.","Không cần chỉ dẫn cũng giữ thay đổi nhiệt độ ở mức nhỏ nhất, làm đều nhiệt độ trước khi kiểm tra.","Hiểu nhiệt độ ảnh hưởng đến chất lượng tinh trùng, và có thể hướng dẫn người mới cách quản lý nhiệt độ khi bảo quản và kiểm tra."],"name_id":"Penyimpanan 17°C dan menekan perubahan suhu","kanten_id":"Apakah menyimpan semen sekitar 17°C, menyeragamkan suhu sebelum pemeriksaan, dan menekan perubahan suhu seminimal mungkin.","levels_id":["Tidak peduli suhu penyimpanan, mengevaluasi dengan suhu sebelum pemeriksaan yang tidak seragam sehingga salah menilai.","Jika ada instruksi bisa memeriksa suhu, tetapi sering lalai menekan perubahan dan menyeragamkan suhu.","Jika ada instruksi, bisa menyimpan sekitar 17°C dan cukup memperhatikan suhu.","Tanpa instruksi pun, menekan perubahan suhu seminimal mungkin, dan menyeragamkan suhu sebelum pemeriksaan.","Memahami pengaruh suhu terhadap kualitas sperma, dan bisa mengajari karyawan baru pengelolaan suhu saat penyimpanan dan pemeriksaan."]},{"id":"activity-mix","name":"精子活力確認と穏やかな反転","kanten":"顕微鏡で精子活力を確認し、反転を穏やかに行って精子へのダメージを防げるか。","levels":["活力確認を省き、新鮮精液を激しく振盪して精子を傷める。","指示があれば確認するが、反転の強さやタイミングに漏れがある。","指示があれば顕微鏡で活力を確認し、ひと通り穏やかに反転できる。","指示がなくても活力を確認し、反転を穏やかに行ってダメージを防ぐ。","精子活力と反転操作の関係を理解し、検査と反転の手技を新人に指導できる。"],"name_en":"Checking sperm motility and gentle inversion","kanten_en":"Can they check sperm motility under a microscope and invert the container gently to prevent sperm damage?","levels_en":["Skips the motility check and shakes fresh semen violently, damaging the sperm.","With guidance, checks motility, but is inconsistent about the force and timing of inversion.","With guidance, checks motility under the microscope and can adequately invert the container gently.","Independently checks motility and inverts gently to prevent damage.","Understands the relationship between sperm motility and the inversion procedure, and can teach new staff the testing and inversion techniques."],"name_vi":"Kiểm tra hoạt lực tinh trùng và đảo chai nhẹ nhàng","kanten_vi":"Có kiểm tra hoạt lực tinh trùng bằng kính hiển vi, đảo chai nhẹ nhàng để tránh làm tổn thương tinh trùng không.","levels_vi":["Bỏ qua kiểm tra hoạt lực, lắc mạnh tinh dịch tươi làm tổn thương tinh trùng.","Nếu có chỉ dẫn thì kiểm tra, nhưng có bỏ sót về độ mạnh và thời điểm đảo chai.","Nếu có chỉ dẫn thì kiểm tra hoạt lực bằng kính hiển vi, đảo chai được cơ bản một cách nhẹ nhàng.","Không cần chỉ dẫn cũng kiểm tra hoạt lực, đảo chai nhẹ nhàng để tránh tổn thương.","Hiểu quan hệ giữa hoạt lực tinh trùng và thao tác đảo chai, và có thể hướng dẫn người mới kỹ thuật kiểm tra và đảo chai."],"name_id":"Pemeriksaan motilitas sperma dan membalik botol dengan lembut","kanten_id":"Apakah memeriksa motilitas (gerak) sperma dengan mikroskop, dan membalik botol dengan lembut untuk mencegah kerusakan sperma.","levels_id":["Melewatkan pemeriksaan motilitas, dan mengguncang semen segar dengan keras sehingga merusak sperma.","Jika ada instruksi bisa memeriksa, tetapi sering lalai soal kekuatan dan waktu membalik botol.","Jika ada instruksi, bisa memeriksa motilitas dengan mikroskop dan membalik botol secara garis besar dengan lembut.","Tanpa instruksi pun, memeriksa motilitas dan membalik botol dengan lembut sehingga mencegah kerusakan.","Memahami hubungan motilitas sperma dengan cara membalik botol, dan bisa mengajari karyawan baru teknik pemeriksaan dan pembalikan."]}],"gyomu":"03","name_en":"Semen check and inversion","purposeShort_en":"Exclude problem semen before use and prevent declines in reproductive performance","name_vi":"Kiểm tra tinh dịch và đảo chai tinh","purposeShort_vi":"Loại bỏ tinh dịch có vấn đề trước khi dùng, ngăn thành tích sinh sản giảm sút","name_id":"Pemeriksaan semen dan membalik botol semen","purposeShort_id":"Menyingkirkan semen yang bermasalah sebelum dipakai, mencegah turunnya hasil reproduksi"},{"id":"semen-mix","category":"breeding","no":"No.17","name":"精液攪拌","purposeShort":"精子濃度を均一化する","aspects":[{"id":"gentle-mix","name":"穏やかな攪拌と温度・浸透圧の配慮","kanten":"強く振らず穏やかに攪拌し、希釈液との温度差や気泡混入を避けられるか。","levels":["強く振って気泡を混入させ、希釈液との温度差で浸透圧ショックを招く。","指示があれば攪拌するが、強さや温度差への配慮に漏れがある。","指示があれば穏やかにひと通り攪拌できる。","指示がなくても温度差を抑えて穏やかに攪拌し、気泡混入を避ける。","浸透圧ショックや酸化ストレスの仕組みを理解し、攪拌のコツを新人に指導できる。"],"name_en":"Gentle mixing with attention to temperature and osmotic pressure","kanten_en":"Can they mix gently without shaking hard, avoiding temperature differences with the extender and air bubble entrainment?","levels_en":["Shakes hard, entraining air bubbles, and causes osmotic shock through temperature differences with the extender.","With guidance, mixes, but is inconsistent about force and attention to temperature differences.","With guidance, can adequately mix gently.","Independently limits temperature differences, mixes gently, and avoids entraining air bubbles.","Understands the mechanisms of osmotic shock and oxidative stress, and can teach new staff the knack of mixing."],"name_vi":"Lắc nhẹ nhàng và chú ý nhiệt độ, áp suất thẩm thấu","kanten_vi":"Có lắc nhẹ nhàng, không lắc mạnh, tránh chênh lệch nhiệt độ với dung dịch pha loãng và tránh lẫn bọt khí không.","levels_vi":["Lắc mạnh làm lẫn bọt khí, chênh lệch nhiệt độ với dung dịch pha loãng gây sốc thẩm thấu.","Nếu có chỉ dẫn thì lắc, nhưng có bỏ sót về độ mạnh và chú ý đến chênh lệch nhiệt độ.","Nếu có chỉ dẫn thì lắc được cơ bản một cách nhẹ nhàng.","Không cần chỉ dẫn cũng giữ chênh lệch nhiệt độ nhỏ, lắc nhẹ nhàng và tránh lẫn bọt khí.","Hiểu cơ chế sốc thẩm thấu và stress oxy hóa, và có thể hướng dẫn người mới mẹo lắc đều."],"name_id":"Pengadukan lembut dan perhatian pada suhu serta tekanan osmotik","kanten_id":"Apakah mengaduk dengan lembut tanpa mengocok keras, dan menghindari perbedaan suhu dengan cairan pengencer serta masuknya gelembung udara.","levels_id":["Mengocok keras sehingga gelembung udara masuk, dan perbedaan suhu dengan cairan pengencer menyebabkan syok tekanan osmotik.","Jika ada instruksi bisa mengaduk, tetapi sering lalai memperhatikan kekuatan dan perbedaan suhu.","Jika ada instruksi, bisa mengaduk secara garis besar dengan lembut.","Tanpa instruksi pun, menekan perbedaan suhu, mengaduk dengan lembut, dan menghindari masuknya gelembung udara.","Memahami mekanisme syok tekanan osmotik dan stres oksidatif, dan bisa mengajari karyawan baru trik pengadukan."]},{"id":"light-shield","name":"遮光の徹底","kanten":"遮光を守り、紫外線・光線による精子ダメージを防げるか。","levels":["遮光を怠り、光にさらして精子を傷める。","指示があれば遮光するが、徹底に漏れがある。","指示があればひと通り遮光して扱える。","指示がなくても遮光を徹底し、光線ダメージを防ぐ。","光が精子に与える影響を理解し、遮光管理を新人に指導できる。"],"name_en":"Thorough light shielding","kanten_en":"Can they maintain light shielding and prevent sperm damage from ultraviolet and visible light?","levels_en":["Neglects light shielding and exposes semen to light, damaging the sperm.","With guidance, shields from light, but not thoroughly.","With guidance, can adequately handle semen under light shielding.","Independently maintains thorough light shielding and prevents light damage.","Understands how light affects sperm, and can teach new staff light-shielding management."],"name_vi":"Che sáng kỹ càng","kanten_vi":"Có giữ việc che sáng, phòng tổn thương tinh trùng do tia cực tím và ánh sáng không.","levels_vi":["Không che sáng, để tinh dịch phơi ra ánh sáng làm tổn thương tinh trùng.","Nếu có chỉ dẫn thì che sáng, nhưng chưa làm triệt để.","Nếu có chỉ dẫn thì che sáng và xử lý được cơ bản.","Không cần chỉ dẫn cũng che sáng kỹ càng, phòng tổn thương do ánh sáng.","Hiểu ánh sáng ảnh hưởng đến tinh trùng, và có thể hướng dẫn người mới cách quản lý che sáng."],"name_id":"Menjalankan pelindungan dari cahaya","kanten_id":"Apakah mematuhi pelindungan dari cahaya, dan mencegah kerusakan sperma karena sinar ultraviolet dan cahaya.","levels_id":["Lalai melindungi dari cahaya, membiarkan semen terkena cahaya sehingga sperma rusak.","Jika ada instruksi bisa melindungi dari cahaya, tetapi pelaksanaannya sering lalai.","Jika ada instruksi, bisa menangani semen secara garis besar dengan terlindung dari cahaya.","Tanpa instruksi pun, menjalankan pelindungan dari cahaya dengan ketat, dan mencegah kerusakan karena cahaya.","Memahami pengaruh cahaya terhadap sperma, dan bisa mengajari karyawan baru pengelolaan pelindungan dari cahaya."]}],"gyomu":"17","name_en":"Semen mixing","purposeShort_en":"Even out the sperm concentration","name_vi":"Lắc đều tinh dịch (lắc nhẹ)","purposeShort_vi":"Làm đều nồng độ tinh trùng","name_id":"Mengaduk semen (kocok pelan)","purposeShort_id":"Menyeragamkan konsentrasi sperma"},{"id":"preg-check","category":"breeding","no":"No.09","name":"妊娠鑑定","purposeShort":"分娩・離乳頭数を計画通り確保し、空胎母豚を早く見つけて対応する","aspects":[{"id":"timing-recheck","name":"鑑定時期の厳守と再確認","kanten":"交配後24〜28日に鑑定し、1回で判断せず35〜40日で必ず再確認できるか。","levels":["1回の確認だけで妊娠を確定し、21日目などの偽陽性を見落とす。","指示があれば鑑定するが、時期の厳守や再確認に漏れが多い。","指示があれば決められた時期に鑑定し、ひと通り実施できる。","指示がなくても24〜28日に鑑定し、35〜40日で必ず再確認する。","偽陽性・偽陰性の時期特性を理解し、鑑定時期と再確認の重要性を新人に指導できる。"],"name_en":"Strict Timing and Recheck","kanten_en":"Can they check at 24-28 days after mating, and always recheck at 35-40 days instead of deciding from a single check?","levels_en":["Confirms pregnancy from a single check and misses false positives such as those around day 21.","With guidance can perform checks, but often misses the required timing or the recheck.","With guidance can check at the designated timing and complete the basic procedure.","Independently checks at 24-28 days and always rechecks at 35-40 days.","Understands the timing characteristics of false positives and negatives, and can teach new staff the importance of check timing and rechecking."],"name_vi":"Tuân thủ thời điểm chẩn đoán và kiểm tra lại","kanten_vi":"Có chẩn đoán vào ngày 24-28 sau giao phối, không kết luận chỉ sau 1 lần mà luôn kiểm tra lại vào ngày 35-40 không.","levels_vi":["Chỉ kiểm tra 1 lần đã kết luận là mang thai, bỏ sót dương tính giả như ở ngày 21.","Nếu được chỉ thị thì chẩn đoán, nhưng hay thiếu sót về tuân thủ thời điểm và kiểm tra lại.","Nếu được chỉ thị thì chẩn đoán đúng thời điểm quy định và thực hiện được cơ bản.","Dù không có chỉ thị vẫn chẩn đoán vào ngày 24-28 và luôn kiểm tra lại vào ngày 35-40.","Hiểu đặc điểm thời điểm của dương tính giả, âm tính giả, và có thể hướng dẫn người mới về tầm quan trọng của thời điểm chẩn đoán và kiểm tra lại."],"name_id":"Menepati waktu pemeriksaan dan pemeriksaan ulang","kanten_id":"Apakah dapat memeriksa pada hari ke-24-28 setelah perkawinan, tidak memutuskan hanya dengan satu kali pemeriksaan, dan selalu memeriksa ulang pada hari ke-35-40?","levels_id":["Memastikan kebuntingan hanya dengan satu kali pemeriksaan, sehingga melewatkan hasil positif palsu seperti pada hari ke-21.","Memeriksa jika diperintah, tetapi sering lalai menepati waktu dan melakukan pemeriksaan ulang.","Jika diperintah, dapat memeriksa pada waktu yang ditentukan dan melakukannya secara lengkap.","Tanpa diperintah pun, memeriksa pada hari ke-24-28 dan selalu memeriksa ulang pada hari ke-35-40.","Memahami kapan hasil positif palsu dan negatif palsu bisa terjadi, dan dapat mengajarkan pentingnya waktu pemeriksaan dan pemeriksaan ulang kepada karyawan baru."]},{"id":"echo-reading","name":"エコー画像の正しい読み取り","kanten":"膀胱・腸内容物と胎胞を混同せず、エコー画像を正しく読み取れるか。","levels":["膀胱や腸内容物を妊娠と誤読し、判定を誤る。","指示があれば当てるが、画像の読み取りに誤りが多い。","指示があればひと通りエコーを当てて胎胞を確認できる。","指示がなくても膀胱・腸内容物と胎胞を見分けて正しく判定する。","エコー画像の見分け方を理解し、誤読を避ける読み取りを新人に指導できる。"],"name_en":"Correct Reading of Ultrasound Images","kanten_en":"Can they read ultrasound images correctly without confusing the bladder or intestinal contents with gestational sacs?","levels_en":["Misreads the bladder or intestinal contents as pregnancy and makes wrong judgments.","With guidance can apply the probe, but makes frequent errors in reading the images.","With guidance can apply the ultrasound probe and confirm gestational sacs through the basic procedure.","Independently distinguishes the bladder and intestinal contents from gestational sacs and judges correctly.","Understands how to distinguish ultrasound images and can teach new staff how to read them without misinterpretation."],"name_vi":"Đọc đúng hình ảnh siêu âm","kanten_vi":"Có đọc đúng hình ảnh siêu âm, không nhầm bàng quang hoặc chất chứa trong ruột với túi thai không.","levels_vi":["Đọc nhầm bàng quang hoặc chất chứa trong ruột thành mang thai, dẫn đến kết luận sai.","Nếu được chỉ thị thì áp đầu dò siêu âm, nhưng hay đọc sai hình ảnh.","Nếu được chỉ thị thì có thể siêu âm và xác nhận túi thai một cách cơ bản.","Dù không có chỉ thị vẫn phân biệt được bàng quang, chất chứa trong ruột với túi thai và kết luận đúng.","Hiểu cách phân biệt hình ảnh siêu âm, và có thể hướng dẫn người mới cách đọc để tránh đọc sai."],"name_id":"Membaca gambar USG dengan benar","kanten_id":"Apakah dapat membaca gambar USG dengan benar, tanpa mengira kandung kemih atau isi usus sebagai kantung janin?","levels_id":["Salah membaca kandung kemih atau isi usus sebagai kebuntingan, sehingga hasil penilaian keliru.","Menempelkan alat USG jika diperintah, tetapi sering salah membaca gambar.","Jika diperintah, dapat menempelkan alat USG dan memeriksa kantung janin secara lengkap.","Tanpa diperintah pun, dapat membedakan kandung kemih dan isi usus dari kantung janin, lalu menilai dengan benar.","Memahami cara membedakan gambar USG dan dapat mengajarkan cara membaca yang menghindari salah baca kepada karyawan baru."]},{"id":"recheck-return","name":"鑑定後の再発情チェック","kanten":"鑑定後も再発情チェックを続け、空胎の長期化を防げるか。","levels":["鑑定後の再発情チェックを中断し、空胎を長期化させる。","指示があれば確認するが、継続に漏れが多い。","指示があれば鑑定後の再発情をひと通り確認できる。","指示がなくても再発情チェックを続け、空胎の母豚を早く見つける。","再発情チェックの意義を理解し、空胎長期化を防ぐ管理を新人に指導できる。"],"name_en":"Return-to-Estrus Checks After Diagnosis","kanten_en":"Can they continue return-to-estrus checks after diagnosis and prevent prolonged open days?","levels_en":["Stops return-to-estrus checks after diagnosis and lets open days drag on.","With guidance can check, but often fails to keep it up.","With guidance can carry out the basic return-to-estrus checks after diagnosis.","Independently continues return-to-estrus checks and finds open sows early.","Understands the purpose of return-to-estrus checks and can teach new staff how to prevent prolonged open days."],"name_vi":"Kiểm tra động dục trở lại sau chẩn đoán","kanten_vi":"Sau khi chẩn đoán có tiếp tục kiểm tra động dục trở lại, tránh để tình trạng không mang thai kéo dài không.","levels_vi":["Ngừng kiểm tra động dục trở lại sau chẩn đoán, để tình trạng không mang thai kéo dài.","Nếu được chỉ thị thì kiểm tra, nhưng hay không duy trì liên tục.","Nếu được chỉ thị thì có thể kiểm tra động dục trở lại sau chẩn đoán một cách cơ bản.","Dù không có chỉ thị vẫn tiếp tục kiểm tra động dục trở lại, phát hiện sớm lợn nái không mang thai.","Hiểu ý nghĩa của việc kiểm tra động dục trở lại, và có thể hướng dẫn người mới cách quản lý để tránh tình trạng không mang thai kéo dài."],"name_id":"Memeriksa birahi kembali setelah diagnosa","kanten_id":"Apakah tetap memeriksa birahi kembali setelah diagnosa, sehingga masa tidak bunting tidak berkepanjangan?","levels_id":["Berhenti memeriksa birahi kembali setelah diagnosa, sehingga masa tidak bunting menjadi berkepanjangan.","Memeriksa jika diperintah, tetapi sering tidak melanjutkannya.","Jika diperintah, dapat memeriksa birahi kembali setelah diagnosa secara lengkap.","Tanpa diperintah pun, terus memeriksa birahi kembali dan cepat menemukan induk babi yang tidak bunting.","Memahami pentingnya pemeriksaan birahi kembali dan dapat mengajarkan cara mencegah masa tidak bunting berkepanjangan kepada karyawan baru."]}],"gyomu":"09","name_en":"Pregnancy Check","purposeShort_en":"Secure planned farrowing and weaning numbers, and find open sows early to take action","name_vi":"Chẩn đoán mang thai","purposeShort_vi":"Đảm bảo số con đẻ ra và số con cai sữa theo kế hoạch, phát hiện sớm lợn nái không mang thai để xử lý","name_id":"Diagnosa kebuntingan","purposeShort_id":"Memastikan jumlah kelahiran dan penyapihan sesuai rencana, serta cepat menemukan induk babi yang tidak bunting untuk ditangani"},{"id":"pms","category":"breeding","no":"No.08","name":"PMS投与","purposeShort":"発情が弱い・来ない母豚に発情を誘起し、タイミングをそろえる","aspects":[{"id":"timing-judge","name":"投与時期と黄体確認","kanten":"基本は離乳当日〜翌日に投与し、黄体遺残をエコー確認して重複投与を避けられるか。","levels":["黄体遺残を確認せず重複投与し、投与時期も守らない。","指示があれば投与するが、時期や黄体確認に漏れがある。","指示があれば決められた時期に用量を守ってひと通り投与できる。","指示がなくても離乳当日〜翌日に投与し、黄体遺残を確認して重複を避ける。","黄体とホルモン誘起の関係を理解し、投与時期と適応の判断を新人に指導できる。"],"name_en":"Administration Timing and Corpus Luteum Check","kanten_en":"Can they administer on the day of weaning or the next day as a rule, and check for retained corpora lutea by ultrasound to avoid duplicate dosing?","levels_en":["Doses repeatedly without checking for retained corpora lutea, and ignores the administration timing.","With guidance can administer, but misses the timing or the corpus luteum check.","With guidance can administer the correct dose at the designated timing through the basic procedure.","Independently administers on the day of weaning or the next day, checking for retained corpora lutea to avoid duplication.","Understands the relationship between corpora lutea and hormonal induction, and can teach new staff how to judge timing and indications."],"name_vi":"Thời điểm tiêm và kiểm tra thể vàng","kanten_vi":"Về cơ bản có tiêm vào ngày cai sữa hoặc ngày hôm sau, siêu âm kiểm tra thể vàng tồn lưu để tránh tiêm trùng lặp không.","levels_vi":["Không kiểm tra thể vàng tồn lưu mà tiêm trùng lặp, cũng không giữ đúng thời điểm tiêm.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về thời điểm và kiểm tra thể vàng.","Nếu được chỉ thị thì tiêm đúng thời điểm, đúng liều lượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn tiêm vào ngày cai sữa hoặc ngày hôm sau, kiểm tra thể vàng tồn lưu để tránh trùng lặp.","Hiểu quan hệ giữa thể vàng và kích thích bằng hormone, và có thể hướng dẫn người mới cách phán đoán thời điểm tiêm và đối tượng phù hợp."],"name_id":"Waktu penyuntikan dan pemeriksaan korpus luteum","kanten_id":"Apakah pada dasarnya menyuntik pada hari sapih sampai hari berikutnya, dan memeriksa sisa korpus luteum (badan kuning) dengan USG untuk menghindari penyuntikan ganda?","levels_id":["Menyuntik ganda tanpa memeriksa sisa korpus luteum, dan tidak menepati waktu penyuntikan.","Menyuntik jika diperintah, tetapi sering lalai soal waktu dan pemeriksaan korpus luteum.","Jika diperintah, dapat menyuntik pada waktu yang ditentukan dengan dosis yang benar secara lengkap.","Tanpa diperintah pun, menyuntik pada hari sapih sampai hari berikutnya, dan memeriksa sisa korpus luteum untuk menghindari penyuntikan ganda.","Memahami hubungan korpus luteum dengan induksi hormon, dan dapat mengajarkan penilaian waktu dan sasaran penyuntikan kepada karyawan baru."]},{"id":"no-self-judge","name":"自己判断の回避と投与後の確認","kanten":"使いすぎず上長・獣医師と相談し、未経産・経産を区別し、投与後の雄豚刺激で許容を確認できるか。","levels":["自己判断で使い、未経産・経産を区別せず、投与後の許容反応も確認しない。","指示があれば投与するが、相談や投与後確認に漏れがある。","指示があれば上長・獣医師と相談してひと通り投与できる。","指示がなくても使いすぎを避けて相談し、投与後は雄豚刺激で許容反応を確認する。","誘起剤の適正使用と個体差を理解し、相談と投与後確認の要点を新人に指導できる。"],"name_en":"Avoiding Self-Judgment and Post-Administration Checks","kanten_en":"Can they avoid overuse by consulting supervisors and the veterinarian, distinguish gilts from parous sows, and confirm standing response with boar stimulation after administration?","levels_en":["Uses the drug on their own judgment, does not distinguish gilts from parous sows, and never confirms the standing response after administration.","With guidance can administer, but misses consultations or post-administration checks.","With guidance can consult supervisors and the veterinarian and administer through the basic procedure.","Independently avoids overuse by consulting others, and confirms the standing response with boar stimulation after administration.","Understands proper use of induction drugs and individual variation, and can teach new staff the key points of consultation and post-administration checks."],"name_vi":"Tránh tự ý quyết định và kiểm tra sau khi tiêm","kanten_vi":"Có tránh lạm dụng, trao đổi với cấp trên và bác sĩ thú y, phân biệt nái chưa đẻ và nái đã đẻ, sau khi tiêm dùng lợn đực kích thích để kiểm tra phản xạ đứng yên không.","levels_vi":["Tự ý sử dụng, không phân biệt nái chưa đẻ và nái đã đẻ, cũng không kiểm tra phản xạ đứng yên sau khi tiêm.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về trao đổi và kiểm tra sau khi tiêm.","Nếu được chỉ thị thì trao đổi với cấp trên, bác sĩ thú y và tiêm được cơ bản.","Dù không có chỉ thị vẫn tránh lạm dụng, có trao đổi, sau khi tiêm dùng lợn đực kích thích để kiểm tra phản xạ đứng yên.","Hiểu cách dùng đúng thuốc kích thích và sự khác biệt giữa từng cá thể, và có thể hướng dẫn người mới các điểm chính về trao đổi và kiểm tra sau khi tiêm."],"name_id":"Tidak memutuskan sendiri dan memeriksa setelah penyuntikan","kanten_id":"Apakah tidak memakai obat berlebihan, berkonsultasi dengan atasan dan dokter hewan, membedakan babi dara dan induk babi beranak, serta memeriksa refleks diam dengan rangsangan babi jantan setelah penyuntikan?","levels_id":["Memakai obat atas keputusan sendiri, tidak membedakan babi dara dan induk babi beranak, dan tidak memeriksa refleks diam setelah penyuntikan.","Menyuntik jika diperintah, tetapi sering lalai berkonsultasi dan memeriksa setelah penyuntikan.","Jika diperintah, dapat menyuntik secara lengkap setelah berkonsultasi dengan atasan dan dokter hewan.","Tanpa diperintah pun, menghindari pemakaian berlebihan, berkonsultasi lebih dulu, dan setelah penyuntikan memeriksa refleks diam dengan rangsangan babi jantan.","Memahami pemakaian obat pemicu birahi yang tepat dan perbedaan tiap individu, dan dapat mengajarkan pokok konsultasi dan pemeriksaan setelah penyuntikan kepada karyawan baru."]}],"gyomu":"08","name_en":"PMS Administration","purposeShort_en":"Induce estrus in sows with weak or absent heat and synchronize timing","name_vi":"Tiêm PMS (hormone kích thích động dục)","purposeShort_vi":"Gây động dục cho lợn nái động dục yếu hoặc không động dục, làm đồng đều thời điểm","name_id":"Penyuntikan PMS (hormon induksi birahi)","purposeShort_id":"Memicu birahi pada induk babi yang birahinya lemah atau tidak muncul, dan menyeragamkan waktunya"},{"id":"echo-check","category":"breeding","no":"No.24","name":"入室準備（エコー検査）","purposeShort":"妊娠している母豚だけを分娩舎に入れ、空胎を早く見つける","aspects":[{"id":"timing-hold","name":"実施時期の遵守と保留判定","kanten":"決められた時期に実施し、判定があいまいな個体は保留・再確認できるか。","levels":["時期を守らず、あいまいな判定でも確定してしまう。","指示があれば実施するが、保留・再確認の判断に漏れがある。","指示があれば決められた時期にひと通り検査できる。","指示がなくても時期を守り、あいまいな個体は保留して再確認する。","誤判定のリスクを理解し、保留・再確認の判断を新人に指導できる。"],"name_en":"Keeping the Schedule and Holding Uncertain Cases","kanten_en":"Can they perform the exam at the designated time and hold and recheck animals with ambiguous results?","levels_en":["Ignores the schedule and finalizes judgments even when the result is ambiguous.","With guidance can perform the exam, but misses the judgment to hold and recheck.","With guidance can perform the basic exam at the designated time.","Independently keeps the schedule and holds ambiguous animals for rechecking.","Understands the risk of misjudgment and can teach new staff how to decide on holding and rechecking."],"name_vi":"Tuân thủ thời điểm thực hiện và tạm giữ kết luận","kanten_vi":"Có thực hiện đúng thời điểm quy định, với con có kết quả chưa rõ thì tạm giữ và kiểm tra lại không.","levels_vi":["Không giữ đúng thời điểm, kết quả chưa rõ vẫn kết luận.","Nếu được chỉ thị thì thực hiện, nhưng còn thiếu sót trong phán đoán tạm giữ, kiểm tra lại.","Nếu được chỉ thị thì kiểm tra đúng thời điểm quy định một cách cơ bản.","Dù không có chỉ thị vẫn giữ đúng thời điểm, con chưa rõ thì tạm giữ và kiểm tra lại.","Hiểu rủi ro kết luận sai, và có thể hướng dẫn người mới cách phán đoán tạm giữ, kiểm tra lại."],"name_id":"Menepati waktu pelaksanaan dan menunda penilaian yang meragukan","kanten_id":"Apakah melaksanakan pada waktu yang ditentukan, dan menunda serta memeriksa ulang individu yang hasilnya meragukan?","levels_id":["Tidak menepati waktu, dan tetap memastikan hasil walaupun penilaiannya meragukan.","Melaksanakan jika diperintah, tetapi sering lalai menunda dan memeriksa ulang.","Jika diperintah, dapat memeriksa pada waktu yang ditentukan secara lengkap.","Tanpa diperintah pun, menepati waktu, dan menunda individu yang meragukan lalu memeriksanya ulang.","Memahami risiko salah penilaian dan dapat mengajarkan penilaian tunda dan periksa ulang kepada karyawan baru."]},{"id":"reflect-result","name":"結果の即時反映と入室前の環境確認","kanten":"結果をその場でプレート・リストに反映し、分娩舎の衛生・飲水を確認できるか。","levels":["結果を反映せず、分娩舎の衛生・飲水確認も省く。","指示があれば反映するが、記録や環境確認に漏れがある。","指示があれば結果をひと通りプレート・リストに反映できる。","指示がなくても結果を即時反映し、入室前に分娩舎の衛生・飲水を確認する。","結果反映と環境準備の意義を理解し、入室前チェックを新人に指導できる。"],"name_en":"Immediate Recording of Results and Pre-Entry Environment Check","kanten_en":"Can they record results on plates and lists on the spot, and check hygiene and drinking water in the farrowing house?","levels_en":["Does not record results, and skips the hygiene and drinking-water checks in the farrowing house.","With guidance can record results, but misses records or environment checks.","With guidance can record the results on plates and lists through the basic procedure.","Independently records results immediately and checks hygiene and drinking water in the farrowing house before entry.","Understands the value of recording results and preparing the environment, and can teach new staff the pre-entry checks."],"name_vi":"Cập nhật kết quả ngay và kiểm tra môi trường trước khi vào chuồng","kanten_vi":"Có ghi ngay kết quả vào thẻ thông tin (plate) và danh sách, kiểm tra vệ sinh và nước uống của chuồng đẻ không.","levels_vi":["Không cập nhật kết quả, cũng bỏ qua việc kiểm tra vệ sinh, nước uống của chuồng đẻ.","Nếu được chỉ thị thì cập nhật, nhưng còn thiếu sót về ghi chép và kiểm tra môi trường.","Nếu được chỉ thị thì có thể ghi kết quả vào thẻ thông tin và danh sách một cách cơ bản.","Dù không có chỉ thị vẫn cập nhật kết quả ngay, kiểm tra vệ sinh và nước uống của chuồng đẻ trước khi cho lợn vào.","Hiểu ý nghĩa của việc cập nhật kết quả và chuẩn bị môi trường, và có thể hướng dẫn người mới cách kiểm tra trước khi cho lợn vào chuồng."],"name_id":"Segera mencatat hasil dan memeriksa lingkungan sebelum masuk","kanten_id":"Apakah dapat langsung mencatat hasil ke kartu data (plate) dan daftar, serta memeriksa kebersihan dan air minum kandang beranak?","levels_id":["Tidak mencatat hasil, dan melewatkan pemeriksaan kebersihan dan air minum kandang beranak.","Mencatat jika diperintah, tetapi sering lalai dalam pencatatan dan pemeriksaan lingkungan.","Jika diperintah, dapat mencatat hasil ke kartu data (plate) dan daftar secara lengkap.","Tanpa diperintah pun, langsung mencatat hasil, dan sebelum babi masuk memeriksa kebersihan dan air minum kandang beranak.","Memahami arti pencatatan hasil dan persiapan lingkungan, dan dapat mengajarkan pemeriksaan sebelum masuk kepada karyawan baru."]}],"gyomu":"24","name_en":"Entry Preparation (Ultrasound Exam)","purposeShort_en":"Move only pregnant sows into the farrowing house and find open sows early","name_vi":"Chuẩn bị vào chuồng đẻ (kiểm tra siêu âm)","purposeShort_vi":"Chỉ đưa lợn nái đang mang thai vào chuồng đẻ, phát hiện sớm lợn không mang thai","name_id":"Persiapan masuk kandang beranak (pemeriksaan USG)","purposeShort_id":"Memasukkan hanya induk babi yang bunting ke kandang beranak, dan cepat menemukan yang tidak bunting"},{"id":"pg","category":"breeding","no":"No.36","name":"PG（プロスタグランジン）接種","purposeShort":"分娩のタイミングをそろえ、分娩管理・立会いをしやすくする","aspects":[{"id":"gestation-day","name":"妊娠日数の確認と適期投与","kanten":"妊娠日数を正しく数え、113日以前の禁忌を避けて決められた日齢・対象に接種できるか。","levels":["妊娠日数を誤算して113日以前に投与し、早産・死産を招く。","指示があれば接種するが、日数確認や対象確認に漏れがある。","指示があれば決められた日齢・対象にひと通り接種できる。","指示がなくても妊娠日数を確認し、対象母豚を確かめて適期に接種する。","早期投与の禁忌と黄体の関係を理解し、適期投与の判断を新人に指導できる。"],"name_en":"Confirming Gestation Days and Timely Administration","kanten_en":"Can they count gestation days correctly, avoid the contraindicated period before day 113, and inject the designated animals at the designated day?","levels_en":["Miscounts gestation days, injects before day 113, and causes premature farrowing and stillbirths.","With guidance can inject, but misses the day count or the target-animal check.","With guidance can inject the designated animals at the designated day through the basic procedure.","Independently confirms gestation days, verifies the target sows, and injects at the right time.","Understands the contraindication of early administration and its relationship with the corpus luteum, and can teach new staff how to judge timely administration."],"name_vi":"Kiểm tra số ngày mang thai và tiêm đúng thời điểm","kanten_vi":"Có đếm đúng số ngày mang thai, tránh chống chỉ định tiêm trước ngày 113, tiêm đúng ngày tuổi thai và đúng đối tượng quy định không.","levels_vi":["Tính sai số ngày mang thai, tiêm trước ngày 113, gây đẻ non, thai chết lưu.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về kiểm tra số ngày và đối tượng.","Nếu được chỉ thị thì tiêm đúng ngày tuổi thai, đúng đối tượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn kiểm tra số ngày mang thai, xác nhận lợn nái đối tượng và tiêm đúng thời điểm.","Hiểu chống chỉ định tiêm sớm và quan hệ với thể vàng, và có thể hướng dẫn người mới cách phán đoán thời điểm tiêm phù hợp."],"name_id":"Memeriksa umur kebuntingan dan menyuntik pada waktu yang tepat","kanten_id":"Apakah dapat menghitung umur kebuntingan dengan benar, menghindari larangan penyuntikan sebelum hari ke-113, dan menyuntik pada umur dan sasaran yang ditentukan?","levels_id":["Salah menghitung umur kebuntingan sehingga menyuntik sebelum hari ke-113, dan menyebabkan lahir prematur atau lahir mati.","Menyuntik jika diperintah, tetapi sering lalai memeriksa jumlah hari dan sasaran.","Jika diperintah, dapat menyuntik pada umur dan sasaran yang ditentukan secara lengkap.","Tanpa diperintah pun, memeriksa umur kebuntingan, memastikan induk babi sasaran, dan menyuntik pada waktu yang tepat.","Memahami larangan penyuntikan terlalu awal dan hubungannya dengan korpus luteum, dan dapat mengajarkan penilaian waktu penyuntikan kepada karyawan baru."]},{"id":"injection-obs","name":"確実な注射と誘起後の分娩観察","kanten":"脂肪層への誤注射を避けて確実に注射し、誘起後の分娩観察を強化できるか。","levels":["脂肪層に誤注射して効果を弱め、誘起後の分娩観察も強化しない。","指示があれば接種するが、注射部位や観察強化に漏れがある。","指示があればひと通り正しく注射し、誘起後の観察ができる。","指示がなくても確実に筋注し、誘起後は分娩観察を強化する。","誤注射による吸収遅延を理解し、確実な注射と観察強化を新人に指導できる。"],"name_en":"Reliable Injection and Farrowing Observation After Induction","kanten_en":"Can they inject reliably while avoiding accidental injection into the fat layer, and intensify farrowing observation after induction?","levels_en":["Injects into the fat layer, weakening the effect, and does not intensify farrowing observation after induction.","With guidance can inject, but misses the injection site or the intensified observation.","With guidance can inject correctly and observe after induction through the basic procedure.","Independently gives a reliable intramuscular injection and intensifies farrowing observation after induction.","Understands delayed absorption from misplaced injections, and can teach new staff reliable injection and intensified observation."],"name_vi":"Tiêm chắc chắn và theo dõi đẻ sau khi kích thích","kanten_vi":"Có tiêm chắc chắn, tránh tiêm nhầm vào lớp mỡ, và tăng cường theo dõi đẻ sau khi kích thích không.","levels_vi":["Tiêm nhầm vào lớp mỡ làm giảm hiệu quả, cũng không tăng cường theo dõi đẻ sau khi kích thích.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về vị trí tiêm và tăng cường theo dõi.","Nếu được chỉ thị thì tiêm đúng và theo dõi sau khi kích thích một cách cơ bản.","Dù không có chỉ thị vẫn tiêm bắp chắc chắn, sau khi kích thích thì tăng cường theo dõi đẻ.","Hiểu việc tiêm sai chỗ làm thuốc hấp thu chậm, và có thể hướng dẫn người mới cách tiêm chắc chắn và tăng cường theo dõi."],"name_id":"Menyuntik dengan pasti dan mengawasi kelahiran setelah induksi","kanten_id":"Apakah dapat menyuntik dengan pasti tanpa salah masuk ke lapisan lemak, dan memperketat pengawasan kelahiran setelah induksi?","levels_id":["Salah menyuntik ke lapisan lemak sehingga efeknya lemah, dan tidak memperketat pengawasan kelahiran setelah induksi.","Menyuntik jika diperintah, tetapi sering lalai soal lokasi suntikan dan penguatan pengawasan.","Jika diperintah, dapat menyuntik dengan benar dan mengawasi setelah induksi secara lengkap.","Tanpa diperintah pun, menyuntik ke dalam otot dengan pasti, dan memperketat pengawasan kelahiran setelah induksi.","Memahami bahwa salah suntik memperlambat penyerapan obat, dan dapat mengajarkan cara menyuntik yang pasti dan penguatan pengawasan kepada karyawan baru."]}],"gyomu":"36","name_en":"PG (Prostaglandin) Injection","purposeShort_en":"Synchronize farrowing timing to make farrowing management and attendance easier","name_vi":"Tiêm PG (prostaglandin)","purposeShort_vi":"Làm đồng đều thời điểm đẻ, giúp quản lý đẻ và trực đẻ dễ dàng hơn","name_id":"Penyuntikan PG (prostaglandin) — induksi kelahiran","purposeShort_id":"Menyeragamkan waktu melahirkan agar pengelolaan dan pendampingan kelahiran lebih mudah"},{"id":"uterine-wash","category":"breeding","no":"No.42","name":"子宮内洗浄","purposeShort":"子宮内の汚染物を減らし、子宮炎・発熱を防ぎ産後回復を促す","aspects":[{"id":"target-select","name":"対象選定と獣医師指示の遵守","kanten":"全頭には行わず対象を選定し、薬剤の濃度・量を守って獣医師の指示に従えるか。","levels":["全頭にルーチンで行い、薬剤の濃度・量も守らず自然回復を妨げる。","指示があれば実施するが、対象選定や濃度管理に漏れがある。","指示があれば対象を選び、決められた濃度・量でひと通り実施できる。","指示がなくても手入れした母豚等に絞り、濃度・量を守って獣医師の指示に従う。","予防的ルーチン洗浄の弊害を理解し、対象選定と適正実施を新人に指導できる。"],"name_en":"Case Selection and Following Veterinary Instructions","kanten_en":"Can they select cases instead of treating every sow, keep the correct drug concentration and volume, and follow the veterinarian's instructions?","levels_en":["Performs it routinely on every sow, ignores drug concentration and volume, and hinders natural recovery.","With guidance can perform it, but misses case selection or concentration control.","With guidance can select cases and perform the basic procedure at the designated concentration and volume.","Independently limits treatment to sows that required manual intervention and the like, keeps concentration and volume, and follows the veterinarian's instructions.","Understands the harm of routine preventive flushing, and can teach new staff case selection and proper practice."],"name_vi":"Chọn đối tượng và tuân theo chỉ thị của bác sĩ thú y","kanten_vi":"Có chọn đối tượng thay vì làm cho tất cả, giữ đúng nồng độ và lượng thuốc, tuân theo chỉ thị của bác sĩ thú y không.","levels_vi":["Làm thường quy cho tất cả, không giữ đúng nồng độ và lượng thuốc, cản trở hồi phục tự nhiên.","Nếu được chỉ thị thì thực hiện, nhưng còn thiếu sót về chọn đối tượng và quản lý nồng độ.","Nếu được chỉ thị thì chọn đối tượng, thực hiện đúng nồng độ và lượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn chỉ làm cho lợn nái đã can thiệp bằng tay v.v., giữ đúng nồng độ, lượng thuốc và tuân theo chỉ thị của bác sĩ thú y.","Hiểu tác hại của việc rửa thường quy để phòng bệnh, và có thể hướng dẫn người mới cách chọn đối tượng và thực hiện đúng."],"name_id":"Memilih sasaran dan mengikuti perintah dokter hewan","kanten_id":"Apakah tidak melakukan pada semua babi tetapi memilih sasaran, menjaga kepekatan dan jumlah obat, serta mengikuti perintah dokter hewan?","levels_id":["Melakukan secara rutin pada semua babi, tidak menjaga kepekatan dan jumlah obat, sehingga menghambat pemulihan alami.","Melakukan jika diperintah, tetapi sering lalai memilih sasaran dan mengatur kepekatan.","Jika diperintah, dapat memilih sasaran dan melakukannya secara lengkap dengan kepekatan dan jumlah yang ditentukan.","Tanpa diperintah pun, membatasi hanya pada induk babi yang dibantu saat melahirkan dan sejenisnya, menjaga kepekatan dan jumlah obat, serta mengikuti perintah dokter hewan.","Memahami kerugian pencucian rutin sebagai pencegahan, dan dapat mengajarkan pemilihan sasaran dan pelaksanaan yang tepat kepada karyawan baru."]},{"id":"aseptic-gentle","name":"滅菌器具・穏やかな操作と術後観察","kanten":"滅菌した器具・洗浄液を使い、強くこすらず、実施後の体調・悪露を観察できるか。","levels":["非滅菌の器具・洗浄液を使い、強くこすって子宮内膜を傷め、術後観察も省く。","指示があれば実施するが、滅菌や術後観察に漏れがある。","指示があれば滅菌器具でひと通り実施し、術後の体調を確認できる。","指示がなくても滅菌器具で穏やかに操作し、実施後の体調・悪露を観察する。","二次汚染・内膜損傷のリスクを理解し、無菌操作と術後観察を新人に指導できる。"],"name_en":"Sterile Equipment, Gentle Handling, and Follow-up Observation","kanten_en":"Can they use sterilized equipment and flushing solution, avoid harsh scrubbing, and monitor condition and lochia afterward?","levels_en":["Uses unsterilized equipment and solution, scrubs hard and damages the endometrium, and skips follow-up observation.","With guidance can perform it, but misses sterilization or follow-up observation.","With guidance can perform the basic procedure with sterile equipment and check the sow's condition afterward.","Independently handles the procedure gently with sterile equipment and monitors condition and lochia afterward.","Understands the risks of secondary contamination and endometrial damage, and can teach new staff aseptic technique and follow-up observation."],"name_vi":"Dụng cụ tiệt trùng, thao tác nhẹ nhàng và theo dõi sau khi làm","kanten_vi":"Có dùng dụng cụ và dung dịch rửa đã tiệt trùng, không chà xát mạnh, theo dõi thể trạng và sản dịch sau khi thực hiện không.","levels_vi":["Dùng dụng cụ, dung dịch không tiệt trùng, chà xát mạnh làm tổn thương niêm mạc tử cung, cũng bỏ qua theo dõi sau khi làm.","Nếu được chỉ thị thì thực hiện, nhưng còn thiếu sót về tiệt trùng và theo dõi sau khi làm.","Nếu được chỉ thị thì thực hiện bằng dụng cụ tiệt trùng và kiểm tra thể trạng sau khi làm một cách cơ bản.","Dù không có chỉ thị vẫn thao tác nhẹ nhàng với dụng cụ tiệt trùng, theo dõi thể trạng và sản dịch sau khi thực hiện.","Hiểu rủi ro nhiễm bẩn thứ cấp và tổn thương niêm mạc, và có thể hướng dẫn người mới thao tác vô trùng và theo dõi sau khi làm."],"name_id":"Alat steril, penanganan lembut, dan pengawasan setelah tindakan","kanten_id":"Apakah memakai alat dan cairan pencuci yang steril, tidak menggosok keras, serta mengawasi kondisi tubuh dan cairan nifas (lokia) setelah tindakan?","levels_id":["Memakai alat dan cairan pencuci yang tidak steril, menggosok keras hingga melukai dinding rahim, dan melewatkan pengawasan setelah tindakan.","Melakukan jika diperintah, tetapi sering lalai soal sterilisasi dan pengawasan setelah tindakan.","Jika diperintah, dapat melakukannya secara lengkap dengan alat steril dan memeriksa kondisi tubuh setelah tindakan.","Tanpa diperintah pun, menangani dengan lembut memakai alat steril, dan setelah tindakan mengawasi kondisi tubuh dan cairan nifas (lokia).","Memahami risiko pencemaran ulang dan luka pada dinding rahim, dan dapat mengajarkan penanganan steril dan pengawasan setelah tindakan kepada karyawan baru."]}],"gyomu":"42","name_en":"Uterine Flushing","purposeShort_en":"Reduce uterine contamination, prevent metritis and fever, and promote postpartum recovery","name_vi":"Rửa tử cung (sau khi đẻ)","purposeShort_vi":"Giảm chất bẩn trong tử cung, phòng viêm tử cung, sốt và giúp hồi phục sau đẻ","name_id":"Pencucian rahim (setelah melahirkan)","purposeShort_id":"Mengurangi kotoran di dalam rahim, mencegah radang rahim dan demam, serta mempercepat pemulihan setelah melahirkan"},{"id":"farrow-entry","category":"farrowing","no":"No.26","name":"入室（分娩舎）","purposeShort":"分娩が近い母豚だけを入れ、落ち着いた状態で分娩を迎えさせる","aspects":[{"id":"prep-before","name":"入室前の舎内準備","kanten":"入室前に床・温度・水・エサと分娩クレートの洗浄・乾燥を整えられるか。","levels":["分娩舎の温度・保温灯を確認せず、クレート洗浄・乾燥も未完了のまま入室させ、子豚低体温死を招く。","指示があれば準備するが、温度設定やクレート乾燥の確認に漏れがある。","指示があれば床・温度・水・エサをひと通り整えられる。","指示がなくても入室前に温度・保温灯・水・エサとクレートの洗浄・乾燥を確認する。","入室前準備が子豚の生存に直結すると理解し、準備の要点を新人に指導できる。"],"name_en":"House Preparation Before Entry","kanten_en":"Can they prepare the floor, temperature, water, and feed, and wash and dry the farrowing crates before entry?","levels_en":["Moves sows in without checking the house temperature or heat lamps and with crates not yet washed and dried, causing piglet deaths from hypothermia.","With guidance can prepare, but misses the temperature settings or the crate-drying check.","With guidance can set up the floor, temperature, water, and feed through the basic procedure.","Independently checks temperature, heat lamps, water, feed, and crate washing and drying before entry.","Understands that pre-entry preparation directly affects piglet survival, and can teach new staff the key points of preparation."],"name_vi":"Chuẩn bị trong chuồng trước khi đưa lợn vào","kanten_vi":"Trước khi đưa lợn vào, có chuẩn bị sàn, nhiệt độ, nước, thức ăn và rửa, làm khô cũi đẻ không.","levels_vi":["Không kiểm tra nhiệt độ và đèn sưởi ấm của chuồng đẻ, đưa lợn vào khi cũi chưa rửa, chưa khô, khiến lợn con chết vì hạ thân nhiệt.","Nếu được chỉ thị thì chuẩn bị, nhưng còn thiếu sót về kiểm tra cài đặt nhiệt độ và độ khô của cũi.","Nếu được chỉ thị thì chuẩn bị sàn, nhiệt độ, nước, thức ăn được cơ bản.","Dù không có chỉ thị vẫn kiểm tra nhiệt độ, đèn sưởi ấm, nước, thức ăn và việc rửa, làm khô cũi trước khi đưa lợn vào.","Hiểu việc chuẩn bị trước khi vào chuồng liên quan trực tiếp đến sự sống của lợn con, và có thể hướng dẫn người mới các điểm chính của việc chuẩn bị."],"name_id":"Menyiapkan kandang sebelum babi masuk","kanten_id":"Apakah sebelum babi masuk dapat menyiapkan lantai, suhu, air, pakan, serta mencuci dan mengeringkan farrowing crate?","levels_id":["Tidak memeriksa suhu dan lampu pemanas kandang beranak, memasukkan babi sebelum farrowing crate selesai dicuci dan dikeringkan, sehingga anak babi mati kedinginan.","Menyiapkan jika diperintah, tetapi sering lalai memeriksa pengaturan suhu dan kekeringan crate.","Jika diperintah, dapat menyiapkan lantai, suhu, air, dan pakan secara lengkap.","Tanpa diperintah pun, sebelum babi masuk memeriksa suhu, lampu pemanas, air, pakan, serta pencucian dan pengeringan crate.","Memahami bahwa persiapan sebelum masuk langsung menentukan hidup mati anak babi, dan dapat mengajarkan pokok persiapan kepada karyawan baru."]},{"id":"batch-entry","name":"適期の一斉入室と入室後観察","kanten":"分娩が近い母豚をロットごとに一斉入室させ、途中追加を避け、入室後の体調・行動を観察できるか。","levels":["入室タイミングが遅れて妊娠舎で分娩させ、入室後の観察も怠る。","指示があれば入室させるが、タイミングや一斉入室の管理に漏れがある。","指示があればロットごとに一斉入室させ、ひと通り観察できる。","指示がなくても適期にロット単位で入室させ、途中追加を避けて入室後を観察する。","オールイン・オールアウトの意義を理解し、適期入室と観察を新人に指導できる。"],"name_en":"Timely Batch Entry and Observation After Entry","kanten_en":"Can they move sows close to farrowing in by lot all at once, avoid mid-batch additions, and observe condition and behavior after entry?","levels_en":["Moves sows in too late so they farrow in the gestation house, and neglects observation after entry.","With guidance can move sows in, but misses the timing or batch-entry management.","With guidance can move sows in by lot all at once and observe them through the basic routine.","Independently moves sows in by lot at the right time, avoids mid-batch additions, and observes them after entry.","Understands the value of all-in/all-out, and can teach new staff timely entry and observation."],"name_vi":"Đưa vào đồng loạt đúng thời điểm và theo dõi sau khi vào","kanten_vi":"Có đưa lợn nái sắp đẻ vào đồng loạt theo từng lô, tránh bổ sung giữa chừng, theo dõi thể trạng và hành vi sau khi vào không.","levels_vi":["Đưa vào muộn khiến nái đẻ ở chuồng mang thai, cũng lơ là theo dõi sau khi vào.","Nếu được chỉ thị thì đưa lợn vào, nhưng còn thiếu sót về thời điểm và quản lý đưa vào đồng loạt.","Nếu được chỉ thị thì đưa vào đồng loạt theo lô và theo dõi được cơ bản.","Dù không có chỉ thị vẫn đưa vào theo lô đúng thời điểm, tránh bổ sung giữa chừng và theo dõi sau khi vào.","Hiểu ý nghĩa của cùng vào - cùng ra (all-in all-out), và có thể hướng dẫn người mới việc đưa vào đúng thời điểm và theo dõi."],"name_id":"Memasukkan serentak pada waktu yang tepat dan mengawasi setelahnya","kanten_id":"Apakah dapat memasukkan induk babi yang hampir melahirkan serentak per kelompok (lot), menghindari penambahan di tengah jalan, dan mengawasi kondisi tubuh dan tingkah lakunya setelah masuk?","levels_id":["Terlambat memasukkan sehingga babi melahirkan di kandang bunting, dan lalai mengawasi setelah masuk.","Memasukkan jika diperintah, tetapi sering lalai soal waktu dan pengaturan masuk serentak.","Jika diperintah, dapat memasukkan serentak per kelompok (lot) dan mengawasinya secara lengkap.","Tanpa diperintah pun, memasukkan per kelompok (lot) pada waktu yang tepat, menghindari penambahan di tengah jalan, dan mengawasi setelah masuk.","Memahami arti sistem all-in all-out, dan dapat mengajarkan waktu masuk yang tepat dan pengawasan kepada karyawan baru."]}],"gyomu":"26","name_en":"Entry (Farrowing House)","purposeShort_en":"Move in only sows close to farrowing so they can farrow in a calm state","name_vi":"Đưa nái vào chuồng đẻ","purposeShort_vi":"Chỉ đưa lợn nái sắp đẻ vào, để nái đón cuộc đẻ trong trạng thái yên tĩnh","name_id":"Memasukkan induk ke kandang beranak","purposeShort_id":"Memasukkan hanya induk babi yang hampir melahirkan, agar melahirkan dalam keadaan tenang"},{"id":"farrow-assist","category":"farrowing","no":"No.35","name":"分娩介助","purposeShort":"母豚と子豚の命を守り、死産・直後の死亡を減らし初乳を飲ませる","aspects":[{"id":"timing","name":"介助タイミングの見極め","kanten":"分娩間隔を計り、子豚が長く出てこない時だけ適切に介助できるか。","levels":["分娩間隔を見ずに放置し、45分を超えても介助せず低酸素・死産を増やす。","指示があれば介助するが、分娩間隔の見極めが甘く判断は他者まかせ。","指示があれば分娩間隔を計り、長く出ない時にひと通り介助できる。","指示がなくても分娩間隔を計り、必要な時だけ適切に介助する。","分娩間隔と低酸素・死産の関係を理解し、介助の見極めを新人に指導できる。"],"name_en":"Judging When to Assist","kanten_en":"Can they time the birth intervals and assist properly only when a piglet is long overdue?","levels_en":["Leaves the sow unattended without watching birth intervals, fails to assist even past 45 minutes, and increases hypoxia and stillbirths.","With guidance can assist, but judges birth intervals poorly and leaves decisions to others.","With guidance can time birth intervals and perform basic assistance when a piglet is long overdue.","Independently times birth intervals and assists properly only when needed.","Understands the relationship between birth intervals, hypoxia, and stillbirth, and can teach new staff how to judge when to assist."],"name_vi":"Phán đoán thời điểm can thiệp","kanten_vi":"Có đo khoảng cách giữa các lần đẻ, chỉ can thiệp đúng cách khi lợn con lâu không ra không.","levels_vi":["Không theo dõi khoảng cách giữa các lần đẻ mà bỏ mặc, quá 45 phút vẫn không can thiệp, làm tăng thiếu oxy và chết lưu.","Nếu được chỉ thị thì can thiệp, nhưng phán đoán khoảng cách đẻ còn kém và phó mặc người khác quyết định.","Nếu được chỉ thị thì đo khoảng cách giữa các lần đẻ và can thiệp được cơ bản khi lợn con lâu không ra.","Dù không có chỉ thị vẫn đo khoảng cách giữa các lần đẻ, chỉ can thiệp đúng cách khi cần.","Hiểu quan hệ giữa khoảng cách đẻ với thiếu oxy, chết lưu, và có thể hướng dẫn người mới cách phán đoán khi nào cần can thiệp."],"name_id":"Menilai waktu yang tepat untuk membantu","kanten_id":"Apakah dapat mengukur jarak waktu antar kelahiran, dan membantu dengan tepat hanya saat anak babi lama tidak keluar?","levels_id":["Membiarkan tanpa melihat jarak waktu antar kelahiran, tidak membantu walau lebih dari 45 menit, sehingga kekurangan oksigen dan lahir mati bertambah.","Membantu jika diperintah, tetapi penilaian jarak waktu antar kelahiran lemah dan keputusan diserahkan ke orang lain.","Jika diperintah, dapat mengukur jarak waktu antar kelahiran dan membantu secara lengkap saat anak babi lama tidak keluar.","Tanpa diperintah pun, mengukur jarak waktu antar kelahiran dan membantu dengan tepat hanya saat diperlukan.","Memahami hubungan jarak waktu antar kelahiran dengan kekurangan oksigen dan lahir mati, dan dapat mengajarkan penilaian kapan harus membantu kepada karyawan baru."]},{"id":"asepsis-lubric","name":"清潔・潤滑と薬剤の適正使用","kanten":"介助時に清潔と潤滑を守り、オキシトシンを過剰投与せず適正に使えるか。","levels":["清潔・潤滑を守らず、オキシトシンを過剰投与して過強陣痛・死産を招く。","指示があれば清潔にするが、潤滑や薬剤量の管理に漏れがある。","指示があれば清潔と潤滑を守り、ひと通り介助できる。","指示がなくても清潔・潤滑を徹底し、薬剤を適正量で使う。","過剰投与の危険を理解し、清潔操作と薬剤の適正使用を新人に指導できる。"],"name_en":"Cleanliness, Lubrication, and Proper Drug Use","kanten_en":"Can they keep clean and lubricated during assistance and use oxytocin properly without overdosing?","levels_en":["Ignores cleanliness and lubrication, and overdoses oxytocin, causing hypertonic labor and stillbirths.","With guidance keeps things clean, but misses lubrication or dose control.","With guidance can keep clean and lubricated and perform basic assistance.","Independently maintains thorough cleanliness and lubrication and uses drugs at the proper dose.","Understands the dangers of overdosing, and can teach new staff clean technique and proper drug use."],"name_vi":"Sạch sẽ, bôi trơn và dùng thuốc đúng cách","kanten_vi":"Khi can thiệp có giữ sạch sẽ và bôi trơn, dùng oxytocin (thuốc giục đẻ) đúng cách, không quá liều không.","levels_vi":["Không giữ sạch sẽ, không bôi trơn, tiêm oxytocin quá liều gây cơn co quá mạnh, chết lưu.","Nếu được chỉ thị thì giữ sạch, nhưng còn thiếu sót về bôi trơn và quản lý liều thuốc.","Nếu được chỉ thị thì giữ sạch sẽ, bôi trơn và can thiệp được cơ bản.","Dù không có chỉ thị vẫn giữ sạch sẽ, bôi trơn triệt để, dùng thuốc đúng liều.","Hiểu nguy hiểm của việc quá liều, và có thể hướng dẫn người mới thao tác sạch sẽ và dùng thuốc đúng cách."],"name_id":"Kebersihan, pelumas, dan pemakaian obat yang tepat","kanten_id":"Apakah saat membantu menjaga kebersihan dan memakai pelumas, serta memakai oksitosin dengan tepat tanpa dosis berlebihan?","levels_id":["Tidak menjaga kebersihan dan pelumas, memberi oksitosin berlebihan sehingga kontraksi terlalu kuat dan terjadi lahir mati.","Menjaga kebersihan jika diperintah, tetapi sering lalai soal pelumas dan takaran obat.","Jika diperintah, dapat menjaga kebersihan dan pelumas serta membantu secara lengkap.","Tanpa diperintah pun, menjaga kebersihan dan pelumas dengan ketat, dan memakai obat dengan takaran yang tepat.","Memahami bahaya dosis berlebihan, dan dapat mengajarkan penanganan bersih dan pemakaian obat yang tepat kepada karyawan baru."]},{"id":"newborn-care","name":"新生子豚の乾燥・保温・蘇生","kanten":"生まれた子豚をすぐ乾かし温め、呼吸を確認し、仮死子豚を蘇生できるか。","levels":["子豚を乾かさず温めず、仮死子豚を死産と誤判断して蘇生処置を省く。","指示があれば処置するが、呼吸確認や蘇生の判断に漏れがある。","指示があれば子豚を乾かし温め、呼吸をひと通り確認できる。","指示がなくてもすぐ乾かして温め、仮死子豚を見分けて蘇生処置を行う。","仮死と死産の見分けや蘇生の意義を理解し、新生子豚の初期処置を新人に指導できる。"],"name_en":"Drying, Warming, and Resuscitating Newborn Piglets","kanten_en":"Can they dry and warm newborn piglets immediately, check breathing, and resuscitate piglets born in apparent lifelessness?","levels_en":["Does not dry or warm piglets, mistakes asphyxiated piglets for stillbirths, and skips resuscitation.","With guidance can treat piglets, but misses breathing checks or the decision to resuscitate.","With guidance can dry and warm piglets and check breathing through the basic routine.","Independently dries and warms piglets immediately, recognizes asphyxiated piglets, and performs resuscitation.","Understands how to distinguish asphyxia from stillbirth and the value of resuscitation, and can teach new staff the initial care of newborn piglets."],"name_vi":"Lau khô, giữ ấm, hồi sức lợn con sơ sinh","kanten_vi":"Có lau khô, sưởi ấm lợn con ngay sau khi sinh, kiểm tra hô hấp và hồi sức cho lợn con bị ngạt không.","levels_vi":["Không lau khô, không sưởi ấm lợn con, nhầm lợn con bị ngạt là chết lưu và bỏ qua hồi sức.","Nếu được chỉ thị thì xử lý, nhưng còn thiếu sót trong kiểm tra hô hấp và phán đoán hồi sức.","Nếu được chỉ thị thì lau khô, sưởi ấm lợn con và kiểm tra hô hấp được cơ bản.","Dù không có chỉ thị vẫn lau khô, sưởi ấm ngay, phân biệt được lợn con bị ngạt và tiến hành hồi sức.","Hiểu cách phân biệt ngạt với chết lưu và ý nghĩa của hồi sức, và có thể hướng dẫn người mới cách xử lý ban đầu cho lợn con sơ sinh."],"name_id":"Mengeringkan, menghangatkan, dan menghidupkan kembali anak babi baru lahir","kanten_id":"Apakah dapat segera mengeringkan dan menghangatkan anak babi yang lahir, memeriksa napasnya, dan menolong anak babi yang lemas seperti mati (asfiksia)?","levels_id":["Tidak mengeringkan dan menghangatkan anak babi, salah mengira anak babi lemas sebagai lahir mati, dan melewatkan pertolongan napas.","Menangani jika diperintah, tetapi sering lalai memeriksa napas dan menilai perlunya pertolongan.","Jika diperintah, dapat mengeringkan dan menghangatkan anak babi serta memeriksa napasnya secara lengkap.","Tanpa diperintah pun, segera mengeringkan dan menghangatkan, membedakan anak babi lemas dan melakukan pertolongan napas.","Memahami cara membedakan lemas dan lahir mati serta arti pertolongan napas, dan dapat mengajarkan penanganan awal anak babi baru lahir kepada karyawan baru."]}],"gyomu":"35","name_en":"Farrowing Assistance","purposeShort_en":"Protect the lives of sows and piglets, reduce stillbirths and early deaths, and ensure colostrum intake","name_vi":"Hỗ trợ đỡ đẻ","purposeShort_vi":"Bảo vệ tính mạng lợn nái và lợn con, giảm chết lưu, chết ngay sau đẻ và cho bú sữa đầu","name_id":"Membantu proses kelahiran","purposeShort_id":"Melindungi nyawa induk dan anak babi, mengurangi lahir mati dan kematian setelah lahir, serta memberi kolostrum (susu pertama)"},{"id":"cross-foster","category":"farrowing","no":"No.39","name":"送り里子","purposeShort":"乳頭数と子豚数のバランスを整え、離乳頭数を増やし弱子を助ける","aspects":[{"id":"colostrum-first","name":"初乳摂取後の里子と対象選び","kanten":"初乳を飲ませてから、日齢・体重が近い健康な子豚を組み合わせ、乳頭数を超えないよう里子に出せるか。","levels":["初乳摂取が不十分なまま移動させ、体重差の大きい子豚を混ぜ、病気の子豚も里子にする。","指示があれば里子に出すが、初乳確認や対象選びに漏れが多い。","指示があれば初乳を飲ませてから日齢・体重の近い子豚をひと通り組める。","指示がなくても生後12〜24時間で初乳を飲ませ、体重差を抑えて乳頭数内に収める。","初乳と免疫獲得の関係を理解し、里子の対象選びと頭数管理を新人に指導できる。"],"name_en":"Fostering After Colostrum Intake and Selecting Candidates","kanten_en":"Can they foster only after colostrum intake, match healthy piglets of similar age and weight, and stay within the teat count?","levels_en":["Moves piglets with insufficient colostrum intake, mixes piglets with large weight differences, and fosters sick piglets too.","With guidance can foster, but often misses the colostrum check or candidate selection.","With guidance can ensure colostrum intake first and match piglets of similar age and weight through the basic procedure.","Independently ensures colostrum intake within 12-24 hours of birth, limits weight differences, and stays within the teat count.","Understands the relationship between colostrum and immunity, and can teach new staff candidate selection and litter-size management."],"name_vi":"Ghép bầy sau khi bú sữa đầu và chọn đối tượng","kanten_vi":"Có cho bú sữa đầu trước, ghép các lợn con khỏe mạnh có ngày tuổi, cân nặng gần nhau, không vượt quá số vú không.","levels_vi":["Chuyển đi khi chưa bú đủ sữa đầu, ghép lợn con chênh lệch cân nặng lớn, cho cả lợn con bệnh đi ghép bầy.","Nếu được chỉ thị thì ghép bầy, nhưng hay thiếu sót về kiểm tra sữa đầu và chọn đối tượng.","Nếu được chỉ thị thì cho bú sữa đầu rồi ghép các con có ngày tuổi, cân nặng gần nhau một cách cơ bản.","Dù không có chỉ thị vẫn cho bú sữa đầu trong 12-24 giờ sau sinh, hạn chế chênh lệch cân nặng và giữ trong số vú.","Hiểu quan hệ giữa sữa đầu và miễn dịch, và có thể hướng dẫn người mới cách chọn con ghép bầy và quản lý số con."],"name_id":"Menitipkan setelah minum kolostrum dan memilih sasaran","kanten_id":"Apakah menitipkan setelah anak minum kolostrum (susu pertama), memasangkan anak babi sehat yang umur dan beratnya berdekatan, dan tidak melebihi jumlah puting?","levels_id":["Memindahkan sebelum cukup minum kolostrum, mencampur anak babi yang beda beratnya besar, dan menitipkan juga anak babi yang sakit.","Menitipkan jika diperintah, tetapi sering lalai memastikan kolostrum dan memilih sasaran.","Jika diperintah, dapat memasangkan anak babi yang umur dan beratnya berdekatan secara lengkap setelah minum kolostrum.","Tanpa diperintah pun, memberi kolostrum dalam 12-24 jam setelah lahir, menekan beda berat, dan menjaga jumlah dalam batas jumlah puting.","Memahami hubungan kolostrum dengan kekebalan, dan dapat mengajarkan pemilihan anak titipan dan pengaturan jumlah kepada karyawan baru."]},{"id":"acceptance-care","name":"母豚の拒絶対策","kanten":"里子移動時に臭い付けなどで母豚の拒絶を防ぎ、定着を確認できるか。","levels":["臭い付けなどの拒絶対策をせず、母豚に拒まれても放置する。","指示があれば対策するが、定着の確認に漏れがある。","指示があれば拒絶対策をひと通り行える。","指示がなくても臭い付け等で拒絶を防ぎ、定着を確認する。","母豚の拒絶の仕組みを理解し、拒絶対策と定着確認を新人に指導できる。"],"name_en":"Preventing Rejection by the Sow","kanten_en":"Can they prevent rejection by the sow with scent-masking and the like during fostering, and confirm the piglets settle in?","levels_en":["Takes no anti-rejection measures such as scent-masking, and leaves piglets alone even when the sow rejects them.","With guidance can take measures, but misses confirming that the piglets settle in.","With guidance can carry out the basic anti-rejection measures.","Independently prevents rejection with scent-masking and the like and confirms the piglets settle in.","Understands how sow rejection occurs, and can teach new staff anti-rejection measures and settlement checks."],"name_vi":"Đối sách khi nái từ chối con","kanten_vi":"Khi chuyển con ghép bầy có phòng nái từ chối bằng cách tạo mùi v.v., kiểm tra con đã quen bầy chưa không.","levels_vi":["Không có biện pháp như tạo mùi, nái từ chối cũng bỏ mặc.","Nếu được chỉ thị thì làm, nhưng còn thiếu sót trong kiểm tra con đã quen bầy chưa.","Nếu được chỉ thị thì thực hiện đối sách chống từ chối được cơ bản.","Dù không có chỉ thị vẫn phòng từ chối bằng tạo mùi v.v. và kiểm tra con đã quen bầy.","Hiểu cơ chế nái từ chối con, và có thể hướng dẫn người mới cách chống từ chối và kiểm tra con quen bầy."],"name_id":"Mencegah penolakan oleh induk babi","kanten_id":"Apakah saat memindahkan anak titipan dapat mencegah penolakan induk babi, misalnya dengan menyamakan bau, dan memastikan anak diterima?","levels_id":["Tidak melakukan pencegahan penolakan seperti menyamakan bau, dan membiarkan walaupun induk babi menolak.","Melakukan pencegahan jika diperintah, tetapi sering lalai memastikan anak diterima.","Jika diperintah, dapat melakukan pencegahan penolakan secara lengkap.","Tanpa diperintah pun, mencegah penolakan dengan menyamakan bau dan sebagainya, lalu memastikan anak diterima.","Memahami mengapa induk babi menolak, dan dapat mengajarkan pencegahan penolakan dan pemastian penerimaan kepada karyawan baru."]}],"gyomu":"39","name_en":"Cross-Fostering","purposeShort_en":"Balance teat numbers and litter sizes, increase weaned piglets, and help weak piglets","name_vi":"Ghép bầy (cho nái khác nuôi)","purposeShort_vi":"Cân bằng số vú và số lợn con, tăng số con cai sữa và cứu con yếu","name_id":"Titip anak ke induk lain","purposeShort_id":"Menyeimbangkan jumlah puting dan jumlah anak babi, menambah jumlah anak sapih, dan menolong anak yang lemah"},{"id":"sow-lineup","category":"facility","no":"No.13","name":"母豚の並びの整理","purposeShort":"母豚をまとめて管理しやすくし、ケンカ・ストレスを減らす","aspects":[{"id":"schedule-order","name":"分娩予定日順の整列と台帳反映","kanten":"交配日・分娩予定日のズレを抑えて整列させ、並び情報を台帳に反映できるか。","levels":["分娩予定日順に整列させず、並び情報も台帳に反映せず認識齟齬を招く。","指示があれば整列させるが、予定日順の徹底や台帳反映に漏れがある。","指示があれば分娩予定日順にひと通り整列できる。","指示がなくても予定日のズレを抑えて整列させ、並び情報を台帳に反映する。","整列と移動指示の連動を理解し、並び管理と台帳反映を新人に指導できる。"],"name_en":"Lining Up by Due Date and Updating the Ledger","kanten_en":"Can they line up sows with minimal gaps in mating and due dates, and record the lineup in the ledger?","levels_en":["Does not line sows up by due date and does not record the lineup in the ledger, causing misunderstandings.","With guidance can line sows up, but misses strict due-date ordering or ledger updates.","With guidance can line sows up by due date through the basic procedure.","Independently lines sows up with minimal due-date gaps and records the lineup in the ledger.","Understands how the lineup links to movement orders, and can teach new staff lineup management and ledger updates."],"name_vi":"Xếp theo thứ tự ngày dự sinh và cập nhật sổ quản lý","kanten_vi":"Có xếp hàng sao cho ngày giao phối, ngày dự sinh ít chênh lệch, và ghi thông tin vị trí vào sổ quản lý không.","levels_vi":["Không xếp theo thứ tự ngày dự sinh, cũng không ghi thông tin vị trí vào sổ, gây hiểu nhầm lẫn nhau.","Nếu được chỉ thị thì xếp, nhưng còn thiếu sót về xếp đúng thứ tự ngày dự sinh và cập nhật sổ.","Nếu được chỉ thị thì xếp theo thứ tự ngày dự sinh được cơ bản.","Dù không có chỉ thị vẫn xếp cho ngày dự sinh ít chênh lệch và ghi thông tin vị trí vào sổ quản lý.","Hiểu sự liên kết giữa xếp hàng và chỉ thị di chuyển, và có thể hướng dẫn người mới cách quản lý vị trí và cập nhật sổ."],"name_id":"Menata urut tanggal perkiraan melahirkan dan mencatat ke buku","kanten_id":"Apakah dapat menata dengan menekan selisih tanggal kawin dan perkiraan melahirkan, serta mencatat susunan posisinya ke buku catatan?","levels_id":["Tidak menata urut tanggal perkiraan melahirkan, tidak mencatat susunan ke buku catatan, sehingga terjadi salah paham.","Menata jika diperintah, tetapi sering lalai menepati urutan tanggal dan mencatat ke buku.","Jika diperintah, dapat menata urut tanggal perkiraan melahirkan secara lengkap.","Tanpa diperintah pun, menata dengan menekan selisih tanggal perkiraan, dan mencatat susunan posisi ke buku catatan.","Memahami kaitan penataan dengan instruksi pemindahan, dan dapat mengajarkan pengaturan susunan dan pencatatan kepada karyawan baru."]},{"id":"compatibility","name":"体格差・攻撃性への配慮","kanten":"極端に弱い・大きい母豚や攻撃的な個体を同じ並びに入れず、負傷を防げるか。","levels":["体格差・攻撃性を考えず収容し、負傷が出ても気にしない。","指示があれば配慮するが、体格差や攻撃性の見極めに漏れがある。","指示があれば極端に弱い・大きい母豚を分けてひと通り配置できる。","指示がなくても体格差・攻撃性を見て収容し、妊娠初期の大きな並び替えを避ける。","収容と負傷・ストレスの関係を理解し、相性を考えた配置を新人に指導できる。"],"name_en":"Accounting for Size Differences and Aggression","kanten_en":"Can they keep extremely weak, oversized, or aggressive sows out of the same lineup and prevent injuries?","levels_en":["Houses sows without regard to size differences or aggression, and does not care even when injuries occur.","With guidance can take care, but misses judging size differences or aggression.","With guidance can separate extremely weak or oversized sows and complete the basic placement.","Independently houses sows with attention to size and aggression, and avoids major regrouping in early gestation.","Understands how housing relates to injury and stress, and can teach new staff compatibility-based placement."],"name_vi":"Chú ý chênh lệch thể trạng và tính hung dữ","kanten_vi":"Có tránh xếp lợn nái quá yếu, quá to hoặc con hung dữ vào cùng hàng, phòng bị thương không.","levels_vi":["Xếp lợn không xét chênh lệch thể trạng, tính hung dữ, có con bị thương cũng không quan tâm.","Nếu được chỉ thị thì chú ý, nhưng còn thiếu sót trong nhận biết chênh lệch thể trạng và tính hung dữ.","Nếu được chỉ thị thì tách riêng lợn nái quá yếu, quá to và sắp xếp được cơ bản.","Dù không có chỉ thị vẫn xem thể trạng, tính hung dữ khi xếp, tránh xáo trộn lớn vào đầu thai kỳ.","Hiểu quan hệ giữa cách xếp với bị thương, stress, và có thể hướng dẫn người mới cách bố trí có xét đến sự hợp nhau."],"name_id":"Memperhatikan beda ukuran badan dan sifat agresif","kanten_id":"Apakah tidak menempatkan induk babi yang sangat lemah, sangat besar, atau agresif dalam satu barisan, sehingga mencegah luka?","levels_id":["Menempatkan tanpa memikirkan beda ukuran badan dan sifat agresif, dan tidak peduli walaupun ada yang terluka.","Memperhatikan jika diperintah, tetapi sering lalai menilai beda ukuran badan dan sifat agresif.","Jika diperintah, dapat memisahkan induk babi yang sangat lemah atau sangat besar dan menempatkannya secara lengkap.","Tanpa diperintah pun, menempatkan dengan melihat beda ukuran badan dan sifat agresif, serta menghindari penataan ulang besar pada awal kebuntingan.","Memahami hubungan penempatan dengan luka dan stres, dan dapat mengajarkan penempatan yang memperhatikan kecocokan kepada karyawan baru."]}],"gyomu":"13","name_en":"Organizing the Sow Lineup","purposeShort_en":"Group sows for easier management and reduce fighting and stress","name_vi":"Sắp xếp lại vị trí lợn nái","purposeShort_vi":"Gom lợn nái lại cho dễ quản lý, giảm đánh nhau và stress","name_id":"Menata ulang posisi induk babi","purposeShort_id":"Mengelompokkan induk babi agar mudah dikelola, serta mengurangi perkelahian dan stres"},{"id":"move-order","category":"facility","no":"No.10","name":"移動指示","purposeShort":"ピッグフローを滞らせず、豚にストレスをかけず安全に移動させる","aspects":[{"id":"count-handover","name":"頭数・グループ確認と引き継ぎ","kanten":"移動する頭数・グループを事前確認し、口頭のみに頼らず引き継いで誤移動を防げるか。","levels":["口頭のみで指示し、頭数照合もせず担当交代時に誤移動・在庫ズレを招く。","指示があれば確認するが、頭数照合や引き継ぎに漏れが多い。","指示があれば移動頭数・グループをひと通り事前確認できる。","指示がなくても頭数・グループを確認し、記録で引き継いで実頭数と照合する。","誤移動・在庫ズレのリスクを理解し、頭数管理と引き継ぎを新人に指導できる。"],"name_en":"Confirming Head Counts and Groups, and Handover","kanten_en":"Can they confirm the head count and group to be moved in advance, and hand over with records rather than word of mouth to prevent wrong moves?","levels_en":["Gives orders only verbally without count verification, causing wrong moves and inventory mismatches at shift changes.","With guidance can confirm, but often misses count verification or handover.","With guidance can confirm the head count and group to be moved in advance through the basic procedure.","Independently confirms head counts and groups, hands over with records, and verifies against actual counts.","Understands the risks of wrong moves and inventory mismatches, and can teach new staff count management and handover."],"name_vi":"Kiểm tra số con, nhóm và bàn giao","kanten_vi":"Có kiểm tra trước số con, nhóm cần di chuyển, không chỉ dựa vào lời nói mà bàn giao bằng ghi chép để tránh di chuyển nhầm không.","levels_vi":["Chỉ thị chỉ bằng lời nói, không đối chiếu số con, gây di chuyển nhầm, lệch tồn kho khi đổi ca.","Nếu được chỉ thị thì kiểm tra, nhưng hay thiếu sót về đối chiếu số con và bàn giao.","Nếu được chỉ thị thì kiểm tra trước số con, nhóm di chuyển được cơ bản.","Dù không có chỉ thị vẫn kiểm tra số con, nhóm, bàn giao bằng ghi chép và đối chiếu với số con thực tế.","Hiểu rủi ro di chuyển nhầm, lệch tồn kho, và có thể hướng dẫn người mới cách quản lý số con và bàn giao."],"name_id":"Memeriksa jumlah ekor dan kelompok serta serah terima","kanten_id":"Apakah dapat memeriksa lebih dulu jumlah ekor dan kelompok yang dipindah, serta melakukan serah terima tidak hanya secara lisan sehingga mencegah salah pindah?","levels_id":["Memberi perintah hanya secara lisan tanpa mencocokkan jumlah ekor, sehingga saat ganti petugas terjadi salah pindah dan selisih stok.","Memeriksa jika diperintah, tetapi sering lalai mencocokkan jumlah ekor dan serah terima.","Jika diperintah, dapat memeriksa lebih dulu jumlah ekor dan kelompok yang dipindah secara lengkap.","Tanpa diperintah pun, memeriksa jumlah ekor dan kelompok, melakukan serah terima dengan catatan, dan mencocokkan dengan jumlah ekor sebenarnya.","Memahami risiko salah pindah dan selisih stok, dan dapat mengajarkan pengelolaan jumlah ekor dan serah terima kepada karyawan baru."]},{"id":"route-biosec","name":"通路確認と移動先の清浄性","kanten":"通路の段差・滑り・障害物を先に確認し、移動先の清掃・消毒完了を確かめて汚染搬入を防げるか。","levels":["通路を確認せず、清掃・消毒完了前の汚染豚舎に搬入する。","指示があれば通路を見るが、移動先の清浄性確認に漏れがある。","指示があれば通路の危険をひと通り確認できる。","指示がなくても通路を先に点検し、移動先の清掃・消毒完了を確かめてから移動する。","移動と防疫の関係を理解し、通路点検と清浄性確認を新人に指導できる。"],"name_en":"Checking Routes and Destination Cleanliness","kanten_en":"Can they check the route in advance for steps, slippery spots, and obstacles, and confirm the destination's cleaning and disinfection are complete to prevent bringing in contamination?","levels_en":["Does not check the route and moves pigs into a contaminated barn before cleaning and disinfection are complete.","With guidance checks the route, but misses confirming the destination's cleanliness.","With guidance can check the route hazards through the basic procedure.","Independently inspects the route first and confirms the destination's cleaning and disinfection are complete before moving.","Understands the link between movement and biosecurity, and can teach new staff route inspection and cleanliness checks."],"name_vi":"Kiểm tra lối đi và độ sạch của nơi chuyển đến","kanten_vi":"Có kiểm tra trước bậc, chỗ trơn, vật cản trên lối đi, xác nhận nơi chuyển đến đã vệ sinh, khử trùng xong để tránh mang ô nhiễm vào không.","levels_vi":["Không kiểm tra lối đi, đưa lợn vào chuồng ô nhiễm chưa vệ sinh, khử trùng xong.","Nếu được chỉ thị thì xem lối đi, nhưng còn thiếu sót trong kiểm tra độ sạch của nơi chuyển đến.","Nếu được chỉ thị thì kiểm tra chỗ nguy hiểm trên lối đi được cơ bản.","Dù không có chỉ thị vẫn kiểm tra lối đi trước, xác nhận nơi chuyển đến đã vệ sinh, khử trùng xong rồi mới di chuyển.","Hiểu quan hệ giữa di chuyển và phòng dịch, và có thể hướng dẫn người mới cách kiểm tra lối đi và độ sạch."],"name_id":"Memeriksa jalur dan kebersihan tempat tujuan","kanten_id":"Apakah dapat memeriksa lebih dulu jalur dari tangga, licin, dan penghalang, serta memastikan tempat tujuan sudah selesai dibersihkan dan didisinfeksi agar tidak membawa masuk pencemaran?","levels_id":["Tidak memeriksa jalur, dan memasukkan babi ke kandang kotor yang belum selesai dibersihkan dan didisinfeksi.","Melihat jalur jika diperintah, tetapi sering lalai memastikan kebersihan tempat tujuan.","Jika diperintah, dapat memeriksa bahaya di jalur secara lengkap.","Tanpa diperintah pun, memeriksa jalur lebih dulu, dan memastikan tempat tujuan selesai dibersihkan dan didisinfeksi sebelum memindahkan.","Memahami hubungan pemindahan dengan biosekuriti, dan dapat mengajarkan pemeriksaan jalur dan kebersihan tujuan kepada karyawan baru."]}],"gyomu":"10","name_en":"Movement Orders","purposeShort_en":"Keep the pig flow moving and move pigs safely without stress","name_vi":"Chỉ thị di chuyển","purposeShort_vi":"Không làm tắc luồng luân chuyển lợn (pig flow), di chuyển an toàn không gây stress cho lợn","name_id":"Instruksi pemindahan (memindahkan babi)","purposeShort_id":"Menjaga alur pemindahan babi (pig flow) tetap lancar, dan memindahkan babi dengan aman tanpa membuat stres"},{"id":"move-preg","category":"facility","no":"No.25","name":"妊娠舎→交配舎・育成舎 移動","purposeShort":"ピッグフローを守って次の舎へつなぐ","aspects":[{"id":"quiet-move","name":"静かな追い方と適期移動","kanten":"静かに追い無理に走らせず、分娩予定を踏まえた適期に移動できるか。","levels":["分娩予定より早く移動させ、妊娠後期の母豚を急かしてストレス・分娩事故を招く。","指示があれば移動させるが、追い方や時期の見極めに漏れがある。","指示があれば静かにひと通り移動できる。","指示がなくても静かに追い、分娩予定を踏まえた適期に無理なく移動する。","移動時期とストレスの関係を理解し、静かな移動と適期の判断を新人に指導できる。"],"name_en":"Quiet Driving and Timely Movement","kanten_en":"Can they drive sows quietly without forcing them to run, and move them at the right time based on the farrowing schedule?","levels_en":["Moves sows earlier than the farrowing schedule and rushes late-gestation sows, causing stress and farrowing accidents.","With guidance can move sows, but misses driving technique or timing judgment.","With guidance can complete a basic quiet move.","Independently drives sows quietly and moves them without strain at the right time based on the farrowing schedule.","Understands the relationship between movement timing and stress, and can teach new staff quiet movement and timing judgment."],"name_vi":"Lùa nhẹ nhàng và di chuyển đúng thời điểm","kanten_vi":"Có lùa nhẹ nhàng, không bắt lợn chạy, di chuyển đúng thời điểm dựa trên ngày dự sinh không.","levels_vi":["Di chuyển sớm hơn ngày dự sinh, hối thúc lợn nái cuối thai kỳ gây stress, tai nạn khi đẻ.","Nếu được chỉ thị thì di chuyển, nhưng còn thiếu sót về cách lùa và phán đoán thời điểm.","Nếu được chỉ thị thì di chuyển nhẹ nhàng được cơ bản.","Dù không có chỉ thị vẫn lùa nhẹ nhàng, di chuyển đúng thời điểm dựa trên ngày dự sinh, không ép lợn.","Hiểu quan hệ giữa thời điểm di chuyển và stress, và có thể hướng dẫn người mới cách di chuyển nhẹ nhàng và phán đoán thời điểm."],"name_id":"Menggiring dengan tenang dan memindah pada waktu yang tepat","kanten_id":"Apakah dapat menggiring dengan tenang tanpa memaksa babi berlari, dan memindah pada waktu yang tepat dengan mempertimbangkan perkiraan melahirkan?","levels_id":["Memindah lebih awal dari perkiraan melahirkan, memburu-buru induk babi bunting tua, sehingga menyebabkan stres dan kecelakaan melahirkan.","Memindah jika diperintah, tetapi sering lalai soal cara menggiring dan penilaian waktu.","Jika diperintah, dapat memindah dengan tenang secara lengkap.","Tanpa diperintah pun, menggiring dengan tenang dan memindah tanpa paksaan pada waktu yang tepat sesuai perkiraan melahirkan.","Memahami hubungan waktu pemindahan dengan stres, dan dapat mengajarkan cara memindah yang tenang dan penilaian waktu yang tepat kepada karyawan baru."]},{"id":"dest-check","name":"移動先の水・エサ・収容確認","kanten":"移動先の水・エサと収容スペースを事前に確認し、過密搬入を防げるか。","levels":["移動先の水・エサや収容スペースを確認せず、過密に搬入する。","指示があれば確認するが、収容スペースの確認に漏れがある。","指示があれば移動先の水・エサをひと通り確認できる。","指示がなくても移動先の水・エサと収容スペースを確かめ、過密を避ける。","過密搬入のリスクを理解し、移動先確認の要点を新人に指導できる。"],"name_en":"Checking Water, Feed, and Capacity at the Destination","kanten_en":"Can they check water, feed, and housing capacity at the destination in advance and prevent overcrowded moves?","levels_en":["Moves pigs in overcrowded without checking water, feed, or housing capacity at the destination.","With guidance can check, but misses the housing-capacity check.","With guidance can check water and feed at the destination through the basic procedure.","Independently checks water, feed, and housing capacity at the destination and avoids overcrowding.","Understands the risks of overcrowded moves, and can teach new staff the key points of destination checks."],"name_vi":"Kiểm tra nước, thức ăn, sức chứa của nơi chuyển đến","kanten_vi":"Có kiểm tra trước nước, thức ăn và diện tích chứa của nơi chuyển đến, tránh nhập lợn quá đông không.","levels_vi":["Không kiểm tra nước, thức ăn, diện tích chứa của nơi chuyển đến, nhập lợn quá đông.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót trong kiểm tra diện tích chứa.","Nếu được chỉ thị thì kiểm tra nước, thức ăn của nơi chuyển đến được cơ bản.","Dù không có chỉ thị vẫn kiểm tra nước, thức ăn, diện tích chứa của nơi chuyển đến, tránh quá đông.","Hiểu rủi ro nhập lợn quá đông, và có thể hướng dẫn người mới các điểm chính khi kiểm tra nơi chuyển đến."],"name_id":"Memeriksa air, pakan, dan daya tampung tempat tujuan","kanten_id":"Apakah dapat memeriksa lebih dulu air, pakan, dan ruang tampung di tempat tujuan, sehingga mencegah pemasukan yang terlalu padat?","levels_id":["Tidak memeriksa air, pakan, dan ruang tampung di tempat tujuan, dan memasukkan babi terlalu padat.","Memeriksa jika diperintah, tetapi sering lalai memeriksa ruang tampung.","Jika diperintah, dapat memeriksa air dan pakan di tempat tujuan secara lengkap.","Tanpa diperintah pun, memastikan air, pakan, dan ruang tampung tempat tujuan, dan menghindari kepadatan berlebih.","Memahami risiko pemasukan terlalu padat, dan dapat mengajarkan pokok pemeriksaan tempat tujuan kepada karyawan baru."]}],"gyomu":"25","name_en":"Gestation House to Breeding/Grower House Movement","purposeShort_en":"Keep the pig flow and connect sows to the next house","name_vi":"Di chuyển từ chuồng lợn nái mang thai → chuồng phối giống / chuồng hậu bị","purposeShort_vi":"Giữ đúng luồng luân chuyển lợn (pig flow), nối tiếp sang chuồng kế","name_id":"Pemindahan dari kandang bunting → kandang kawin / kandang babi pengganti","purposeShort_id":"Menyambungkan ke kandang berikutnya dengan menjaga alur pemindahan babi (pig flow)"},{"id":"scraper","category":"facility","no":"No.19","name":"スクレーパー動作確認","purposeShort":"除糞機能を正常に保ち、機械トラブルを早期発見して大故障を防ぐ","aspects":[{"id":"safety-power","name":"電源遮断など安全手順","kanten":"確認・清掃の前に必ず電源を切り、回転部・可動部に安全に触れられるか。","levels":["電源を切らずに点検・清掃し、回転部に触れて事故の危険を招く。","指示があれば電源を切るが、徹底が甘く危険な操作が残る。","指示があれば確認・清掃前に電源をひと通り切れる。","指示がなくても必ず電源を切ってから安全に点検・清掃する。","回転部の危険を理解し、電源遮断など安全手順を新人に指導できる。"],"name_en":"Safety Procedures Including Power Shutoff","kanten_en":"Can they always cut the power before inspection and cleaning and touch rotating and moving parts safely?","levels_en":["Inspects and cleans without cutting the power, touching rotating parts and risking accidents.","With guidance cuts the power, but the habit is weak and unsafe actions remain.","With guidance can cut the power before inspection and cleaning as a basic routine.","Independently always cuts the power before inspecting and cleaning safely.","Understands the dangers of rotating parts, and can teach new staff safety procedures including power shutoff."],"name_vi":"Quy trình an toàn như ngắt điện","kanten_vi":"Trước khi kiểm tra, vệ sinh có luôn ngắt điện, chạm vào bộ phận quay, bộ phận chuyển động một cách an toàn không.","levels_vi":["Không ngắt điện mà kiểm tra, vệ sinh, chạm vào bộ phận quay gây nguy cơ tai nạn.","Nếu được chỉ thị thì ngắt điện, nhưng chưa triệt để, vẫn còn thao tác nguy hiểm.","Nếu được chỉ thị thì ngắt điện trước khi kiểm tra, vệ sinh được cơ bản.","Dù không có chỉ thị vẫn luôn ngắt điện rồi mới kiểm tra, vệ sinh an toàn.","Hiểu nguy hiểm của bộ phận quay, và có thể hướng dẫn người mới quy trình an toàn như ngắt điện."],"name_id":"Prosedur keselamatan seperti mematikan listrik","kanten_id":"Apakah selalu mematikan listrik sebelum pemeriksaan dan pembersihan, sehingga aman saat menyentuh bagian yang berputar atau bergerak?","levels_id":["Memeriksa dan membersihkan tanpa mematikan listrik, menyentuh bagian berputar, dan menimbulkan bahaya kecelakaan.","Mematikan listrik jika diperintah, tetapi tidak konsisten sehingga masih ada tindakan berbahaya.","Jika diperintah, dapat mematikan listrik sebelum pemeriksaan dan pembersihan secara lengkap.","Tanpa diperintah pun, selalu mematikan listrik lebih dulu, lalu memeriksa dan membersihkan dengan aman.","Memahami bahaya bagian yang berputar, dan dapat mengajarkan prosedur keselamatan seperti mematikan listrik kepada karyawan baru."]},{"id":"wear-report","name":"異音・摩耗の点検と異常時の停止・報告","kanten":"異音・振動・チェーンやワイヤの摩耗を点検し、異常があれば無理に動かさず報告できるか。","levels":["定期確認をせず異音・動作不良や摩耗を見落とし、汚液滞留・断線を招く。","指示があれば点検するが、摩耗の見極めや異常時の対応に漏れがある。","指示があれば異音・振動やチェーンの摩耗をひと通り点検できる。","指示がなくても定期点検し、異常があれば無理に動かさず停止して報告する。","摩耗・断線のリスクを理解し、点検の着眼点と異常時対応を新人に指導できる。"],"name_en":"Inspecting for Noise and Wear, and Stopping and Reporting on Abnormality","kanten_en":"Can they inspect for abnormal noise, vibration, and wear of chains and wires, and stop and report instead of forcing operation when something is wrong?","levels_en":["Skips regular inspection, missing abnormal noise, malfunction, and wear, leading to slurry buildup and cable breaks.","With guidance can inspect, but misses judging wear or responding to abnormalities.","With guidance can inspect for abnormal noise, vibration, and chain wear through the basic routine.","Independently inspects regularly and, on any abnormality, stops the machine and reports instead of forcing it.","Understands the risks of wear and cable breaks, and can teach new staff inspection points and abnormality response."],"name_vi":"Kiểm tra tiếng lạ, mài mòn; dừng và báo cáo khi bất thường","kanten_vi":"Có kiểm tra tiếng lạ, rung, độ mài mòn của xích, dây cáp, khi có bất thường thì không cố chạy mà báo cáo không.","levels_vi":["Không kiểm tra định kỳ, bỏ sót tiếng lạ, hoạt động kém, mài mòn, gây ứ đọng nước bẩn, đứt dây.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót trong nhận biết mài mòn và xử lý khi bất thường.","Nếu được chỉ thị thì kiểm tra tiếng lạ, rung và độ mài mòn của xích được cơ bản.","Dù không có chỉ thị vẫn kiểm tra định kỳ, khi có bất thường thì không cố chạy mà dừng lại và báo cáo.","Hiểu rủi ro mài mòn, đứt dây, và có thể hướng dẫn người mới các điểm cần xem khi kiểm tra và cách xử lý bất thường."],"name_id":"Memeriksa bunyi aneh dan keausan, berhenti dan melapor saat tidak normal","kanten_id":"Apakah dapat memeriksa bunyi aneh, getaran, dan keausan rantai atau kawat, dan jika ada yang tidak normal tidak memaksakan jalan melainkan melapor?","levels_id":["Tidak memeriksa secara berkala, melewatkan bunyi aneh, gangguan kerja, dan keausan, sehingga cairan kotor menumpuk dan kawat putus.","Memeriksa jika diperintah, tetapi sering lalai menilai keausan dan menangani saat tidak normal.","Jika diperintah, dapat memeriksa bunyi aneh, getaran, dan keausan rantai secara lengkap.","Tanpa diperintah pun, memeriksa berkala, dan jika ada yang tidak normal menghentikan mesin tanpa memaksakan lalu melapor.","Memahami risiko keausan dan kawat putus, dan dapat mengajarkan titik pemeriksaan dan penanganan saat tidak normal kepada karyawan baru."]}],"gyomu":"19","name_en":"Manure Scraper Operation Check","purposeShort_en":"Keep manure removal working, detect mechanical trouble early, and prevent major breakdowns","name_vi":"Kiểm tra hoạt động máy cào phân","purposeShort_vi":"Giữ chức năng dọn phân hoạt động bình thường, phát hiện sớm trục trặc máy để tránh hỏng lớn","name_id":"Pemeriksaan kerja alat pengeruk kotoran","purposeShort_id":"Menjaga fungsi pembersihan kotoran tetap normal, menemukan gangguan mesin sejak dini, dan mencegah kerusakan besar"},{"id":"fan-clean","category":"facility","no":"No.29","name":"ファン清掃","purposeShort":"換気能力を保ち、呼吸器トラブル・暑熱ストレスを防ぎ設備を長持ちさせる","aspects":[{"id":"power-off","name":"電源遮断と安全な清掃","kanten":"作業前に必ず電源を切り、モーター・配線に水をかけずに清掃できるか。","levels":["電源を切らずに清掃して回転部に接触し、モーターや配線に水をかける危険な作業をする。","指示があれば電源を切るが、水かけ回避などの徹底が甘い。","指示があれば電源を切り、羽根・シャッター・ネットの汚れをひと通り落とせる。","指示がなくても電源を切り、モーターや配線を避けて安全に清掃する。","感電・巻き込みの危険を理解し、安全な清掃手順を新人に指導できる。"],"name_en":"Power Shutoff and Safe Cleaning","kanten_en":"Can they always cut the power before work and clean without splashing water on motors and wiring?","levels_en":["Cleans without cutting the power, contacting rotating parts, and works dangerously by splashing water on motors and wiring.","With guidance cuts the power, but is lax about avoiding water splashes and the like.","With guidance can cut the power and remove the dirt from blades, shutters, and nets through the basic routine.","Independently cuts the power and cleans safely while avoiding motors and wiring.","Understands the dangers of electric shock and entanglement, and can teach new staff safe cleaning procedures."],"name_vi":"Ngắt điện và vệ sinh an toàn","kanten_vi":"Trước khi làm có luôn ngắt điện, vệ sinh mà không xịt nước vào mô-tơ, dây điện không.","levels_vi":["Không ngắt điện mà vệ sinh, chạm vào bộ phận quay, làm việc nguy hiểm như xịt nước vào mô-tơ, dây điện.","Nếu được chỉ thị thì ngắt điện, nhưng chưa triệt để trong việc tránh xịt nước v.v.","Nếu được chỉ thị thì ngắt điện, làm sạch cánh quạt, cửa chớp, lưới được cơ bản.","Dù không có chỉ thị vẫn ngắt điện, tránh mô-tơ và dây điện, vệ sinh an toàn.","Hiểu nguy hiểm điện giật, bị cuốn kẹt, và có thể hướng dẫn người mới quy trình vệ sinh an toàn."],"name_id":"Mematikan listrik dan membersihkan dengan aman","kanten_id":"Apakah selalu mematikan listrik sebelum bekerja, dan membersihkan tanpa menyiram air ke motor dan kabel?","levels_id":["Membersihkan tanpa mematikan listrik hingga menyentuh bagian berputar, dan bekerja berbahaya dengan menyiram air ke motor dan kabel.","Mematikan listrik jika diperintah, tetapi tidak konsisten menghindari siraman air.","Jika diperintah, dapat mematikan listrik dan membersihkan kotoran pada baling-baling, penutup (shutter), dan jaring secara lengkap.","Tanpa diperintah pun, mematikan listrik dan membersihkan dengan aman sambil menghindari motor dan kabel.","Memahami bahaya tersengat listrik dan terlilit, dan dapat mengajarkan urutan pembersihan yang aman kepada karyawan baru."]},{"id":"belt-check","name":"ファンベルト・効率の点検","kanten":"埃の堆積やベルトの劣化を点検し、換気効率の低下や突然停止を防げるか。","levels":["埃の堆積やベルト劣化を確認せず、換気効率低下や突然停止を招く。","指示があれば清掃するが、ベルト劣化や効率低下の点検に漏れがある。","指示があれば埃を落とし、目に見える不具合をひと通り確認できる。","指示がなくてもベルトの劣化を点検し、換気効率の低下に早く気づく。","換気効率と暑熱死のリスクを理解し、ベルト・効率の点検を新人に指導できる。"],"name_en":"Inspecting Fan Belts and Efficiency","kanten_en":"Can they inspect for dust buildup and belt deterioration and prevent reduced ventilation efficiency and sudden stoppage?","levels_en":["Does not check dust buildup or belt deterioration, causing reduced ventilation efficiency and sudden stoppage.","With guidance can clean, but misses inspecting belt deterioration or efficiency loss.","With guidance can remove dust and check visible defects through the basic routine.","Independently inspects belt deterioration and notices reduced ventilation efficiency early.","Understands the risks of ventilation loss and heat-related deaths, and can teach new staff belt and efficiency inspection."],"name_vi":"Kiểm tra dây curoa quạt và hiệu suất","kanten_vi":"Có kiểm tra bụi bám và dây curoa xuống cấp, phòng giảm hiệu suất thông gió và dừng đột ngột không.","levels_vi":["Không kiểm tra bụi bám, dây curoa xuống cấp, gây giảm hiệu suất thông gió, dừng đột ngột.","Nếu được chỉ thị thì vệ sinh, nhưng còn thiếu sót trong kiểm tra dây curoa xuống cấp và hiệu suất giảm.","Nếu được chỉ thị thì làm sạch bụi và kiểm tra các hỏng hóc nhìn thấy được một cách cơ bản.","Dù không có chỉ thị vẫn kiểm tra dây curoa xuống cấp, sớm nhận ra hiệu suất thông gió giảm.","Hiểu rủi ro giữa hiệu suất thông gió và chết do nóng, và có thể hướng dẫn người mới cách kiểm tra dây curoa, hiệu suất."],"name_id":"Memeriksa sabuk (belt) kipas dan efisiensi","kanten_id":"Apakah dapat memeriksa tumpukan debu dan kerusakan sabuk (belt), sehingga mencegah turunnya efisiensi ventilasi dan berhenti mendadak?","levels_id":["Tidak memeriksa tumpukan debu dan kerusakan sabuk, sehingga efisiensi ventilasi turun dan kipas berhenti mendadak.","Membersihkan jika diperintah, tetapi sering lalai memeriksa kerusakan sabuk dan penurunan efisiensi.","Jika diperintah, dapat membersihkan debu dan memeriksa kerusakan yang terlihat secara lengkap.","Tanpa diperintah pun, memeriksa kerusakan sabuk dan cepat menyadari turunnya efisiensi ventilasi.","Memahami risiko efisiensi ventilasi terhadap kematian karena panas, dan dapat mengajarkan pemeriksaan sabuk dan efisiensi kepada karyawan baru."]}],"gyomu":"29","name_en":"Fan Cleaning","purposeShort_en":"Maintain ventilation capacity, prevent respiratory trouble and heat stress, and extend equipment life","name_vi":"Vệ sinh quạt","purposeShort_vi":"Duy trì năng lực thông gió, phòng bệnh hô hấp, stress do nóng và giúp thiết bị bền lâu","name_id":"Membersihkan kipas","purposeShort_id":"Menjaga kemampuan ventilasi, mencegah gangguan pernapasan dan stres panas, serta membuat peralatan awet"},{"id":"pad-tank","category":"facility","no":"No.30","name":"パドタンク清掃（夏季）","purposeShort":"クーリング性能を保ち、藻・細菌・悪臭を防ぎ設備を長持ちさせる","aspects":[{"id":"regular-clean","name":"定期清掃と藻・バイオフィルム防止","kanten":"月1回以上の清掃を守り、藻・バイオフィルムの発生を防げるか。作業前に電源を切り水を抜けるか。","levels":["清掃を怠って藻・バイオフィルムを発生させ、電源も切らずに作業する。","指示があれば清掃するが、頻度や電源遮断・排水の手順に漏れがある。","指示があれば電源を切り水を抜いて、やさしくひと通り清掃できる。","指示がなくても月1回以上清掃し、フィルターやポンプも一緒に確認する。","クーリング性能と衛生の関係を理解し、定期清掃の手順を新人に指導できる。"],"name_en":"Regular Cleaning and Preventing Algae and Biofilm","kanten_en":"Can they clean at least once a month to prevent algae and biofilm, and cut the power and drain the water before work?","levels_en":["Neglects cleaning, letting algae and biofilm develop, and works without cutting the power.","With guidance can clean, but misses the frequency or the power-shutoff and draining steps.","With guidance can cut the power, drain the water, and clean gently through the basic routine.","Independently cleans at least once a month and checks the filters and pump at the same time.","Understands the link between cooling performance and hygiene, and can teach new staff the regular cleaning procedure."],"name_vi":"Vệ sinh định kỳ và phòng rêu tảo, màng sinh học","kanten_vi":"Có giữ vệ sinh ít nhất 1 lần/tháng, phòng rêu tảo, màng sinh học (biofilm) phát sinh không. Trước khi làm có ngắt điện, xả nước không.","levels_vi":["Lười vệ sinh làm phát sinh rêu tảo, màng sinh học, làm việc mà không ngắt điện.","Nếu được chỉ thị thì vệ sinh, nhưng còn thiếu sót về tần suất và quy trình ngắt điện, xả nước.","Nếu được chỉ thị thì ngắt điện, xả nước và vệ sinh nhẹ nhàng được cơ bản.","Dù không có chỉ thị vẫn vệ sinh ít nhất 1 lần/tháng, kiểm tra luôn cả bộ lọc và máy bơm.","Hiểu quan hệ giữa hiệu quả làm mát và vệ sinh, và có thể hướng dẫn người mới quy trình vệ sinh định kỳ."],"name_id":"Pembersihan berkala dan pencegahan lumut serta biofilm","kanten_id":"Apakah menepati pembersihan minimal sebulan sekali sehingga mencegah lumut dan biofilm (lapisan lendir kuman)? Apakah sebelum bekerja mematikan listrik dan membuang airnya?","levels_id":["Lalai membersihkan sehingga lumut dan biofilm tumbuh, dan bekerja tanpa mematikan listrik.","Membersihkan jika diperintah, tetapi sering lalai soal frekuensi serta urutan mematikan listrik dan membuang air.","Jika diperintah, dapat mematikan listrik, membuang air, dan membersihkan dengan lembut secara lengkap.","Tanpa diperintah pun, membersihkan minimal sebulan sekali, dan memeriksa filter serta pompa sekaligus.","Memahami hubungan kemampuan pendinginan dengan kebersihan, dan dapat mengajarkan urutan pembersihan berkala kepada karyawan baru."]},{"id":"chlorine-temp","name":"残留塩素・水温・濃度の管理","kanten":"残留塩素・水温を確認して細菌増殖を防ぎ、塩素系消毒剤を高濃度にせず飲水量低下を招かないか。","levels":["残留塩素・水温を確認せず補充のみで細菌を増やし、消毒剤を高濃度にして飲水量を落とす。","指示があれば確認するが、濃度や水温の管理に漏れがある。","指示があれば残留塩素・水温をひと通り確認できる。","指示がなくても残留塩素・水温を確認し、消毒剤の濃度を適正に保つ。","細菌増殖と飲水量の関係を理解し、塩素・水温・濃度の管理を新人に指導できる。"],"name_en":"Managing Residual Chlorine, Water Temperature, and Concentration","kanten_en":"Can they check residual chlorine and water temperature to prevent bacterial growth, and avoid over-concentrating chlorine disinfectant so water intake does not drop?","levels_en":["Only refills without checking residual chlorine or water temperature, letting bacteria grow, and over-concentrates disinfectant, reducing water intake.","With guidance can check, but misses concentration or water-temperature management.","With guidance can check residual chlorine and water temperature through the basic routine.","Independently checks residual chlorine and water temperature and keeps disinfectant concentration appropriate.","Understands the relationship between bacterial growth and water intake, and can teach new staff chlorine, temperature, and concentration management."],"name_vi":"Quản lý clo dư, nhiệt độ nước và nồng độ","kanten_vi":"Có kiểm tra clo dư, nhiệt độ nước để phòng vi khuẩn sinh sôi, không pha thuốc khử trùng gốc clo quá đậm gây giảm lượng nước uống không.","levels_vi":["Không kiểm tra clo dư, nhiệt độ nước, chỉ châm thêm nước làm vi khuẩn sinh sôi, pha thuốc khử trùng quá đậm làm giảm lượng nước uống.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót trong quản lý nồng độ và nhiệt độ nước.","Nếu được chỉ thị thì kiểm tra clo dư, nhiệt độ nước được cơ bản.","Dù không có chỉ thị vẫn kiểm tra clo dư, nhiệt độ nước, giữ nồng độ thuốc khử trùng phù hợp.","Hiểu quan hệ giữa vi khuẩn sinh sôi và lượng nước uống, và có thể hướng dẫn người mới cách quản lý clo, nhiệt độ nước, nồng độ."],"name_id":"Mengelola sisa klorin, suhu air, dan kepekatan","kanten_id":"Apakah memeriksa sisa klorin dan suhu air untuk mencegah bakteri berkembang, dan tidak membuat disinfektan klorin terlalu pekat sehingga babi jadi kurang minum?","levels_id":["Hanya menambah air tanpa memeriksa sisa klorin dan suhu air sehingga bakteri berkembang, dan membuat disinfektan terlalu pekat sehingga babi kurang minum.","Memeriksa jika diperintah, tetapi sering lalai mengelola kepekatan dan suhu air.","Jika diperintah, dapat memeriksa sisa klorin dan suhu air secara lengkap.","Tanpa diperintah pun, memeriksa sisa klorin dan suhu air, dan menjaga kepekatan disinfektan tetap tepat.","Memahami hubungan perkembangan bakteri dengan jumlah air minum, dan dapat mengajarkan pengelolaan klorin, suhu air, dan kepekatan kepada karyawan baru."]}],"gyomu":"30","name_en":"Pad Tank Cleaning (Summer)","purposeShort_en":"Maintain cooling performance, prevent algae, bacteria, and odor, and extend equipment life","name_vi":"Vệ sinh bể nước của tấm làm mát (pad tank) — mùa hè","purposeShort_vi":"Duy trì hiệu quả làm mát, phòng rêu tảo, vi khuẩn, mùi hôi và giúp thiết bị bền lâu","name_id":"Membersihkan tangki air panel pendingin (pad tank) — musim panas","purposeShort_id":"Menjaga kemampuan pendinginan, mencegah lumut, bakteri, dan bau busuk, serta membuat peralatan awet"},{"id":"feed-switch","category":"facility","no":"No.20","name":"エサスイッチ","purposeShort":"給餌を安定させ、ムダな飼料を減らし機械トラブルを防ぐ","aspects":[{"id":"switch-position","name":"スイッチ位置と異常時の停止","kanten":"自動・手動・切の位置を確認し、ホッパー空・詰まり・異音時はすぐオフにできるか。","levels":["スイッチ位置を確認せず、ホッパー空や詰まり・異音があってもオフにしない。","指示があれば位置を確認するが、異常時の停止対応に漏れがある。","指示があれば自動・手動・切の位置をひと通り確認できる。","指示がなくても位置を確認し、ホッパー空・詰まり・異音時はすぐオフにする。","給餌設備のトラブルを理解し、スイッチ操作と異常時対応を新人に指導できる。"],"name_en":"Switch Position and Stopping on Abnormality","kanten_en":"Can they confirm the auto/manual/off position and switch off immediately when the hopper is empty, clogged, or making abnormal noise?","levels_en":["Does not confirm the switch position and does not switch off even when the hopper is empty, clogged, or making abnormal noise.","With guidance can confirm the position, but misses stopping the machine on abnormality.","With guidance can confirm the auto/manual/off position through the basic routine.","Independently confirms the position and switches off immediately on an empty hopper, clogging, or abnormal noise.","Understands feeding-equipment troubles, and can teach new staff switch operation and abnormality response."],"name_vi":"Vị trí công tắc và dừng khi bất thường","kanten_vi":"Có kiểm tra vị trí tự động / bằng tay / tắt, khi phễu chứa cám rỗng, bị tắc hoặc có tiếng lạ thì tắt ngay không.","levels_vi":["Không kiểm tra vị trí công tắc, phễu rỗng, bị tắc hay có tiếng lạ cũng không tắt.","Nếu được chỉ thị thì kiểm tra vị trí, nhưng còn thiếu sót trong xử lý dừng khi bất thường.","Nếu được chỉ thị thì kiểm tra vị trí tự động / bằng tay / tắt được cơ bản.","Dù không có chỉ thị vẫn kiểm tra vị trí, khi phễu rỗng, bị tắc, có tiếng lạ thì tắt ngay.","Hiểu các trục trặc của thiết bị cho ăn, và có thể hướng dẫn người mới cách thao tác công tắc và xử lý khi bất thường."],"name_id":"Posisi sakelar dan mematikan saat tidak normal","kanten_id":"Apakah memeriksa posisi otomatis / manual / mati, dan segera mematikan saat corong pakan (hopper) kosong, tersumbat, atau berbunyi aneh?","levels_id":["Tidak memeriksa posisi sakelar, dan tidak mematikan walaupun corong pakan kosong, tersumbat, atau berbunyi aneh.","Memeriksa posisi jika diperintah, tetapi sering lalai mematikan saat tidak normal.","Jika diperintah, dapat memeriksa posisi otomatis / manual / mati secara lengkap.","Tanpa diperintah pun, memeriksa posisi, dan segera mematikan saat corong pakan kosong, tersumbat, atau berbunyi aneh.","Memahami gangguan pada peralatan pemberian pakan, dan dapat mengajarkan pengoperasian sakelar dan penanganan saat tidak normal kepada karyawan baru."]},{"id":"timer-record","name":"タイマー変更後の動作確認と記録","kanten":"設定変更は決められた人が行い、タイマー変更後は動作確認し、切り替え日を記録できるか。","levels":["権限のない者が設定を変え、変更後の動作確認もせず切り替え日も記録しない。","指示があれば確認するが、動作確認や記録に漏れがある。","指示があればタイマー変更後の動作をひと通り確認できる。","指示がなくても変更後に動作を確認し、切り替え日を記録して二重切り替えを防ぐ。","設定変更と給餌事故の関係を理解し、動作確認と記録の徹底を新人に指導できる。"],"name_en":"Operation Check and Recording After Timer Changes","kanten_en":"Can they leave setting changes to designated staff, verify operation after timer changes, and record the changeover date?","levels_en":["Unauthorized staff change the settings, with no operation check afterward and no record of the changeover date.","With guidance can check, but misses the operation check or the record.","With guidance can verify operation after a timer change through the basic routine.","Independently verifies operation after changes and records the changeover date to prevent double changeovers.","Understands how setting changes relate to feeding accidents, and can teach new staff thorough operation checks and recording."],"name_vi":"Kiểm tra hoạt động sau khi đổi hẹn giờ và ghi chép","kanten_vi":"Việc đổi cài đặt có do người được quy định làm, sau khi đổi hẹn giờ có kiểm tra hoạt động và ghi lại ngày chuyển đổi không.","levels_vi":["Người không có quyền đổi cài đặt, sau khi đổi không kiểm tra hoạt động, cũng không ghi ngày chuyển đổi.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về kiểm tra hoạt động và ghi chép.","Nếu được chỉ thị thì kiểm tra hoạt động sau khi đổi hẹn giờ được cơ bản.","Dù không có chỉ thị vẫn kiểm tra hoạt động sau khi đổi, ghi ngày chuyển đổi để tránh chuyển đổi hai lần.","Hiểu quan hệ giữa đổi cài đặt và sự cố cho ăn, và có thể hướng dẫn người mới việc kiểm tra hoạt động và ghi chép triệt để."],"name_id":"Memeriksa kerja setelah mengubah timer dan mencatatnya","kanten_id":"Apakah perubahan pengaturan hanya dilakukan orang yang ditunjuk, kerja mesin diperiksa setelah timer diubah, dan tanggal penggantian dicatat?","levels_id":["Orang tanpa wewenang mengubah pengaturan, tidak memeriksa kerja mesin setelah diubah, dan tidak mencatat tanggal penggantian.","Memeriksa jika diperintah, tetapi sering lalai memeriksa kerja mesin dan mencatat.","Jika diperintah, dapat memeriksa kerja mesin setelah timer diubah secara lengkap.","Tanpa diperintah pun, memeriksa kerja mesin setelah perubahan, dan mencatat tanggal penggantian untuk mencegah penggantian ganda.","Memahami hubungan perubahan pengaturan dengan kecelakaan pemberian pakan, dan dapat mengajarkan pemeriksaan kerja mesin dan pencatatan kepada karyawan baru."]}],"gyomu":"20","name_en":"Feed Switch","purposeShort_en":"Keep feeding stable, reduce feed waste, and prevent mechanical trouble","name_vi":"Công tắc cấp cám","purposeShort_vi":"Giữ việc cho ăn ổn định, giảm lãng phí thức ăn và phòng trục trặc máy","name_id":"Sakelar pakan (pengoperasian pemberian pakan otomatis)","purposeShort_id":"Menstabilkan pemberian pakan, mengurangi pakan terbuang, dan mencegah gangguan mesin"},{"id":"daily-report","category":"record","no":"No.05","name":"日報記入","purposeShort":"豚の状態を記録して病気を早期発見し、成績を数字で残し改善に役立てる","aspects":[{"id":"accurate-timely","name":"その場での正確な記録","kanten":"記憶頼りのまとめ書きを避け、その場で事実と数字を正確に記録できるか。","levels":["記憶頼りで後からまとめ書きし、数値の単位ズレなど不正確な記録をする。","指示があれば記録するが、まとめ書きや単位ズレが多い。","指示があればその場で事実と数字をひと通り正確に記録できる。","指示がなくてもその場で正確に記録し、単位や数値を確かめる。","記録の正確さが早期発見・改善に不可欠と理解し、正確な記入を新人に指導できる。"],"name_en":"Accurate On-the-Spot Recording","kanten_en":"Can they avoid batch-writing from memory and record facts and figures accurately on the spot?","levels_en":["Batch-writes later from memory and makes inaccurate records such as unit mismatches in figures.","With guidance can record, but often batch-writes and mismatches units.","With guidance can record facts and figures accurately on the spot through the basic routine.","Independently records accurately on the spot and double-checks units and figures.","Understands that accurate records are essential to early detection and improvement, and can teach new staff accurate entry."],"name_vi":"Ghi chính xác ngay tại chỗ","kanten_vi":"Có tránh ghi gộp sau bằng trí nhớ, ghi sự việc và con số chính xác ngay tại chỗ không.","levels_vi":["Dựa vào trí nhớ, ghi gộp sau, ghi không chính xác như lệch đơn vị của số liệu.","Nếu được chỉ thị thì ghi, nhưng hay ghi gộp và lệch đơn vị.","Nếu được chỉ thị thì ghi sự việc, con số chính xác ngay tại chỗ được cơ bản.","Dù không có chỉ thị vẫn ghi chính xác ngay tại chỗ, kiểm tra lại đơn vị và con số.","Hiểu tính chính xác của ghi chép là không thể thiếu cho phát hiện sớm và cải thiện, và có thể hướng dẫn người mới cách ghi chính xác."],"name_id":"Mencatat dengan tepat di tempat","kanten_id":"Apakah menghindari menulis rangkuman dari ingatan, dan dapat mencatat fakta dan angka dengan tepat di tempat kerja?","levels_id":["Menulis rangkuman belakangan dari ingatan, dan membuat catatan tidak tepat seperti satuan angka yang keliru.","Mencatat jika diperintah, tetapi sering menulis rangkuman belakangan dan salah satuan.","Jika diperintah, dapat mencatat fakta dan angka dengan tepat di tempat secara lengkap.","Tanpa diperintah pun, mencatat dengan tepat di tempat, dan memastikan satuan dan angkanya.","Memahami bahwa ketepatan catatan penting untuk penemuan dini dan perbaikan, dan dapat mengajarkan pengisian yang tepat kepada karyawan baru."]},{"id":"shared-rule-use","name":"共通ルールでの記入と活用","kanten":"全員が同じルールで書き、書くだけで終わらせず見返して活用できるか。治療豚情報を漏らさないか。","levels":["自己流で書き、治療豚の薬剤名・投与量・開始日を記入せず休薬管理を抜けさせる。","指示があれば共通ルールで書くが、活用や治療豚情報の記入に漏れがある。","指示があれば共通ルールに沿ってひと通り記入できる。","指示がなくても共通ルールで書き、治療豚情報を漏らさず、記録を見返して活用する。","記録の共有と活用の意義を理解し、共通ルールと活用方法を新人に指導できる。"],"name_en":"Writing by Shared Rules and Putting Records to Use","kanten_en":"Can everyone write by the same rules, review and use the records rather than just writing them, and never omit treated-pig information?","levels_en":["Writes in a personal style and omits drug names, doses, and start dates for treated pigs, breaking withdrawal management.","With guidance writes by shared rules, but misses using the records or entering treated-pig information.","With guidance can complete entries following the shared rules.","Independently writes by shared rules, never omits treated-pig information, and reviews and uses the records.","Understands the value of sharing and using records, and can teach new staff the shared rules and how to use records."],"name_vi":"Ghi theo quy tắc chung và sử dụng ghi chép","kanten_vi":"Mọi người có ghi theo cùng một quy tắc, không chỉ ghi mà còn xem lại để sử dụng không. Có bỏ sót thông tin lợn đang điều trị không.","levels_vi":["Ghi theo kiểu riêng, không ghi tên thuốc, liều lượng, ngày bắt đầu của lợn điều trị, làm hổng quản lý thời gian ngừng thuốc.","Nếu được chỉ thị thì ghi theo quy tắc chung, nhưng còn thiếu sót về sử dụng và ghi thông tin lợn điều trị.","Nếu được chỉ thị thì ghi theo quy tắc chung được cơ bản.","Dù không có chỉ thị vẫn ghi theo quy tắc chung, không bỏ sót thông tin lợn điều trị, xem lại và sử dụng ghi chép.","Hiểu ý nghĩa của việc chia sẻ và sử dụng ghi chép, và có thể hướng dẫn người mới quy tắc chung và cách sử dụng."],"name_id":"Mengisi dengan aturan bersama dan memanfaatkannya","kanten_id":"Apakah semua orang menulis dengan aturan yang sama, tidak berhenti pada sekadar menulis tetapi membacanya kembali dan memanfaatkannya? Apakah data babi yang diobati tidak terlewat?","levels_id":["Menulis dengan gaya sendiri, tidak mengisi nama obat, dosis, dan tanggal mulai untuk babi yang diobati, sehingga pengelolaan masa henti obat bolong.","Menulis dengan aturan bersama jika diperintah, tetapi sering lalai memanfaatkan dan mengisi data babi yang diobati.","Jika diperintah, dapat mengisi sesuai aturan bersama secara lengkap.","Tanpa diperintah pun, menulis dengan aturan bersama, tidak melewatkan data babi yang diobati, dan membaca kembali catatan untuk dimanfaatkan.","Memahami arti berbagi dan memanfaatkan catatan, dan dapat mengajarkan aturan bersama dan cara memanfaatkannya kepada karyawan baru."]}],"gyomu":"05","name_en":"Daily Report Entry","purposeShort_en":"Record pig conditions for early disease detection and keep performance in numbers for improvement","name_vi":"Ghi nhật ký công việc","purposeShort_vi":"Ghi lại tình trạng lợn để phát hiện bệnh sớm, lưu thành tích bằng con số để phục vụ cải thiện","name_id":"Mengisi laporan harian","purposeShort_id":"Mencatat keadaan babi untuk menemukan penyakit sejak dini, dan menyimpan hasil kerja dalam angka untuk perbaikan"},{"id":"plate","category":"record","no":"No.07","name":"プレート作成","purposeShort":"個体・群をすぐ見分けられるようにし、ワクチン・治療・休薬中を示す","aspects":[{"id":"update","name":"最新状態への更新と旧プレート処理","kanten":"情報を最新に保ち、分娩後の作成忘れや、差し替え時の古いプレートの残存を防げるか。","levels":["分娩後に作成し忘れ、差し替え時も古いプレートを廃棄せず誤情報を残す。","指示があれば更新するが、作成忘れや旧プレート処理に漏れがある。","指示があれば情報をひと通り最新に更新できる。","指示がなくても分娩後すぐ作成し、差し替え時は古いプレートを確実に廃棄する。","情報の鮮度が個体管理に直結すると理解し、更新と旧プレート処理を新人に指導できる。"],"name_en":"Keeping Plates Current and Disposing of Old Ones","kanten_en":"Can they keep information current, avoiding missed plate creation after farrowing and old plates left behind after replacement?","levels_en":["Forgets to create plates after farrowing and leaves old plates undiscarded at replacement, keeping wrong information posted.","With guidance can update, but misses plate creation or old-plate disposal.","With guidance can update information to the current state through the basic routine.","Independently creates plates right after farrowing and reliably discards old plates at replacement.","Understands that information freshness directly affects individual management, and can teach new staff updating and old-plate disposal."],"name_vi":"Cập nhật trạng thái mới nhất và xử lý thẻ cũ","kanten_vi":"Có giữ thông tin luôn mới nhất, tránh quên làm thẻ sau khi đẻ, tránh để sót thẻ cũ khi thay thẻ không.","levels_vi":["Quên làm thẻ sau khi đẻ, khi thay cũng không bỏ thẻ cũ, để lại thông tin sai.","Nếu được chỉ thị thì cập nhật, nhưng còn thiếu sót về quên làm thẻ và xử lý thẻ cũ.","Nếu được chỉ thị thì cập nhật thông tin lên mới nhất được cơ bản.","Dù không có chỉ thị vẫn làm thẻ ngay sau khi đẻ, khi thay thì bỏ chắc chắn thẻ cũ.","Hiểu độ mới của thông tin liên quan trực tiếp đến quản lý cá thể, và có thể hướng dẫn người mới việc cập nhật và xử lý thẻ cũ."],"name_id":"Memperbarui ke keadaan terkini dan membuang kartu lama","kanten_id":"Apakah dapat menjaga informasi tetap terkini, tidak lupa membuat kartu setelah melahirkan, dan tidak membiarkan kartu lama tertinggal saat penggantian?","levels_id":["Lupa membuat kartu setelah melahirkan, dan saat penggantian tidak membuang kartu lama sehingga informasi salah tertinggal.","Memperbarui jika diperintah, tetapi sering lupa membuat dan lalai menangani kartu lama.","Jika diperintah, dapat memperbarui informasi ke keadaan terkini secara lengkap.","Tanpa diperintah pun, segera membuat setelah melahirkan, dan saat penggantian pasti membuang kartu lama.","Memahami bahwa kesegaran informasi langsung memengaruhi pengelolaan individu, dan dapat mengajarkan pembaruan dan penanganan kartu lama kepada karyawan baru."]},{"id":"readable","name":"誰にでも分かる表記・帳票一致","kanten":"誰が見ても分かる表記・色分けにし、日報や帳票の内容と一致させられるか。","levels":["担当者ごとに書式が異なり、後任者が判読できず帳票とも食い違う。","指示があれば書くが、表記の統一や帳票一致に漏れがある。","指示があれば分かる表記・色分けでひと通り作成できる。","指示がなくても誰でも分かる統一表記にし、日報・帳票と一致させる。","表記統一の意義を理解し、分かりやすいプレート作成を新人に指導できる。"],"name_en":"Notation Anyone Can Read and Consistency with Records","kanten_en":"Can they use notation and color coding anyone can understand, kept consistent with daily reports and ledgers?","levels_en":["Uses formats that differ by person, so successors cannot read the plates and they contradict the ledgers.","With guidance can write plates, but misses unified notation or consistency with ledgers.","With guidance can create plates with understandable notation and color coding through the basic routine.","Independently uses unified notation anyone can read and keeps plates consistent with daily reports and ledgers.","Understands the value of unified notation, and can teach new staff how to make clear plates."],"name_vi":"Cách ghi ai cũng hiểu, khớp với sổ sách","kanten_vi":"Có ghi và phân màu sao cho ai nhìn cũng hiểu, khớp với nội dung nhật ký công việc và sổ sách không.","levels_vi":["Mỗi người ghi một kiểu, người kế nhiệm không đọc được, lệch cả với sổ sách.","Nếu được chỉ thị thì ghi, nhưng còn thiếu sót về thống nhất cách ghi và khớp sổ sách.","Nếu được chỉ thị thì làm thẻ với cách ghi, phân màu dễ hiểu được cơ bản.","Dù không có chỉ thị vẫn ghi thống nhất ai cũng hiểu, khớp với nhật ký công việc, sổ sách.","Hiểu ý nghĩa của việc thống nhất cách ghi, và có thể hướng dẫn người mới cách làm thẻ dễ hiểu."],"name_id":"Penulisan yang dimengerti siapa pun dan cocok dengan buku catatan","kanten_id":"Apakah dapat menulis dengan cara dan warna yang dimengerti siapa pun, dan mencocokkannya dengan isi laporan harian dan buku catatan?","levels_id":["Format tulisan berbeda tiap petugas, tidak terbaca oleh pengganti, dan tidak cocok dengan buku catatan.","Menulis jika diperintah, tetapi sering lalai menyeragamkan penulisan dan mencocokkan dengan buku catatan.","Jika diperintah, dapat membuat dengan penulisan dan pewarnaan yang dimengerti secara lengkap.","Tanpa diperintah pun, menulis dengan format seragam yang dimengerti siapa pun, dan mencocokkannya dengan laporan harian dan buku catatan.","Memahami arti keseragaman penulisan, dan dapat mengajarkan pembuatan kartu yang mudah dimengerti kepada karyawan baru."]}],"gyomu":"07","name_en":"Plate Preparation","purposeShort_en":"Make individuals and groups instantly identifiable and show vaccination, treatment, and withdrawal status","name_vi":"Làm thẻ thông tin (plate)","purposeShort_vi":"Giúp nhận biết ngay từng con, từng nhóm; hiển thị vắc-xin, điều trị, đang ngừng thuốc","name_id":"Membuat kartu data (plate)","purposeShort_id":"Membuat individu dan kelompok mudah dikenali dengan cepat, serta menandai babi yang divaksin, diobati, atau dalam masa henti obat"},{"id":"tagging","category":"record","no":"No.21","name":"タグ付け","purposeShort":"1頭ずつ確実に見分け、健康・繁殖・治療・出荷を一貫管理し追跡可能にする","aspects":[{"id":"position-asepsis","name":"正しい位置と装着前消毒","kanten":"決められた位置・向きに正しく付け、装着前に器具と耳を消毒できるか。","levels":["装着位置・向きが不統一で読み取りにくく、器具・耳の消毒もしない。","指示があれば付けるが、位置の統一や消毒に漏れがある。","指示があれば決められた位置に、消毒してひと通り装着できる。","指示がなくても位置・向きを統一し、装着前に器具と耳を消毒する。","読み取りやすさと感染防止を理解し、正しい装着と消毒を新人に指導できる。"],"name_en":"Correct Position and Pre-Attachment Disinfection","kanten_en":"Can they attach tags correctly in the designated position and orientation, and disinfect the applicator and the ear before attachment?","levels_en":["Attaches tags in inconsistent positions and orientations that are hard to read, and skips disinfecting the applicator and the ear.","With guidance can attach tags, but misses position consistency or disinfection.","With guidance can disinfect and attach tags in the designated position through the basic routine.","Independently keeps position and orientation consistent and disinfects the applicator and the ear before attachment.","Understands readability and infection prevention, and can teach new staff correct attachment and disinfection."],"name_vi":"Vị trí đúng và khử trùng trước khi gắn","kanten_vi":"Có gắn đúng vị trí, đúng chiều quy định, khử trùng dụng cụ và tai trước khi gắn không.","levels_vi":["Vị trí, chiều gắn không thống nhất, khó đọc, cũng không khử trùng dụng cụ và tai.","Nếu được chỉ thị thì gắn, nhưng còn thiếu sót về thống nhất vị trí và khử trùng.","Nếu được chỉ thị thì khử trùng và gắn vào đúng vị trí quy định được cơ bản.","Dù không có chỉ thị vẫn thống nhất vị trí, chiều gắn, khử trùng dụng cụ và tai trước khi gắn.","Hiểu tính dễ đọc và việc phòng nhiễm trùng, và có thể hướng dẫn người mới cách gắn đúng và khử trùng."],"name_id":"Posisi yang benar dan disinfeksi sebelum pemasangan","kanten_id":"Apakah dapat memasang dengan benar pada posisi dan arah yang ditentukan, serta mendisinfeksi alat dan telinga sebelum pemasangan?","levels_id":["Posisi dan arah pemasangan tidak seragam sehingga sulit dibaca, dan tidak mendisinfeksi alat dan telinga.","Memasang jika diperintah, tetapi sering lalai menyeragamkan posisi dan mendisinfeksi.","Jika diperintah, dapat memasang pada posisi yang ditentukan dengan disinfeksi secara lengkap.","Tanpa diperintah pun, menyeragamkan posisi dan arah, serta mendisinfeksi alat dan telinga sebelum pemasangan.","Memahami kemudahan pembacaan dan pencegahan infeksi, dan dapat mengajarkan pemasangan yang benar dan disinfeksi kepada karyawan baru."]},{"id":"reattach","name":"脱落・破損時の再装着","kanten":"脱落・破損を見つけ次第付け直し、個体不明のまま管理を続けないか。","levels":["タグ付け忘れや脱落後の再装着をせず、個体不明のまま出荷しトレーサビリティを断つ。","指示があれば付け直すが、脱落の発見や再装着に漏れがある。","指示があれば脱落・破損をひと通り付け直せる。","指示がなくても脱落・破損を見つけ次第付け直し、個体不明を作らない。","トレーサビリティの重要性を理解し、脱落時の再装着徹底を新人に指導できる。"],"name_en":"Reattachment After Loss or Damage","kanten_en":"Can they reattach tags as soon as loss or damage is found, and never continue managing unidentified pigs?","levels_en":["Skips tagging or reattachment after loss, ships unidentified pigs, and breaks traceability.","With guidance can reattach, but misses spotting losses or reattaching.","With guidance can reattach lost or damaged tags through the basic routine.","Independently reattaches tags as soon as loss or damage is found and never leaves pigs unidentified.","Understands the importance of traceability, and can teach new staff thorough reattachment after tag loss."],"name_vi":"Gắn lại khi thẻ rơi, hỏng","kanten_vi":"Phát hiện thẻ rơi, hỏng có gắn lại ngay, không tiếp tục quản lý khi không rõ cá thể không.","levels_vi":["Quên gắn thẻ, thẻ rơi cũng không gắn lại, xuất chuồng khi không rõ cá thể, làm đứt truy xuất nguồn gốc.","Nếu được chỉ thị thì gắn lại, nhưng còn thiếu sót trong phát hiện thẻ rơi và gắn lại.","Nếu được chỉ thị thì gắn lại thẻ rơi, hỏng được cơ bản.","Dù không có chỉ thị vẫn phát hiện thẻ rơi, hỏng là gắn lại ngay, không để xảy ra con không rõ cá thể.","Hiểu tầm quan trọng của truy xuất nguồn gốc, và có thể hướng dẫn người mới việc gắn lại triệt để khi thẻ rơi."],"name_id":"Memasang ulang saat lepas atau rusak","kanten_id":"Apakah memasang ulang begitu menemukan tanda telinga yang lepas atau rusak, dan tidak melanjutkan pengelolaan dengan individu yang tidak dikenal?","levels_id":["Lupa memasang tanda telinga dan tidak memasang ulang setelah lepas, mengirim babi tanpa identitas, sehingga memutus ketertelusuran (traceability).","Memasang ulang jika diperintah, tetapi sering lalai menemukan yang lepas dan memasang ulang.","Jika diperintah, dapat memasang ulang yang lepas atau rusak secara lengkap.","Tanpa diperintah pun, memasang ulang begitu menemukan yang lepas atau rusak, dan tidak membiarkan ada individu tanpa identitas.","Memahami pentingnya ketertelusuran (traceability), dan dapat mengajarkan kedisiplinan memasang ulang saat lepas kepada karyawan baru."]}],"gyomu":"21","name_en":"Tagging","purposeShort_en":"Identify each pig reliably for consistent health, breeding, treatment, and shipping management and traceability","name_vi":"Gắn thẻ tai","purposeShort_vi":"Nhận biết chắc chắn từng con, quản lý nhất quán sức khỏe, sinh sản, điều trị, xuất chuồng và truy xuất được nguồn gốc","name_id":"Pemasangan tanda telinga (tag nomor)","purposeShort_id":"Mengenali setiap ekor dengan pasti, mengelola kesehatan, reproduksi, pengobatan, dan pengiriman secara terpadu, serta membuatnya dapat ditelusuri"},{"id":"farrow-schedule","category":"record","no":"No.32","name":"分娩予定記入","purposeShort":"分娩時期を把握して舎・人手を計画的に準備し、不受胎を早期発見する","aspects":[{"id":"calc","name":"妊娠日齢の統一計算","kanten":"妊娠日齢の数え方を統一し、交配日から114〜115日後を正確に計算できるか。","levels":["交配日の記録が抜け、日齢の数え方も不統一で分娩予定を計算できない。","指示があれば計算するが、数え方の統一や幅の考慮に漏れがある。","指示があれば交配日から予定日をひと通り計算できる。","指示がなくても統一した数え方で114〜115日後を正確に計算する。","計算のズレが準備に与える影響を理解し、統一した数え方を新人に指導できる。"],"name_en":"Standardized Gestation-Day Calculation","kanten_en":"Can they use a standardized way of counting gestation days and accurately calculate 114-115 days from the mating date?","levels_en":["Mating dates go unrecorded and day counting is inconsistent, so due dates cannot be calculated.","With guidance can calculate, but misses the standardized counting or the allowance for the range.","With guidance can calculate the due date from the mating date through the basic procedure.","Independently calculates 114-115 days accurately using the standardized counting.","Understands how calculation errors affect preparation, and can teach new staff the standardized counting."],"name_vi":"Tính ngày tuổi thai theo cách thống nhất","kanten_vi":"Có thống nhất cách đếm ngày tuổi thai, tính đúng 114-115 ngày sau ngày giao phối không.","levels_vi":["Thiếu ghi chép ngày giao phối, cách đếm cũng không thống nhất nên không tính được ngày dự sinh.","Nếu được chỉ thị thì tính, nhưng còn thiếu sót về thống nhất cách đếm và xét khoảng dao động.","Nếu được chỉ thị thì tính được ngày dự sinh từ ngày giao phối một cách cơ bản.","Dù không có chỉ thị vẫn tính đúng 114-115 ngày sau bằng cách đếm thống nhất.","Hiểu ảnh hưởng của việc tính lệch đến khâu chuẩn bị, và có thể hướng dẫn người mới cách đếm thống nhất."],"name_id":"Menghitung umur kebuntingan dengan cara yang seragam","kanten_id":"Apakah cara menghitung umur kebuntingan diseragamkan, dan dapat menghitung dengan tepat 114-115 hari setelah tanggal kawin?","levels_id":["Catatan tanggal kawin bolong dan cara menghitung tidak seragam, sehingga perkiraan melahirkan tidak dapat dihitung.","Menghitung jika diperintah, tetapi sering lalai menyeragamkan cara hitung dan mempertimbangkan rentangnya.","Jika diperintah, dapat menghitung tanggal perkiraan dari tanggal kawin secara lengkap.","Tanpa diperintah pun, menghitung 114-115 hari setelah kawin dengan tepat memakai cara hitung yang seragam.","Memahami pengaruh selisih hitungan terhadap persiapan, dan dapat mengajarkan cara hitung yang seragam kepada karyawan baru."]},{"id":"rewrite","name":"再交配時の書き直しと母豚観察","kanten":"交配・再交配のたびに書き直し、予定日だけで判断せず母豚の様子も確認できるか。","levels":["再交配時に修正記入を忘れ、予定日だけで判断して母豚の様子を見ない。","指示があれば書き直すが、修正漏れや観察不足がある。","指示があれば交配・再交配のたびにひと通り書き直せる。","指示がなくても再交配時に必ず書き直し、母豚の様子も合わせて確認する。","書き直し漏れがスケジュール混乱を招くと理解し、記入と観察の徹底を新人に指導できる。"],"name_en":"Rewriting on Rebreeding and Observing the Sow","kanten_en":"Can they rewrite the entry at every mating and rebreeding, and check the sow's condition instead of judging by the due date alone?","levels_en":["Forgets to correct entries on rebreeding and judges by the due date alone without watching the sow.","With guidance can rewrite, but has missed corrections and insufficient observation.","With guidance can rewrite the entry at every mating and rebreeding through the basic routine.","Independently rewrites without fail on rebreeding and checks the sow's condition as well.","Understands that missed rewrites disrupt the schedule, and can teach new staff thorough entry and observation."],"name_vi":"Ghi lại khi phối lại và quan sát lợn nái","kanten_vi":"Mỗi lần phối, phối lại có ghi lại không, không chỉ dựa vào ngày dự sinh mà còn xem tình trạng lợn nái không.","levels_vi":["Quên sửa khi phối lại, chỉ dựa vào ngày dự sinh mà không xem tình trạng lợn nái.","Nếu được chỉ thị thì ghi lại, nhưng còn sót chỗ sửa và thiếu quan sát.","Nếu được chỉ thị thì ghi lại được mỗi lần phối, phối lại một cách cơ bản.","Dù không có chỉ thị vẫn luôn ghi lại khi phối lại, đồng thời xem tình trạng lợn nái.","Hiểu sót ghi lại sẽ gây rối loạn lịch, và có thể hướng dẫn người mới việc ghi chép và quan sát triệt để."],"name_id":"Menulis ulang saat kawin ulang dan mengamati induk babi","kanten_id":"Apakah menulis ulang setiap kali kawin atau kawin ulang, dan tidak menilai hanya dari tanggal perkiraan tetapi juga memeriksa keadaan induk babi?","levels_id":["Lupa memperbaiki catatan saat kawin ulang, menilai hanya dari tanggal perkiraan, dan tidak melihat keadaan induk babi.","Menulis ulang jika diperintah, tetapi masih ada lupa memperbaiki dan kurang mengamati.","Jika diperintah, dapat menulis ulang setiap kali kawin atau kawin ulang secara lengkap.","Tanpa diperintah pun, pasti menulis ulang saat kawin ulang, dan memeriksa keadaan induk babi sekaligus.","Memahami bahwa lupa menulis ulang mengacaukan jadwal, dan dapat mengajarkan kedisiplinan mencatat dan mengamati kepada karyawan baru."]}],"gyomu":"32","name_en":"Farrowing Due-Date Entry","purposeShort_en":"Grasp farrowing timing to prepare housing and staff systematically and detect failed conception early","name_vi":"Ghi ngày dự sinh","purposeShort_vi":"Nắm thời kỳ đẻ để chuẩn bị chuồng và nhân lực có kế hoạch, phát hiện sớm không thụ thai","name_id":"Mencatat perkiraan tanggal melahirkan","purposeShort_id":"Mengetahui waktu melahirkan untuk menyiapkan kandang dan tenaga kerja secara terencana, serta menemukan kegagalan bunting sejak dini"},{"id":"cull-ship","category":"shipping","no":"No.22","name":"廃豚出荷（母豚出し）","purposeShort":"繁殖群を計画的に更新し、母豚に無理をさせず安全に出荷する","aspects":[{"id":"welfare-law","name":"歩様確認と法令遵守","kanten":"歩けない・立てない豚は出荷せず、出荷前に体調・歩様を確認し、絶食時も水を止めないか。","levels":["歩けない豚を出荷し、体調・歩様の確認も絶食時の給水も怠る。","指示があれば確認するが、歩様の見極めや給水管理に漏れがある。","指示があれば体調・歩様をひと通り確認して出荷できる。","指示がなくても歩けない豚を除外し、絶食時も水を止めずに安全に出荷する。","と畜場法・輸送指針を理解し、welfareに配慮した出荷を新人に指導できる。"],"name_en":"Gait Checks and Legal Compliance","kanten_en":"Can they refuse to ship pigs that cannot walk or stand, check condition and gait before shipping, and keep water available during fasting?","levels_en":["Ships pigs that cannot walk, and neglects condition and gait checks and water supply during fasting.","With guidance can check, but misses judging gait or managing water supply.","With guidance can check condition and gait and ship through the basic procedure.","Independently excludes pigs that cannot walk and ships safely with water kept available during fasting.","Understands the Slaughterhouse Act and transport guidelines, and can teach new staff welfare-conscious shipping."],"name_vi":"Kiểm tra dáng đi và tuân thủ pháp luật","kanten_vi":"Có không xuất lợn không đi được, không đứng được; trước khi xuất kiểm tra thể trạng, dáng đi; khi nhịn ăn không cắt nước không.","levels_vi":["Xuất cả lợn không đi được, lơ là kiểm tra thể trạng, dáng đi và cấp nước khi nhịn ăn.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về nhận biết dáng đi và quản lý cấp nước.","Nếu được chỉ thị thì kiểm tra thể trạng, dáng đi và xuất chuồng được cơ bản.","Dù không có chỉ thị vẫn loại trừ lợn không đi được, không cắt nước khi nhịn ăn, xuất chuồng an toàn.","Hiểu luật về lò mổ và hướng dẫn vận chuyển của Nhật Bản, và có thể hướng dẫn người mới cách xuất chuồng có quan tâm đến phúc lợi động vật (welfare)."],"name_id":"Memeriksa cara berjalan dan menaati peraturan","kanten_id":"Apakah tidak mengirim babi yang tidak bisa berjalan atau berdiri, memeriksa kondisi tubuh dan cara berjalan sebelum pengiriman, dan tidak menghentikan air minum saat puasa?","levels_id":["Mengirim babi yang tidak bisa berjalan, dan lalai memeriksa kondisi tubuh dan cara berjalan serta memberi air minum saat puasa.","Memeriksa jika diperintah, tetapi sering lalai menilai cara berjalan dan mengelola air minum.","Jika diperintah, dapat memeriksa kondisi tubuh dan cara berjalan secara lengkap lalu mengirim.","Tanpa diperintah pun, menyisihkan babi yang tidak bisa berjalan, dan mengirim dengan aman tanpa menghentikan air minum saat puasa.","Memahami undang-undang rumah potong hewan dan pedoman pengangkutan, dan dapat mengajarkan pengiriman yang memperhatikan kesejahteraan hewan kepada karyawan baru."]},{"id":"cull-select","name":"廃豚候補の選定と誤出荷防止","kanten":"廃豚選定基準に沿って選び、休薬期間中の治療豚と混同せず、体重・体型を確認できるか。","levels":["休薬中の治療豚と廃豚候補を混同して誤出荷し、体重・体型確認も省く。","指示があれば選定するが、基準の統一や治療豚との区別に漏れがある。","指示があれば選定基準に沿ってひと通り選べる。","指示がなくても基準に沿って選び、治療豚と区別し、体重・体型を確認する。","選定基準と残留違反のリスクを理解し、廃豚選定と誤出荷防止を新人に指導できる。"],"name_en":"Selecting Cull Candidates and Preventing Wrong Shipments","kanten_en":"Can they select by the culling criteria, avoid confusing them with treated pigs in withdrawal, and check weight and body condition?","levels_en":["Confuses treated pigs in withdrawal with cull candidates and ships them by mistake, skipping weight and body-condition checks.","With guidance can select, but misses standardized criteria or the distinction from treated pigs.","With guidance can select by the culling criteria through the basic procedure.","Independently selects by the criteria, distinguishes treated pigs, and checks weight and body condition.","Understands the criteria and the risk of residue violations, and can teach new staff cull selection and wrong-shipment prevention."],"name_vi":"Chọn lợn loại thải và phòng xuất nhầm","kanten_vi":"Có chọn theo tiêu chuẩn chọn lợn loại thải, không nhầm với lợn đang điều trị trong thời gian ngừng thuốc, kiểm tra cân nặng, thể hình không.","levels_vi":["Nhầm lợn điều trị đang trong thời gian ngừng thuốc với lợn loại thải và xuất nhầm, cũng bỏ qua kiểm tra cân nặng, thể hình.","Nếu được chỉ thị thì chọn, nhưng còn thiếu sót về thống nhất tiêu chuẩn và phân biệt với lợn điều trị.","Nếu được chỉ thị thì chọn theo tiêu chuẩn được cơ bản.","Dù không có chỉ thị vẫn chọn theo tiêu chuẩn, phân biệt với lợn điều trị, kiểm tra cân nặng, thể hình.","Hiểu tiêu chuẩn chọn và rủi ro vi phạm tồn dư thuốc, và có thể hướng dẫn người mới cách chọn lợn loại thải và phòng xuất nhầm."],"name_id":"Memilih calon babi afkir dan mencegah salah kirim","kanten_id":"Apakah memilih sesuai kriteria pemilihan babi afkir, tidak mencampuradukkan dengan babi yang masih dalam masa henti obat, dan memeriksa berat serta bentuk badan?","levels_id":["Mencampuradukkan babi dalam masa henti obat dengan calon afkir sehingga salah kirim, dan melewatkan pemeriksaan berat dan bentuk badan.","Memilih jika diperintah, tetapi sering lalai menyeragamkan kriteria dan membedakan dari babi yang diobati.","Jika diperintah, dapat memilih sesuai kriteria pemilihan secara lengkap.","Tanpa diperintah pun, memilih sesuai kriteria, membedakan dari babi yang diobati, dan memeriksa berat serta bentuk badan.","Memahami kriteria pemilihan dan risiko pelanggaran residu obat, dan dapat mengajarkan pemilihan babi afkir dan pencegahan salah kirim kepada karyawan baru."]}],"gyomu":"22","name_en":"Cull Sow Shipping","purposeShort_en":"Renew the breeding herd systematically and ship sows safely without overstraining them","name_vi":"Xuất chuồng lợn loại thải (đưa lợn nái đi)","purposeShort_vi":"Đổi mới đàn sinh sản có kế hoạch, xuất chuồng an toàn không ép lợn nái quá sức","name_id":"Pengiriman babi afkir (mengeluarkan induk babi)","purposeShort_id":"Memperbarui kelompok induk secara terencana, dan mengirim dengan aman tanpa memaksa induk babi"},{"id":"cull-move","category":"shipping","no":"No.23","name":"育成舎へ廃豚移動","purposeShort":"出荷前管理を円滑にする","aspects":[{"id":"isolation-move","name":"他群との接触回避と静かな移動","kanten":"他群との接触による感染拡大を避け、静かに移動して転倒させないか。","levels":["他群との接触を避けず、急かして転倒させ、収容限界を超えて過密にする。","指示があれば移動させるが、接触回避や収容確認に漏れがある。","指示があれば静かにひと通り移動できる。","指示がなくても他群との接触を避け、静かに移動して過密を防ぐ。","移動時の感染・負傷リスクを理解し、安全な廃豚移動を新人に指導できる。"],"name_en":"Avoiding Contact with Other Groups and Quiet Movement","kanten_en":"Can they avoid spreading infection through contact with other groups and move pigs quietly without letting them fall?","levels_en":["Does not avoid contact with other groups, rushes pigs into falls, and overcrowds beyond housing capacity.","With guidance can move pigs, but misses contact avoidance or capacity checks.","With guidance can complete a basic quiet move.","Independently avoids contact with other groups, moves pigs quietly, and prevents overcrowding.","Understands infection and injury risks during movement, and can teach new staff safe cull-sow movement."],"name_vi":"Tránh tiếp xúc với nhóm khác và di chuyển nhẹ nhàng","kanten_vi":"Có tránh lây lan bệnh do tiếp xúc với nhóm khác, di chuyển nhẹ nhàng để lợn không bị ngã không.","levels_vi":["Không tránh tiếp xúc với nhóm khác, hối thúc làm lợn ngã, nhồi quá giới hạn sức chứa gây quá đông.","Nếu được chỉ thị thì di chuyển, nhưng còn thiếu sót về tránh tiếp xúc và kiểm tra sức chứa.","Nếu được chỉ thị thì di chuyển nhẹ nhàng được cơ bản.","Dù không có chỉ thị vẫn tránh tiếp xúc với nhóm khác, di chuyển nhẹ nhàng, tránh quá đông.","Hiểu rủi ro lây nhiễm, bị thương khi di chuyển, và có thể hướng dẫn người mới cách chuyển lợn loại thải an toàn."],"name_id":"Menghindari kontak dengan kelompok lain dan memindah dengan tenang","kanten_id":"Apakah menghindari penyebaran penyakit lewat kontak dengan kelompok lain, dan memindah dengan tenang tanpa membuat babi jatuh?","levels_id":["Tidak menghindari kontak dengan kelompok lain, memburu-buru hingga babi jatuh, dan memasukkan melebihi batas tampung sehingga terlalu padat.","Memindah jika diperintah, tetapi sering lalai menghindari kontak dan memeriksa daya tampung.","Jika diperintah, dapat memindah dengan tenang secara lengkap.","Tanpa diperintah pun, menghindari kontak dengan kelompok lain, memindah dengan tenang, dan mencegah kepadatan berlebih.","Memahami risiko infeksi dan luka saat memindah, dan dapat mengajarkan pemindahan babi afkir yang aman kepada karyawan baru."]},{"id":"move-record-feed","name":"移動の記録と出荷前給餌管理","kanten":"廃豚移動を記録して在庫を合わせ、出荷予定日までの給餌管理を明確にできるか。","levels":["移動を記録せず在庫が合わず、出荷までの給餌管理も曖昧で飼料コストを膨らませる。","指示があれば記録するが、在庫照合や給餌管理に漏れがある。","指示があれば移動をひと通り記録できる。","指示がなくても移動を記録して在庫を合わせ、出荷予定日までの給餌を管理する。","在庫管理と飼料コストの関係を理解し、記録と給餌管理を新人に指導できる。"],"name_en":"Recording Movements and Pre-Shipping Feed Management","kanten_en":"Can they record cull-sow movements to keep inventory matched, and clarify feeding management up to the planned shipping date?","levels_en":["Does not record movements so inventory does not match, and leaves feeding until shipping vague, inflating feed costs.","With guidance can record, but misses inventory verification or feed management.","With guidance can record the movements through the basic routine.","Independently records movements to match inventory and manages feeding up to the planned shipping date.","Understands the relationship between inventory management and feed costs, and can teach new staff recording and feed management."],"name_vi":"Ghi chép di chuyển và quản lý cho ăn trước xuất chuồng","kanten_vi":"Có ghi việc chuyển lợn loại thải để khớp tồn kho, làm rõ việc quản lý cho ăn đến ngày dự kiến xuất chuồng không.","levels_vi":["Không ghi di chuyển làm lệch tồn kho, quản lý cho ăn đến khi xuất cũng mơ hồ, làm tăng chi phí thức ăn.","Nếu được chỉ thị thì ghi, nhưng còn thiếu sót về đối chiếu tồn kho và quản lý cho ăn.","Nếu được chỉ thị thì ghi việc di chuyển được cơ bản.","Dù không có chỉ thị vẫn ghi việc di chuyển để khớp tồn kho, quản lý cho ăn đến ngày dự kiến xuất chuồng.","Hiểu quan hệ giữa quản lý tồn kho và chi phí thức ăn, và có thể hướng dẫn người mới việc ghi chép và quản lý cho ăn."],"name_id":"Mencatat pemindahan dan mengelola pakan sebelum pengiriman","kanten_id":"Apakah dapat mencatat pemindahan babi afkir agar stok cocok, dan menjelaskan dengan jelas pengelolaan pakan sampai tanggal rencana pengiriman?","levels_id":["Tidak mencatat pemindahan sehingga stok tidak cocok, dan pengelolaan pakan sampai pengiriman kabur sehingga biaya pakan membengkak.","Mencatat jika diperintah, tetapi sering lalai mencocokkan stok dan mengelola pakan.","Jika diperintah, dapat mencatat pemindahan secara lengkap.","Tanpa diperintah pun, mencatat pemindahan agar stok cocok, dan mengelola pemberian pakan sampai tanggal rencana pengiriman.","Memahami hubungan pengelolaan stok dengan biaya pakan, dan dapat mengajarkan pencatatan dan pengelolaan pakan kepada karyawan baru."]}],"gyomu":"23","name_en":"Moving Cull Sows to the Grower House","purposeShort_en":"Keep pre-shipping management running smoothly","name_vi":"Chuyển lợn loại thải sang chuồng lợn choai","purposeShort_vi":"Giúp việc quản lý trước xuất chuồng thuận lợi","name_id":"Memindahkan babi afkir ke kandang grower","purposeShort_id":"Melancarkan pengelolaan sebelum pengiriman"},{"id":"cull-prep","category":"shipping","no":"No.28","name":"廃豚準備","purposeShort":"出荷作業を安全に進める","aspects":[{"id":"final-check","name":"歩様の最終確認と無理のない誘導","kanten":"体調と歩様を最終確認し、歩行困難豚への無理な誘導を避け、急かして暴れさせないか。","levels":["歩行困難豚を無理に誘導し、出荷当日に急かして暴れさせ打撲・PSE肉を招く。","指示があれば確認するが、歩様の最終確認や誘導の丁寧さに漏れがある。","指示があれば体調・歩様をひと通り最終確認できる。","指示がなくても歩様を最終確認し、無理な誘導を避けて落ち着いて誘導する。","PSE肉・打撲の原因を理解し、安全な誘導と最終確認を新人に指導できる。"],"name_en":"Final Gait Check and Unforced Handling","kanten_en":"Can they make a final check of condition and gait, avoid forcing pigs with walking difficulty, and drive without rushing pigs into panic?","levels_en":["Forces pigs with walking difficulty and rushes pigs on shipping day into panic, causing bruises and PSE meat.","With guidance can check, but misses the final gait check or careful handling.","With guidance can make the final check of condition and gait through the basic routine.","Independently makes the final gait check and drives pigs calmly without forcing them.","Understands the causes of PSE meat and bruising, and can teach new staff safe handling and final checks."],"name_vi":"Kiểm tra dáng đi lần cuối và dẫn lợn không ép buộc","kanten_vi":"Có kiểm tra lần cuối thể trạng và dáng đi, tránh ép dẫn lợn đi lại khó khăn, không hối thúc làm lợn hoảng loạn không.","levels_vi":["Ép dẫn lợn đi lại khó khăn, hối thúc trong ngày xuất chuồng làm lợn hoảng loạn, gây bầm dập, thịt PSE (nhạt màu, mềm, rỉ nước).","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về kiểm tra dáng đi lần cuối và sự nhẹ nhàng khi dẫn.","Nếu được chỉ thị thì kiểm tra lần cuối thể trạng, dáng đi được cơ bản.","Dù không có chỉ thị vẫn kiểm tra dáng đi lần cuối, tránh ép buộc, dẫn lợn một cách bình tĩnh.","Hiểu nguyên nhân của thịt PSE và bầm dập, và có thể hướng dẫn người mới cách dẫn an toàn và kiểm tra lần cuối."],"name_id":"Pemeriksaan akhir cara berjalan dan penggiringan tanpa paksaan","kanten_id":"Apakah memeriksa terakhir kondisi tubuh dan cara berjalan, tidak memaksa menggiring babi yang sulit berjalan, dan tidak memburu-buru hingga babi mengamuk?","levels_id":["Memaksa menggiring babi yang sulit berjalan, memburu-buru pada hari pengiriman hingga babi mengamuk, sehingga terjadi memar dan daging PSE (daging pucat lembek berair).","Memeriksa jika diperintah, tetapi sering lalai pada pemeriksaan akhir cara berjalan dan kehalusan penggiringan.","Jika diperintah, dapat memeriksa terakhir kondisi tubuh dan cara berjalan secara lengkap.","Tanpa diperintah pun, memeriksa terakhir cara berjalan, dan menggiring dengan tenang tanpa paksaan.","Memahami penyebab daging PSE dan memar, dan dapat mengajarkan penggiringan yang aman dan pemeriksaan akhir kepada karyawan baru."]},{"id":"fast-notify","name":"絶食タイミングと業者への事前連絡","kanten":"絶食開始タイミングを守り、出荷業者へ頭数・個体情報を事前連絡できるか。","levels":["絶食開始を誤って糞汚染や体重ロスを招き、業者への事前連絡も漏らして積込みを混乱させる。","指示があれば準備するが、絶食時期や事前連絡に漏れがある。","指示があれば絶食のタイミングをひと通り守れる。","指示がなくても絶食開始を適切に管理し、業者へ頭数・個体情報を事前連絡する。","絶食管理と積込みの段取りを理解し、事前連絡と準備を新人に指導できる。"],"name_en":"Fasting Timing and Advance Notice to the Hauler","kanten_en":"Can they keep the fasting start time and notify the shipping company of head counts and individual information in advance?","levels_en":["Gets the fasting start wrong, causing fecal contamination and weight loss, and skips advance notice to the hauler, throwing loading into confusion.","With guidance can prepare, but misses the fasting timing or the advance notice.","With guidance can keep the fasting timing through the basic routine.","Independently manages the fasting start properly and notifies the hauler of head counts and individual information in advance.","Understands fasting management and loading logistics, and can teach new staff advance notice and preparation."],"name_vi":"Thời điểm nhịn ăn và liên hệ trước với đơn vị vận chuyển","kanten_vi":"Có giữ đúng thời điểm bắt đầu nhịn ăn, liên hệ trước với đơn vị xuất chuồng về số con và thông tin cá thể không.","levels_vi":["Sai thời điểm bắt đầu nhịn ăn gây bẩn phân, hụt cân, cũng quên liên hệ trước với đơn vị vận chuyển làm rối việc chất lên xe.","Nếu được chỉ thị thì chuẩn bị, nhưng còn thiếu sót về thời điểm nhịn ăn và liên hệ trước.","Nếu được chỉ thị thì giữ đúng thời điểm nhịn ăn được cơ bản.","Dù không có chỉ thị vẫn quản lý phù hợp thời điểm bắt đầu nhịn ăn, liên hệ trước với đơn vị về số con, thông tin cá thể.","Hiểu việc quản lý nhịn ăn và trình tự chất lên xe, và có thể hướng dẫn người mới việc liên hệ trước và chuẩn bị."],"name_id":"Waktu mulai puasa dan pemberitahuan awal ke pengangkut","kanten_id":"Apakah menepati waktu mulai puasa, dan memberitahukan jumlah ekor dan data individu ke perusahaan pengangkut lebih dulu?","levels_id":["Salah waktu mulai puasa sehingga terjadi pencemaran kotoran dan kehilangan berat, dan lupa memberi tahu pengangkut sehingga pemuatan kacau.","Menyiapkan jika diperintah, tetapi sering lalai soal waktu puasa dan pemberitahuan awal.","Jika diperintah, dapat menepati waktu puasa secara lengkap.","Tanpa diperintah pun, mengelola mulai puasa dengan tepat, dan memberitahukan jumlah ekor dan data individu ke pengangkut lebih dulu.","Memahami pengelolaan puasa dan urutan pemuatan, dan dapat mengajarkan pemberitahuan awal dan persiapan kepada karyawan baru."]}],"gyomu":"28","name_en":"Cull Sow Preparation","purposeShort_en":"Carry out shipping work safely","name_vi":"Chuẩn bị lợn loại thải (trước khi xuất chuồng)","purposeShort_vi":"Tiến hành công việc xuất chuồng an toàn","name_id":"Persiapan babi afkir (sebelum pengiriman)","purposeShort_id":"Menjalankan pekerjaan pengiriman dengan aman"}]};
